INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49929f71-f38b-4979-bf87-51b84379a94d', '寄上吳王三首 一', '寄上吳王三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淮王愛八公，攜手綠雲中。","小子忝枝葉，亦攀丹桂叢。","謬以詞賦重，而將枚馬同。","何日背淮水，東之觀土風。"]', '["淮王愛八公，携手綠云中。","小子忝枝葉，亦攀丹桂叢。","謬以词賦重，而將枚马同。","何日背淮水，东之观土风。"]', '诗', 'shi', '', NULL, '寄上吳王三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f4418dd-2978-46b9-ba18-13e7b821d066', '寄上吳王三首 二', '寄上吳王三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["坐嘯廬江靜，閑聞進玉觴。","去時無一物，東壁挂胡牀。"]', '["坐嘯廬江静，闲闻進玉觴。","去时無一物，东壁挂胡牀。"]', '诗', 'shi', '', NULL, '寄上吳王三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9967d42-821c-4429-8d49-36b98557e70b', '寄上吳王三首 三', '寄上吳王三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["英明廬江守，聲譽廣平籍。","灑掃黃金臺，招邀青雲客。","客曾與天通，出入清禁中。","襄王憐宋玉，願入蘭臺宮。"]', '["英明廬江守，声譽廣平籍。","灑掃黄金台，招邀青云客。","客曾與天通，出入清禁中。","襄王怜宋玉，願入蘭台宮。"]', '诗', 'shi', '', NULL, '寄上吳王三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e574e8-1a27-4f34-8158-66a8548ddc00', '秋日魯郡堯祠亭上宴別杜補闕范侍御', '秋日魯郡堯祠亭上宴別杜補闕范侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我覺秋興逸，誰云秋興悲。","山將落日去，水與晴空宜。","魯酒白玉壺，送行駐金羈。","歇鞍憩古木，解帶挂橫枝。","歌鼓川上亭，曲度神飆吹。","雲歸碧海夕，鴈沒青天時。","相失各萬里，茫然空爾思。"]', '["我覺秋兴逸，誰云秋兴悲。","山將落日去，水與晴空宜。","魯酒白玉壺，送行駐金羈。","歇鞍憩古木，解带挂橫枝。","歌鼓川上亭，曲度神飆吹。","云归碧海夕，鴈沒青天时。","相失各万里，茫然空爾思。"]', '诗', 'shi', '', NULL, '秋日魯郡堯祠亭上宴別杜補闕范侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f58bb3c-db82-4f06-8ec1-07d6aba4512a', '別魯頌', '別魯頌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["誰道泰山高，下却魯連節。","誰云秦軍衆，摧却魯連舌。","獨立天地間，清風灑蘭雪。","夫子還倜儻，攻文繼前烈。","錯落石上松，無爲秋霜折。","贈言鏤寶刀，千歲庶不滅。"]', '["誰道泰山高，下却魯連節。","誰云秦軍衆，摧却魯連舌。","独立天地间，清风灑蘭雪。","夫子還倜儻，攻文繼前烈。","錯落石上松，無爲秋霜折。","贈言鏤寶刀，千歲庶不滅。"]', '诗', 'shi', '', NULL, '別魯頌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e50c7847-073b-4256-8126-719dc53ecc72', '別中都明府兄', '別中都明府兄', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾兄詩酒繼陶君，試宰中都天下聞。","東樓喜奉連枝會，南陌愁爲落葉分。","城隅淥水明秋日，海上青山隔暮雲。","取醉不辭留夜月，鴈行中斷惜離羣。"]', '["吾兄诗酒繼陶君，試宰中都天下闻。","东楼喜奉連枝會，南陌愁爲落葉分。","城隅淥水明秋日，海上青山隔暮云。","取醉不辞留夜月，鴈行中斷惜離羣。"]', '诗', 'shi', '', NULL, '別中都明府兄 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606d0bd8-31d2-4a7a-97ee-341956e7be60', '夢遊天姥吟留別', '梦游天姥吟留別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海客談瀛洲，煙濤微茫信難求。","越人語天姥，雲霓明滅或可覩。","天姥連天向天橫，勢拔五嶽掩赤城。","天台四萬八千丈，對此欲倒東南傾。","我欲因之夢吳越，一夜飛度鏡湖月。","湖月照我影，送我至剡溪。","謝公宿處今尚在，淥水蕩漾清猨啼。","脚著謝公屐，身登青雲梯。","半壁見海日，空中聞天雞。","千巖萬轉路不定，迷花倚石忽已暝。","熊咆龍吟殷巖泉，慄深林兮驚層巔。","雲青青兮欲雨，水澹澹兮生煙。","列缺霹靂，丘巒崩摧。","洞天石扇，訇然中開。","青冥浩蕩不見底，日月照耀金銀臺。","霓爲衣兮風爲馬，雲之君兮紛紛而來下。","虎鼓瑟兮鸞迴車，仙之人兮列如麻。","忽魂悸以魄動，怳驚起而長嗟。","惟覺時之枕席，失向來之煙霞。","世間行樂亦如此，古來萬事東流水。","別君去時何時還，且放白鹿青崖間，須行即騎訪名山。","安能摧眉折腰事權貴？","使我不得開心顏。"]', '["海客談瀛洲，煙濤微茫信难求。","越人語天姥，云霓明滅或可覩。","天姥連天向天橫，勢拔五嶽掩赤城。","天台四万八千丈，对此欲倒东南傾。","我欲因之梦吳越，一夜飞度镜湖月。","湖月照我影，送我至剡溪。","謝公宿处今尚在，淥水蕩漾清猨啼。","脚著謝公屐，身登青云梯。","半壁见海日，空中闻天雞。","千巖万轉路不定，迷花倚石忽已暝。","熊咆龙吟殷巖泉，慄深林兮驚層巔。","云青青兮欲雨，水澹澹兮生煙。","列缺霹靂，丘巒崩摧。","洞天石扇，訇然中开。","青冥浩蕩不见底，日月照耀金銀台。","霓爲衣兮风爲马，云之君兮紛紛而来下。","虎鼓瑟兮鸾迴车，仙之人兮列如麻。","忽魂悸以魄动，怳驚起而长嗟。","惟覺时之枕席，失向来之煙霞。","世间行乐亦如此，古来万事东流水。","別君去时何时還，且放白鹿青崖间，須行即騎訪名山。","安能摧眉折腰事權貴？","使我不得开心顏。"]', '诗', 'shi', '', NULL, '夢遊天姥吟留別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2213a7-0259-4177-9efd-9649879e36f8', '留別曹南羣官之江南', '留別曹南羣官之江南', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我昔釣白龍，放龍溪水傍。","道成本欲去，揮手凌蒼蒼。","時來不關人，談笑遊軒皇。","獻納少成事，歸休辭建章。","十年罷西笑，覽鏡如秋霜。","閉劒琉璃匣，鍊丹紫翠房。","身佩豁落圖，腰垂虎鞶囊。","仙人駕彩鳳，志在窮遐荒。","戀子四五人，裴回未翱翔。","東流送白日，驟歌蘭蕙芳。","仙宮兩無從，人間久摧藏。","范蠡說句踐，屈平去懷王。","飄飄紫霞心，流浪憶江鄉。","愁爲萬里別，復此一銜觴。","淮水帝王州，金陵繞丹陽。","樓臺照海色，衣馬搖川光。","及此北望君，相思淚成行。","朝雲落夢渚，瑤草空高堂。","帝子隔洞庭，青楓滿瀟湘。","懷君路綿邈，覽古情淒涼。","登岳眺百川，杳然萬恨長。","知戀峨眉去，弄景偶騎羊。"]', '["我昔釣白龙，放龙溪水傍。","道成本欲去，揮手凌蒼蒼。","时来不关人，談笑游軒皇。","獻納少成事，归休辞建章。","十年罷西笑，覽镜如秋霜。","閉劒琉璃匣，鍊丹紫翠房。","身佩豁落圖，腰垂虎鞶囊。","仙人駕彩鳳，志在窮遐荒。","戀子四五人，裴回未翱翔。","东流送白日，驟歌蘭蕙芳。","仙宮兩無從，人间久摧藏。","范蠡说句踐，屈平去懷王。","飄飄紫霞心，流浪憶江乡。","愁爲万里別，复此一銜觴。","淮水帝王州，金陵繞丹陽。","楼台照海色，衣马搖川光。","及此北望君，相思泪成行。","朝云落梦渚，瑤草空高堂。","帝子隔洞庭，青楓满瀟湘。","懷君路綿邈，覽古情淒涼。","登岳眺百川，杳然万恨长。","知戀峨眉去，弄景偶騎羊。"]', '诗', 'shi', '', NULL, '留別曹南羣官之江南 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ce20900-4e76-49be-9a95-da3529e1b5a9', '留別于十一兄逖裴十三遊塞垣', '留別于十一兄逖裴十三游塞垣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["太公渭川水，李斯上蔡門。","釣周獵秦安黎元，小魚㕙兔何足言。","天張雲卷有時節，吾徒莫嘆羝觸藩。","于公白首大梁野，使人悵望何可論。","既知朱亥爲壯士，且願束心秋毫裏。","秦趙虎爭血中原，當去抱關救公子。","裴生覽千古，龍鸞炳文章。","悲吟雨雪動林木，放書輟劒思高堂。","勸爾一杯酒，拂爾裘上霜。","爾爲我楚舞，吾爲爾楚歌。","且探虎穴向沙漠，鳴鞭走馬凌黃河。","耻作易水別，臨岐淚滂沱。"]', '["太公渭川水，李斯上蔡门。","釣周獵秦安黎元，小鱼㕙兔何足言。","天張云卷有时節，吾徒莫嘆羝觸藩。","于公白首大梁野，使人悵望何可論。","既知朱亥爲壯士，且願束心秋毫裏。","秦趙虎爭血中原，當去抱关救公子。","裴生覽千古，龙鸾炳文章。","悲吟雨雪动林木，放书輟劒思高堂。","勸爾一杯酒，拂爾裘上霜。","爾爲我楚舞，吾爲爾楚歌。","且探虎穴向沙漠，鳴鞭走马凌黄河。","耻作易水別，臨岐泪滂沱。"]', '诗', 'shi', '', NULL, '留別于十一兄逖裴十三遊塞垣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3b14f9d-89e4-4363-85b1-612171025de6', '留別王司馬嵩', '留別王司马嵩', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯連賣談笑，豈是顧千金。","陶朱雖相越，本有五湖心。","余亦南陽子，時爲梁甫吟。","蒼山容偃蹇，白日惜頹侵。","願一佐明主，功成還舊林。","西來何所爲，孤劒託知音。","鳥愛碧山遠，魚遊滄海深。","呼鷹過上蔡，賣畚向嵩岑。","他日閑相訪，丘中有素琴。"]', '["魯連賣談笑，豈是顧千金。","陶朱雖相越，本有五湖心。","余亦南陽子，时爲梁甫吟。","蒼山容偃蹇，白日惜頹侵。","願一佐明主，功成還旧林。","西来何所爲，孤劒託知音。","鸟愛碧山远，鱼游滄海深。","呼鷹過上蔡，賣畚向嵩岑。","他日闲相訪，丘中有素琴。"]', '诗', 'shi', '', NULL, '留別王司馬嵩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51967264-2d27-486f-b782-23d9407527a0', '夜別張五', '夜別張五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾多張公子，別酌酣高堂。","聽歌舞銀燭，把酒輕羅裳。","橫笛弄秋月，琵琶彈陌桑。","龍泉解錦帶，爲爾傾千觴。"]', '["吾多張公子，別酌酣高堂。","听歌舞銀燭，把酒轻羅裳。","橫笛弄秋月，琵琶彈陌桑。","龙泉解錦带，爲爾傾千觴。"]', '诗', 'shi', '', NULL, '夜別張五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b538c239-a55b-40b2-8845-43e7eb0e45ae', '魏郡別蘇明府因北遊', '魏郡別蘇明府因北游', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魏都接燕趙，美女誇芙蓉。","淇水流碧玉，舟車日奔衝。","青樓夾兩岸，萬室喧歌鍾。","天下稱豪貴，遊此每相逢。","洛陽蘇季子，劒戟森詞鋒。","六印雖未佩，軒車若飛龍。","黃金數百鎰，白璧有幾雙。","散盡空掉臂，高歌賦還邛。","落魄乃如此，何人不相從。","遠別隔兩河，雲山杳千重。","何時更杯酒，再得論心胸。"]', '["魏都接燕趙，美女誇芙蓉。","淇水流碧玉，舟车日奔衝。","青楼夾兩岸，万室喧歌鍾。","天下稱豪貴，游此每相逢。","洛陽蘇季子，劒戟森词鋒。","六印雖未佩，軒车若飞龙。","黄金數百鎰，白璧有幾雙。","散尽空掉臂，高歌賦還邛。","落魄乃如此，何人不相從。","远別隔兩河，云山杳千重。","何时更杯酒，再得論心胸。"]', '诗', 'shi', '', NULL, '魏郡別蘇明府因北遊 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86520d8e-c92d-4500-a5b3-faedeb0faa87', '留別西河劉少府', '留別西河劉少府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋髮已種種，所爲竟無成。","閑傾魯壺酒，笑對劉公榮。","謂我是方朔，人間落歲星。","白衣千萬乘，何事去天庭。","君亦不得意，高歌羨鴻冥。","世人若醯雞，安可識梅生。","雖爲刀筆吏，緬懷在赤城。","余亦如流萍，隨波樂休明。","自有兩少妾，雙騎駿馬行。","東山春酒綠，歸隱謝浮名。"]', '["秋髮已種種，所爲竟無成。","闲傾魯壺酒，笑对劉公榮。","謂我是方朔，人间落歲星。","白衣千万乘，何事去天庭。","君亦不得意，高歌羨鴻冥。","世人若醯雞，安可識梅生。","雖爲刀笔吏，緬懷在赤城。","余亦如流萍，隨波乐休明。","自有兩少妾，雙騎駿马行。","东山春酒綠，归隐謝浮名。"]', '诗', 'shi', '', NULL, '留別西河劉少府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e3e922b-bebf-49df-8c01-ba3334bbdc03', '潁陽別元丹丘之淮陽', '潁陽別元丹丘之淮陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾將元夫子，異姓爲天倫。","本無軒裳契，素以煙霞親。","嘗恨迫世網，銘意俱未伸。","松柏雖寒苦，羞逐桃李春。","悠悠市朝間，玉顏日緇磷。","所失重山岳，所得輕埃塵。","精魄漸蕪穢，衰老相憑因。","我有錦囊訣，可以持君身。","當餐黃金藥，去爲紫陽賓。","萬事難並立，百年猶崇晨。","別爾東南去，悠悠多悲辛。","前志庶不易，遠途期所遵。","已矣歸去來，白雲飛天津。"]', '["吾將元夫子，異姓爲天倫。","本無軒裳契，素以煙霞親。","嘗恨迫世網，銘意俱未伸。","松柏雖寒苦，羞逐桃李春。","悠悠市朝间，玉顏日緇磷。","所失重山岳，所得轻埃塵。","精魄漸蕪穢，衰老相憑因。","我有錦囊訣，可以持君身。","當餐黄金藥，去爲紫陽賓。","万事难並立，百年猶崇晨。","別爾东南去，悠悠多悲辛。","前志庶不易，远途期所遵。","已矣归去来，白云飞天津。"]', '诗', 'shi', '', NULL, '潁陽別元丹丘之淮陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b0cbd3-a3af-4571-b177-8b448f32a91a', '留別廣陵諸公', '留別廣陵諸公', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["憶昔作少年，結交趙與燕。","金羈絡駿馬，錦帶橫龍泉。","寸心無疑事，所向非徒然。","晚節覺此疎，獵精草太玄。","空名束壯士，薄俗棄高賢。","中回聖明顧，揮翰凌雲煙。","騎虎不敢下，攀龍忽墮天。","還家守清真，孤潔勵秋蟬。","鍊丹費火石，採藥窮山川。","臥海不關人，租稅遼東田。","乘興忽復起，櫂歌溪中船。","臨醉謝葛强，山公欲倒鞭。","狂歌自此別，垂釣滄浪前。"]', '["憶昔作少年，結交趙與燕。","金羈絡駿马，錦带橫龙泉。","寸心無疑事，所向非徒然。","晚節覺此疎，獵精草太玄。","空名束壯士，薄俗棄高賢。","中回聖明顧，揮翰凌云煙。","騎虎不敢下，攀龙忽墮天。","還家守清真，孤潔勵秋蟬。","鍊丹費火石，採藥窮山川。","臥海不关人，租稅遼东田。","乘兴忽复起，櫂歌溪中船。","臨醉謝葛强，山公欲倒鞭。","狂歌自此別，垂釣滄浪前。"]', '诗', 'shi', '', NULL, '留別廣陵諸公 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a0c773-86ba-48c4-8e39-9465c603606b', '廣陵贈別', '廣陵贈別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉瓶沽美酒，數里送君還。","繫馬垂楊下，銜盃大道間。","天邊看淥水，海上見青山。","興罷各分袂，何須醉別顏。"]', '["玉瓶沽美酒，數里送君還。","繫马垂楊下，銜盃大道间。","天邊看淥水，海上见青山。","兴罷各分袂，何須醉別顏。"]', '诗', 'shi', '', NULL, '廣陵贈別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a68e6197-cce4-4674-920e-ac5dd54ab6f5', '感時留別從兄徐王延年從弟延陵', '感时留別從兄徐王延年從弟延陵', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天籟何參差，噫然大塊吹。","玄元包橐籥，紫氣何逶迤。","七葉運皇化，千齡光本支。","仙風生指樹，大雅歌螽斯。","諸王若鸞虬，肅穆列藩維。","哲兄錫茅土，聖代羅榮滋。","九卿領徐方，七步繼陳思。","伊昔全盛日，雄豪動京師。","冠劒朝鳳闕，樓船侍龍池。","鼓鐘出朱邸，金翠照丹墀。","君王一顧盼，選色獻蛾眉。","列戟十八年，未曾輙遷移。","大臣小喑鳴，謫竄天南垂。","長沙不足舞，貝錦且成詩。","佐郡浙江西，病閑絕驅馳。","階軒日苔蘚，鳥雀噪簷帷。","時乘平肩輿，出入畏人知。","北宅聊偃憩，歡愉恤惸嫠。","羞言梁苑地，烜赫耀旌旗。","兄弟八九人，吳秦各分離。","太賢達機兆，豈獨慮安危。","小子謝麟閣，雁行忝肩隨。","令弟字延陵，鳳毛出天姿。","清英神仙骨，芬馥茝蘭蕤。","夢得春草句，將非惠連誰。","深心紫河車，與我特相宜。","金膏猶罔象，玉液尚磷緇。","伏枕寄賓館，宛同清漳湄。","藥物多見饋，珍羞亦兼之。","誰道溟渤深，猶言淺恩慈。","鳴蟬遊子意，促織念歸期。","驕陽何太赫，海水爍龍龜。","百川盡凋枯，舟檝閣中逵。","策馬搖涼月，通宵出郊圻。","泣別目眷眷，傷心步遲遲。","願言保明德，王室佇清夷。","摻袂何所道，援毫投此辭。"]', '["天籟何參差，噫然大塊吹。","玄元包橐籥，紫氣何逶迤。","七葉運皇化，千齡光本支。","仙风生指樹，大雅歌螽斯。","諸王若鸾虬，肅穆列藩維。","哲兄錫茅土，聖代羅榮滋。","九卿領徐方，七步繼陳思。","伊昔全盛日，雄豪动京師。","冠劒朝鳳闕，楼船侍龙池。","鼓鐘出朱邸，金翠照丹墀。","君王一顧盼，選色獻蛾眉。","列戟十八年，未曾輙遷移。","大臣小喑鳴，謫竄天南垂。","长沙不足舞，貝錦且成诗。","佐郡浙江西，病闲絕驱驰。","階軒日苔蘚，鸟雀噪簷帷。","时乘平肩輿，出入畏人知。","北宅聊偃憩，歡愉恤惸嫠。","羞言梁苑地，烜赫耀旌旗。","兄弟八九人，吳秦各分離。","太賢達機兆，豈独慮安危。","小子謝麟閣，雁行忝肩隨。","令弟字延陵，鳳毛出天姿。","清英神仙骨，芬馥茝蘭蕤。","梦得春草句，將非惠連誰。","深心紫河车，與我特相宜。","金膏猶罔象，玉液尚磷緇。","伏枕寄賓館，宛同清漳湄。","藥物多见饋，珍羞亦兼之。","誰道溟渤深，猶言淺恩慈。","鳴蟬游子意，促织念归期。","驕陽何太赫，海水爍龙龟。","百川尽凋枯，舟檝閣中逵。","策马搖涼月，通宵出郊圻。","泣別目眷眷，傷心步遲遲。","願言保明德，王室佇清夷。","摻袂何所道，援毫投此辞。"]', '诗', 'shi', '', NULL, '感時留別從兄徐王延年從弟延陵 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c61ac26-7837-467a-8c85-c3178010a31f', '別儲邕之剡中', '別儲邕之剡中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["借問剡中道，東南指越鄉。","舟從廣陵去，水入會稽長。","竹色溪下綠，荷花鏡裏香。","辭君向天姥，拂石臥秋霜。"]', '["借问剡中道，东南指越乡。","舟從廣陵去，水入會稽长。","竹色溪下綠，荷花镜裏香。","辞君向天姥，拂石臥秋霜。"]', '诗', 'shi', '', NULL, '別儲邕之剡中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e2b06f-39de-4867-9086-77efbdff12fb', '留別金陵諸公', '留別金陵諸公', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海水昔飛動，三龍紛戰爭。","鍾山危波瀾，傾側駭奔鯨。","黃旗一掃蕩，割壤開吳京。","六代更霸王，遺跡見都城。","至今秦淮間，禮樂秀羣英。","地扇鄒魯學，詩騰顏謝名。","五月金陵西，祖余白下亭。","欲尋廬峰頂，先遶漢水行。","香爐紫煙滅，瀑布落太清。","若攀星辰去，揮手緬含情。"]', '["海水昔飞动，三龙紛戰爭。","鍾山危波瀾，傾側駭奔鯨。","黄旗一掃蕩，割壤开吳京。","六代更霸王，遺跡见都城。","至今秦淮间，禮乐秀羣英。","地扇鄒魯学，诗腾顏謝名。","五月金陵西，祖余白下亭。","欲尋廬峰頂，先遶漢水行。","香爐紫煙滅，瀑布落太清。","若攀星辰去，揮手緬含情。"]', '诗', 'shi', '', NULL, '留別金陵諸公 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ce3da3-9327-4909-997b-c7804ecb4796', '口號', '口號', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["食出野田美，酒臨遠水傾。","東流若未盡，應見別離情。"]', '["食出野田美，酒臨远水傾。","东流若未尽，應见別離情。"]', '诗', 'shi', '', NULL, '口號 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('809ad73b-9a8e-436e-9874-f9295b624af0', '金陵酒肆留別', '金陵酒肆留別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["風吹柳花滿店香，吳姬壓酒喚客嘗。","金陵子弟來相送，欲行不行各盡觴。","請君試問東流水，別意與之誰短長。"]', '["风吹柳花满店香，吳姬壓酒喚客嘗。","金陵子弟来相送，欲行不行各尽觴。","請君試问东流水，別意與之誰短长。"]', '诗', 'shi', '', NULL, '金陵酒肆留別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d470a73-2f50-4fe4-b3f3-cb8951b47fc0', '金陵白下亭留別', '金陵白下亭留別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["驛亭三楊樹，正當白下門。","吳煙暝長條，漢水齧古根。","向來送行處，迴首阻笑言。","別後若見之，爲余一攀翻。"]', '["驛亭三楊樹，正當白下门。","吳煙暝长條，漢水齧古根。","向来送行处，迴首阻笑言。","別後若见之，爲余一攀翻。"]', '诗', 'shi', '', NULL, '金陵白下亭留別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('088d7e4e-8670-4caa-8790-60b58a2480a3', '別東林寺僧', '別东林寺僧', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["東林送客處，月出白猨啼。","笑別廬山遠，何煩過虎溪。"]', '["东林送客处，月出白猨啼。","笑別廬山远，何煩過虎溪。"]', '诗', 'shi', '', NULL, '別東林寺僧 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087750d7-a87c-4a98-a086-ca8076f48253', '竄夜郎於烏江留別宗十六璟', '竄夜郎於烏江留別宗十六璟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君家全盛日，台鼎何陸離。","斬鼇翼媧皇，鍊石補天維。","一迴日月顧，三入鳳皇池。","失勢青門傍，種瓜復幾時。","猶會衆賓客，三千光路岐。","皇恩雪憤懣，松柏含榮滋。","我非東牀人，令姊忝齊眉。","浪跡未出世，空名動京師。","適遭雲羅解，翻謫夜郎悲。","拙妻莫邪劒，及此二龍隨。","慙君湍波苦，千里遠從之。","白帝曉猨斷，黃牛過客遲。","遙瞻明月峽，西去益相思。"]', '["君家全盛日，台鼎何陸離。","斬鼇翼媧皇，鍊石補天維。","一迴日月顧，三入鳳皇池。","失勢青门傍，種瓜复幾时。","猶會衆賓客，三千光路岐。","皇恩雪憤懣，松柏含榮滋。","我非东牀人，令姊忝齊眉。","浪跡未出世，空名动京師。","適遭云羅解，翻謫夜郎悲。","拙妻莫邪劒，及此二龙隨。","慙君湍波苦，千里远從之。","白帝晓猨斷，黄牛過客遲。","遙瞻明月峽，西去益相思。"]', '诗', 'shi', '', NULL, '竄夜郎於烏江留別宗十六璟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcd63f19-0a2b-447c-87f1-f19c120d8d8f', '留別龔處士', '留別龔处士', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["龔子棲閑地，都無人世喧。","柳深陶令宅，竹暗辟疆園。","我去黃牛峽，遙愁白帝猨。","贈君卷葹草，心斷竟何言。"]', '["龔子棲闲地，都無人世喧。","柳深陶令宅，竹暗辟疆园。","我去黄牛峽，遙愁白帝猨。","贈君卷葹草，心斷竟何言。"]', '诗', 'shi', '', NULL, '留別龔處士 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('660e8871-459a-4d4c-861a-997c1e174eb4', '贈別鄭判官', '贈別鄭判官', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["竄逐勿復哀，慚君問寒灰。","浮雲本無意，吹落章華臺。","遠別淚空盡，長愁心已摧。","二年吟澤畔，顦顇幾時迴。"]', '["竄逐勿复哀，慚君问寒灰。","浮云本無意，吹落章华台。","远別泪空尽，长愁心已摧。","二年吟澤畔，顦顇幾时迴。"]', '诗', 'shi', '', NULL, '贈別鄭判官 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43a4767-2240-44b7-8d5b-c2acdc689839', '黃鶴樓送孟浩然之廣陵', '黄鹤楼送孟浩然之廣陵', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["故人西辭黃鶴樓，煙花三月下揚州。","孤帆遠影碧山盡，唯見長江天際流。"]', '["故人西辞黄鹤楼，煙花三月下揚州。","孤帆远影碧山尽，唯见长江天際流。"]', '诗', 'shi', '', NULL, '黃鶴樓送孟浩然之廣陵 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a02a999-6ea6-4a50-bc53-90b665f10897', '將遊衡嶽過漢陽雙松亭留別族弟浮屠談皓', '將游衡嶽過漢陽雙松亭留別族弟浮屠談皓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦欺趙氏璧，却入邯鄲宮。","本是楚家玉，還來荆山中。","丹彩瀉滄溟，精輝凌白虹。","青蠅一相點，流落此時同。","卓絕道門秀，談玄乃支公。","延蘿結幽居，剪竹繞芳叢。","涼花拂戶牖，天籟鳴虛空。","憶我初來時，蒲萄開景風。","今茲大火落，秋葉黃梧桐。","水色夢沅湘，長沙去何窮。","寄書訪衡嶠，但與南飛鴻。"]', '["秦欺趙氏璧，却入邯鄲宮。","本是楚家玉，還来荆山中。","丹彩瀉滄溟，精輝凌白虹。","青蠅一相点，流落此时同。","卓絕道门秀，談玄乃支公。","延蘿結幽居，剪竹繞芳叢。","涼花拂戶牖，天籟鳴虛空。","憶我初来时，蒲萄开景风。","今茲大火落，秋葉黄梧桐。","水色梦沅湘，长沙去何窮。","寄书訪衡嶠，但與南飞鴻。"]', '诗', 'shi', '', NULL, '將遊衡嶽過漢陽雙松亭留別族弟浮屠談皓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e8867b-a945-4f03-8e0e-eacbf3c6c0ee', '留別賈舍人至二首 一', '留別賈舍人至二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大梁白雲起，飄颻來南洲。","裴回蒼梧野，十見羅浮秋。","鼇抃山海傾，四溟揚洪流。","意欲託孤鳳，從之摩天遊。","鳳苦道路難，翱翔還崑丘。","不肯銜我去，哀鳴慙不周。","遠客謝主人，明珠難暗投。","拂拭倚天劒，西登岳陽樓。","長嘯萬里風，掃清胷中憂。","誰念劉越石，化爲繞指柔。"]', '["大梁白云起，飄颻来南洲。","裴回蒼梧野，十见羅浮秋。","鼇抃山海傾，四溟揚洪流。","意欲託孤鳳，從之摩天游。","鳳苦道路难，翱翔還崑丘。","不肯銜我去，哀鳴慙不周。","远客謝主人，明珠难暗投。","拂拭倚天劒，西登岳陽楼。","长嘯万里风，掃清胷中憂。","誰念劉越石，化爲繞指柔。"]', '诗', 'shi', '', NULL, '留別賈舍人至二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e2ee6f-0796-49c6-b9bd-96e786042baf', '留別賈舍人至二首 二', '留別賈舍人至二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋風吹胡霜，凋此簷下芳。","折芳怨歲晚，離別悽以傷。","謬攀青瑣賢，延我於北堂。","君爲長沙客，我獨之夜郎。","勸此一杯酒，豈惟道路長。","割珠兩分贈，寸心貴不忘。","何必兒女仁，相看淚成行。"]', '["秋风吹胡霜，凋此簷下芳。","折芳怨歲晚，離別悽以傷。","謬攀青瑣賢，延我於北堂。","君爲长沙客，我独之夜郎。","勸此一杯酒，豈惟道路长。","割珠兩分贈，寸心貴不忘。","何必兒女仁，相看泪成行。"]', '诗', 'shi', '', NULL, '留別賈舍人至二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf8918b8-a05a-4ccf-bb2e-3f9b81f6bbfc', '渡荆門送別', '渡荆门送別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["渡遠荆門外，來從楚國遊。","山隨平野盡，江入大荒流。","月下飛天鏡，雲生結海樓。","仍連故鄉水，萬里送行舟。"]', '["渡远荆门外，来從楚国游。","山隨平野尽，江入大荒流。","月下飞天镜，云生結海楼。","仍連故乡水，万里送行舟。"]', '诗', 'shi', '', NULL, '渡荆門送別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa70d3d0-dc0d-417b-aa49-3bcebfcbe727', '聞李太尉大舉秦兵百萬出征東南懦夫請纓冀申一割之用半道病還留別金陵崔侍御十九韻', '闻李太尉大舉秦兵百万出征东南懦夫請纓冀申一割之用半道病還留別金陵崔侍御十九韻', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦出天下兵，蹴踏燕趙傾。","黃河飲馬竭，赤羽連天明。","太尉杖旄鉞，雲旗繞彭城。","三軍受號令，千里肅雷霆。","函谷絕飛鳥，武關擁連營。","意在斬巨鼇，何論鱠長鯨。","恨無左軍略，多愧魯連生。","拂劒照嚴霜，彫戈鬘胡纓。","願雪會稽恥，將期報恩榮。","半道謝病還，無因東南征。","亞夫未見顧，劇孟阻先行。","天奪壯士心，長吁別吳京。","金陵遇太守，倒屣相逢迎。","羣公咸祖餞，四座羅朝英。","初發臨滄觀，醉棲征虜亭。","舊國見秋月，長江流寒聲。","帝車信迴轉，河漢復縱橫。","孤鳳向西海，飛鴻辭北溟。","因之出寥廓，揮手謝公卿。"]', '["秦出天下兵，蹴踏燕趙傾。","黄河饮马竭，赤羽連天明。","太尉杖旄鉞，云旗繞彭城。","三軍受號令，千里肅雷霆。","函谷絕飞鸟，武关擁連營。","意在斬巨鼇，何論鱠长鯨。","恨無左軍略，多愧魯連生。","拂劒照嚴霜，彫戈鬘胡纓。","願雪會稽恥，將期報恩榮。","半道謝病還，無因东南征。","亞夫未见顧，劇孟阻先行。","天奪壯士心，长吁別吳京。","金陵遇太守，倒屣相逢迎。","羣公咸祖餞，四座羅朝英。","初發臨滄观，醉棲征虜亭。","旧国见秋月，长江流寒声。","帝车信迴轉，河漢复縱橫。","孤鳳向西海，飞鴻辞北溟。","因之出寥廓，揮手謝公卿。"]', '诗', 'shi', '', NULL, '聞李太尉大舉秦兵百萬出征東南懦夫請纓冀申一割之用半道病還留別金陵崔侍御十九韻 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5d3b296-7f8d-4e30-b6a7-7942a5cf4902', '別韋少府', '別韋少府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西出蒼龍門，南登白鹿原。","欲尋商山皓，猶戀漢皇恩。","水國遠行邁，仙經深討論。","洗心向溪月，清耳敬亭猨。","築室在人境，閉門無世喧。","多君枉高駕，贈我以微言。","交乃意氣合，道因風雅存。","別離有相思，瑤瑟與金樽。"]', '["西出蒼龙门，南登白鹿原。","欲尋商山皓，猶戀漢皇恩。","水国远行邁，仙經深討論。","洗心向溪月，清耳敬亭猨。","築室在人境，閉门無世喧。","多君枉高駕，贈我以微言。","交乃意氣合，道因风雅存。","別離有相思，瑤瑟與金樽。"]', '诗', 'shi', '', NULL, '別韋少府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b826256-9c22-40b7-b797-669974fac0bc', '南陵別兒童入京', '南陵別兒童入京', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白酒新熟山中歸，黃雞啄黍秋正肥。","呼童烹雞酌白酒，兒女嬉笑牽人衣。","高歌取醉欲自慰，起舞落日爭光輝。","游說萬乘苦不早，著鞭跨馬涉遠道。","會稽愚婦輕買臣，余亦辭家西入秦。","仰天大笑出門去，我輩豈是蓬蒿人。"]', '["白酒新熟山中归，黄雞啄黍秋正肥。","呼童烹雞酌白酒，兒女嬉笑牽人衣。","高歌取醉欲自慰，起舞落日爭光輝。","游说万乘苦不早，著鞭跨马涉远道。","會稽愚婦轻買臣，余亦辞家西入秦。","仰天大笑出门去，我輩豈是蓬蒿人。"]', '诗', 'shi', '', NULL, '南陵別兒童入京 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6d524a9-aab5-4440-8b4b-380c3d9223e3', '別山僧', '別山僧', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["何處名僧到水西，乘舟弄月宿涇溪。","平明別我上山去，手攜金策踏雲梯。","騰身轉覺三天近，舉足迴看萬嶺低。","謔浪肯居支遁下，風流還與遠公齊。","此度別離何日見，相思一夜暝猨啼。"]', '["何处名僧到水西，乘舟弄月宿涇溪。","平明別我上山去，手携金策踏云梯。","腾身轉覺三天近，舉足迴看万嶺低。","謔浪肯居支遁下，风流還與远公齊。","此度別離何日见，相思一夜暝猨啼。"]', '诗', 'shi', '', NULL, '別山僧 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba723a17-18b0-4899-846e-b3143b80fd7b', '贈別王山人歸布山', '贈別王山人归布山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["王子析道論，微言破秋毫。","還歸布山隱，興入天雲高。","爾去安可遲，瑤草恐衰歇。","我心亦懷歸，屢夢松上月。","傲然遂獨往，長嘯開巖扉。","林壑久已蕪，石道生薔薇。","願言弄笙鶴，歲晚來相依。"]', '["王子析道論，微言破秋毫。","還归布山隐，兴入天云高。","爾去安可遲，瑤草恐衰歇。","我心亦懷归，屢梦松上月。","傲然遂独往，长嘯开巖扉。","林壑久已蕪，石道生薔薇。","願言弄笙鹤，歲晚来相依。"]', '诗', 'shi', '', NULL, '贈別王山人歸布山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af4241c-3cb4-4351-a5f9-8207e2a73905', '江夏別宋之悌', '江夏別宋之悌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["楚水清若空，遙將碧海通。","人分千里外，興在一杯中。","谷鳥吟晴日，江猨嘯晚風。","平生不下淚，於此泣無窮。"]', '["楚水清若空，遙將碧海通。","人分千里外，兴在一杯中。","谷鸟吟晴日，江猨嘯晚风。","平生不下泪，於此泣無窮。"]', '诗', 'shi', '', NULL, '江夏別宋之悌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dbf7997-7bc5-4919-8ed5-de4504f5e044', '南陽送客', '南陽送客', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["斗酒勿爲薄，寸心貴不忘。","坐惜故人去，偏令遊子傷。","離顏怨芳草，春思結垂楊。","揮手再三別，臨岐空斷腸。"]', '["斗酒勿爲薄，寸心貴不忘。","坐惜故人去，偏令游子傷。","離顏怨芳草，春思結垂楊。","揮手再三別，臨岐空斷腸。"]', '诗', 'shi', '', NULL, '南陽送客 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a03956af-1c8f-4f59-bbc9-c018f2920d13', '送張舍人之江東', '送張舍人之江东', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["張翰江東去，正值秋風時。","天清一鴈遠，海闊孤帆遲。","白日行欲暮，滄波杳難期。","吳洲如見月，千里幸相思。"]', '["張翰江东去，正值秋风时。","天清一鴈远，海闊孤帆遲。","白日行欲暮，滄波杳难期。","吳洲如见月，千里幸相思。"]', '诗', 'shi', '', NULL, '送張舍人之江東 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a18575-a154-499c-92a1-cc906f3ce6a0', '送王屋山人魏萬還王屋', '送王屋山人魏万還王屋', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["仙人東方生，浩蕩弄雲海。","沛然乘天遊，獨往失所在。","魏侯繼大名，本家聊攝城。","卷舒入元化，跡與古賢幷。","十三弄文史，揮筆如振綺。","辯折田巴生，心齊魯連子。","西涉清洛源，頗驚人世喧。","采秀臥王屋，因窺洞天門。","朅來遊嵩峰，羽客何雙雙。","朝攜月光子，暮宿玉女牕。","鬼谷上窈窕，龍潭下奔潨。","東浮汴河水，訪我三千里。","逸興滿吳雲，飄颻淛江汜。","揮手杭越間，樟亭望潮還。","濤卷海門石，雲橫天際山。","白馬走素車，雷奔駭心顏。","遙聞會稽美，且度耶溪水。","萬壑與千巖，崢嶸鏡湖裏。","秀色不可名，清輝滿江城。","人遊月邊去，舟在空中行。","此中久延佇，入剡尋王許。","笑讀曹娥碑，沈吟黃絹語。","天台連四明，日入向國清。","五峰轉月色，百里行松聲。","靈溪咨沿越，華頂殊超忽。","石梁橫青天，側足履半月。","忽然思永嘉，不憚海路賒。","挂席歷海嶠，迴瞻赤城霞。","赤城漸微沒，孤嶼前嶢兀。","水續萬古流，亭空千霜月。","縉雲川谷難，石門最可觀。","瀑布挂北斗，莫窮此水端。","噴壁灑素雪，空濛生晝寒。","却思惡溪去，寧懼惡溪惡。","咆哮七十灘，水石相噴薄。","路創李北海，巖開謝康樂。","松風和猨聲，搜索連洞壑。","徑出梅花橋，雙溪納歸潮。","落帆金華岸，赤松若可招。","沈約八詠樓，城西孤岧嶢。","岧嶢四荒外，曠望羣川會。","雲卷天地開，波連浙西大。","亂流新安口，北指嚴光瀨。","釣臺碧雲中，邈與蒼嶺對。","稍稍來吳都，裴回上姑蘇。","煙綿橫九疑，漭蕩見五湖。","目極心更遠，悲歌但長吁。","迴橈楚江濱，揮策揚子津。","身著日本裘，昂藏出風塵。","五月造我語，知非佁儗人。","相逢樂無限，水石日在眼。","徒干五諸侯，不致百金產。","吾友揚子雲，弦歌播清芬。","雖爲江寧宰，好與山公羣。","乘興但一行，且知我愛君。","君來幾何時，仙臺應有期。","東窗綠玉樹，定長三五枝。","至今天壇人，當笑爾歸遲。","我苦惜遠別，茫然使心悲。","黃河若不斷，白首長相思。"]', '["仙人东方生，浩蕩弄云海。","沛然乘天游，独往失所在。","魏侯繼大名，本家聊攝城。","卷舒入元化，跡與古賢幷。","十三弄文史，揮笔如振綺。","辯折田巴生，心齊魯連子。","西涉清洛源，頗驚人世喧。","采秀臥王屋，因窺洞天门。","朅来游嵩峰，羽客何雙雙。","朝携月光子，暮宿玉女牕。","鬼谷上窈窕，龙潭下奔潨。","东浮汴河水，訪我三千里。","逸兴满吳云，飄颻淛江汜。","揮手杭越间，樟亭望潮還。","濤卷海门石，云橫天際山。","白马走素车，雷奔駭心顏。","遙闻會稽美，且度耶溪水。","万壑與千巖，崢嶸镜湖裏。","秀色不可名，清輝满江城。","人游月邊去，舟在空中行。","此中久延佇，入剡尋王許。","笑读曹娥碑，沈吟黄絹語。","天台連四明，日入向国清。","五峰轉月色，百里行松声。","靈溪咨沿越，华頂殊超忽。","石梁橫青天，側足履半月。","忽然思永嘉，不憚海路賒。","挂席歷海嶠，迴瞻赤城霞。","赤城漸微沒，孤嶼前嶢兀。","水續万古流，亭空千霜月。","縉云川谷难，石门最可观。","瀑布挂北斗，莫窮此水端。","噴壁灑素雪，空濛生晝寒。","却思惡溪去，寧懼惡溪惡。","咆哮七十灘，水石相噴薄。","路創李北海，巖开謝康乐。","松风和猨声，搜索連洞壑。","徑出梅花橋，雙溪納归潮。","落帆金华岸，赤松若可招。","沈約八詠楼，城西孤岧嶢。","岧嶢四荒外，曠望羣川會。","云卷天地开，波連浙西大。","亂流新安口，北指嚴光瀨。","釣台碧云中，邈與蒼嶺对。","稍稍来吳都，裴回上姑蘇。","煙綿橫九疑，漭蕩见五湖。","目極心更远，悲歌但长吁。","迴橈楚江濱，揮策揚子津。","身著日本裘，昂藏出风塵。","五月造我語，知非佁儗人。","相逢乐無限，水石日在眼。","徒干五諸侯，不致百金產。","吾友揚子云，弦歌播清芬。","雖爲江寧宰，好與山公羣。","乘兴但一行，且知我愛君。","君来幾何时，仙台應有期。","东窗綠玉樹，定长三五枝。","至今天壇人，當笑爾归遲。","我苦惜远別，茫然使心悲。","黄河若不斷，白首长相思。"]', '诗', 'shi', '', NULL, '送王屋山人魏萬還王屋 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366d68c6-fc8b-4dad-b805-13ce2eb26fbb', '送當塗趙少府赴長蘆', '送當塗趙少府赴长蘆', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我來揚都市，送客回輕舠。","因誇楚太子，便覩廣陵濤。","仙尉趙家玉，英風凌四豪。","維舟至長蘆，目送煙雲高。","搖扇對酒樓，持袂把蟹螯。","前途儻相思，登嶽一長謠。"]', '["我来揚都市，送客回轻舠。","因誇楚太子，便覩廣陵濤。","仙尉趙家玉，英风凌四豪。","維舟至长蘆，目送煙云高。","搖扇对酒楼，持袂把蟹螯。","前途儻相思，登嶽一长謠。"]', '诗', 'shi', '', NULL, '送當塗趙少府赴長蘆 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f46c4b42-c765-44f4-bd22-bf30b4a7a5c7', '送友人尋越中山水', '送友人尋越中山水', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["聞道稽山去，偏宜謝客才。","千巖泉灑落，萬壑樹縈迴。","東海橫秦望，西陵遶越臺。","湖清霜鏡曉，濤白雪山來。","八月枚乘筆，三吳張翰杯。","此中多逸興，早晚向天台。"]', '["闻道稽山去，偏宜謝客才。","千巖泉灑落，万壑樹縈迴。","东海橫秦望，西陵遶越台。","湖清霜镜晓，濤白雪山来。","八月枚乘笔，三吳張翰杯。","此中多逸兴，早晚向天台。"]', '诗', 'shi', '', NULL, '送友人尋越中山水 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50f662a3-b036-4f18-acd8-255e8581bb1f', '送族弟凝之滁求婚崔氏', '送族弟凝之滁求婚崔氏', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["與爾情不淺，忘筌已得魚。","玉臺挂寶鏡，持此意何如。","坦腹東牀下，由來志氣疎。","遙知向前路，擲果定盈車。"]', '["與爾情不淺，忘筌已得鱼。","玉台挂寶镜，持此意何如。","坦腹东牀下，由来志氣疎。","遙知向前路，擲果定盈车。"]', '诗', 'shi', '', NULL, '送族弟凝之滁求婚崔氏 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6b982a2-5e34-487d-a54a-fbb388df57ec', '送友人遊梅湖', '送友人游梅湖', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["送君游梅湖，應見梅花發。","有使寄我來，無令紅芳歇。","暫行新林浦，定醉金陵月。","莫惜一鴈書，音塵坐胡越。"]', '["送君游梅湖，應见梅花發。","有使寄我来，無令紅芳歇。","暫行新林浦，定醉金陵月。","莫惜一鴈书，音塵坐胡越。"]', '诗', 'shi', '', NULL, '送友人遊梅湖 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01a5e0f-196c-43be-83ff-6c4ccad25e17', '送崔十二遊天竺寺', '送崔十二游天竺寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["還聞天竺寺，夢想懷東越。","每年海樹霜，桂子落秋月。","送君遊此地，已屬流芳歇。","待我來歲行，相隨浮溟渤。"]', '["還闻天竺寺，梦想懷东越。","每年海樹霜，桂子落秋月。","送君游此地，已屬流芳歇。","待我来歲行，相隨浮溟渤。"]', '诗', 'shi', '', NULL, '送崔十二遊天竺寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbacef3d-8cc5-44cb-bf68-4f36ccc13b35', '送楊山人歸天台', '送楊山人归天台', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["客有思天台，東行路超忽。","濤落浙江秋，沙明浦陽月。","今遊方厭楚，昨夢先歸越。","且盡秉燭歡，無辭凌晨發。","我家小阮賢，剖竹赤城邊。","詩人多見重，官燭未曾然。","興引登山屐，情催泛海船。","石橋如可度，攜手弄雲煙。"]', '["客有思天台，东行路超忽。","濤落浙江秋，沙明浦陽月。","今游方厭楚，昨梦先归越。","且尽秉燭歡，無辞凌晨發。","我家小阮賢，剖竹赤城邊。","诗人多见重，官燭未曾然。","兴引登山屐，情催泛海船。","石橋如可度，携手弄云煙。"]', '诗', 'shi', '', NULL, '送楊山人歸天台 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('123288b6-f986-4c06-99d4-433f9e22274b', '送溫處士歸黃山白鵝峰舊居', '送溫处士归黄山白鵝峰旧居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃山四千仞，三十二蓮峰。","丹崖夾石柱，菡萏金芙蓉。","伊昔昇絕頂，下窺天目松。","仙人鍊玉處，羽化留餘蹤。","亦聞溫伯雪，獨往今相逢。","採秀辭五岳，攀巖歷萬重。","歸休白鵝嶺，渴飲丹砂井。","鳳吹我時來，雲車爾當整。","去去陵陽東，行行芳桂叢。","迴溪十六度，碧嶂盡晴空。","他日還相訪，乘橋躡綵虹。"]', '["黄山四千仞，三十二蓮峰。","丹崖夾石柱，菡萏金芙蓉。","伊昔昇絕頂，下窺天目松。","仙人鍊玉处，羽化留餘蹤。","亦闻溫伯雪，独往今相逢。","採秀辞五岳，攀巖歷万重。","归休白鵝嶺，渴饮丹砂井。","鳳吹我时来，云车爾當整。","去去陵陽东，行行芳桂叢。","迴溪十六度，碧嶂尽晴空。","他日還相訪，乘橋躡綵虹。"]', '诗', 'shi', '', NULL, '送溫處士歸黃山白鵝峰舊居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c62f4f89-1398-4b22-9e2f-17480decca73', '送方士趙叟之東平', '送方士趙叟之东平', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長桑曉洞視，五藏無全牛。","趙叟得祕訣，還從方士遊。","西過獲麟臺，爲我弔孔丘。","念別復懷古，潸然空淚流。"]', '["长桑晓洞視，五藏無全牛。","趙叟得祕訣，還從方士游。","西過獲麟台，爲我弔孔丘。","念別复懷古，潸然空泪流。"]', '诗', 'shi', '', NULL, '送方士趙叟之東平 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77f7b9e4-ad7c-4af2-a41a-ee2afcb2428b', '送韓準裴政孔巢父還山', '送韓準裴政孔巢父還山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["獵客張兔罝，不能挂龍虎。","所以青雲人，高歌在巖戶。","韓生信英彥，裴子含清真。","孔侯復秀出，俱與雲霞親。","峻節凌遠松，同衾臥盤石。","斧冰嗽寒泉，三子同二屐。","時時或乘興，往往雲無心。","出山揖牧伯，長嘯輕衣簪。","昨宵夢裏還，云弄竹溪月。","今晨魯東門，帳飲與君別。","雪崖滑去馬，蘿徑迷歸人。","相思若煙草，歷亂無冬春。"]', '["獵客張兔罝，不能挂龙虎。","所以青云人，高歌在巖戶。","韓生信英彥，裴子含清真。","孔侯复秀出，俱與云霞親。","峻節凌远松，同衾臥盤石。","斧冰嗽寒泉，三子同二屐。","时时或乘兴，往往云無心。","出山揖牧伯，长嘯轻衣簪。","昨宵梦裏還，云弄竹溪月。","今晨魯东门，帳饮與君別。","雪崖滑去马，蘿徑迷归人。","相思若煙草，歷亂無冬春。"]', '诗', 'shi', '', NULL, '送韓準裴政孔巢父還山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92c9a3c7-04ef-449b-9b8a-a9f5c7b1f76e', '送楊少府赴選', '送楊少府赴選', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大國置衡鏡，準平天地心。","羣賢無邪人，朗鑒窮情深。","吾君詠南風，衮冕彈鳴琴。","時泰多美士，京國會纓簪。","山苗落澗底，幽松出高岑。","夫子有盛才，主司得球琳。","流水非鄭曲，前行遇知音。","衣工剪綺繡，一悞傷千金。","何惜刀尺餘，不裁寒女衾。","我非彈冠者，感別但開襟。","空谷無白駒，賢人豈悲吟。","大道安棄物，時來或招尋。","爾見山吏部，當應無陸沈。"]', '["大国置衡镜，準平天地心。","羣賢無邪人，朗鑒窮情深。","吾君詠南风，衮冕彈鳴琴。","时泰多美士，京国會纓簪。","山苗落澗底，幽松出高岑。","夫子有盛才，主司得球琳。","流水非鄭曲，前行遇知音。","衣工剪綺繡，一悞傷千金。","何惜刀尺餘，不裁寒女衾。","我非彈冠者，感別但开襟。","空谷無白駒，賢人豈悲吟。","大道安棄物，时来或招尋。","爾见山吏部，當應無陸沈。"]', '诗', 'shi', '', NULL, '送楊少府赴選 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('598b7bf9-47f1-4af6-a69e-6ca4f21565d4', '對雪奉餞任城六父秩滿歸京', '对雪奉餞任城六父秩满归京', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["龍虎謝鞭策，鵷鸞不司晨。","君看海上鶴，何似籠中鶉。","獨用天地心，浮雲乃吾身。","雖將簪組狎，若與煙霞親。","季父有英風，白眉超常倫。","一官即夢寐，脫屐歸西秦。","竇公敞華筵，墨客盡來臻。","燕歌落胡鴈，郢曲迴陽春。","征馬百度嘶，遊車動行塵。","躊躇未忍去，戀此四座人。","餞離駐高駕，惜別空殷勤。","何時竹林下，更與步兵鄰。"]', '["龙虎謝鞭策，鵷鸾不司晨。","君看海上鹤，何似籠中鶉。","独用天地心，浮云乃吾身。","雖將簪組狎，若與煙霞親。","季父有英风，白眉超常倫。","一官即梦寐，脫屐归西秦。","竇公敞华筵，墨客尽来臻。","燕歌落胡鴈，郢曲迴陽春。","征马百度嘶，游车动行塵。","躊躇未忍去，戀此四座人。","餞離駐高駕，惜別空殷勤。","何时竹林下，更與步兵鄰。"]', '诗', 'shi', '', NULL, '對雪奉餞任城六父秩滿歸京 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a55c5ec-f335-4e3d-89c3-2d54c1c6f0d6', '魯郡堯祠送吳五之瑯琊', '魯郡堯祠送吳五之瑯琊', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["堯沒三千歲，青松古廟存。","送行奠桂酒，拜舞清心魂。","日色促歸人，連歌倒芳樽。","馬嘶俱醉起，分手更何言。"]', '["堯沒三千歲，青松古廟存。","送行奠桂酒，拜舞清心魂。","日色促归人，連歌倒芳樽。","马嘶俱醉起，分手更何言。"]', '诗', 'shi', '', NULL, '魯郡堯祠送吳五之瑯琊 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5ab3e24-6d68-4cdf-ae96-33aa58599bbf', '魯郡堯祠送竇明府薄華還西京', '魯郡堯祠送竇明府薄华還西京', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝策犂眉騧，舉鞭力不堪。","强扶愁疾向何處，角巾微服堯祠南。","長楊掃地不見日，石門噴作金沙潭。","笑誇故人指絕境，山光水色青於藍。","廟中往往來擊鼓，堯本無心爾何苦。","門前長跪雙石人，有女如花日歌舞。","銀鞍繡轂往復迴，簸林蹶石鳴風雷。","遠煙空翠時明滅，白鷗歷亂長飛雪。","紅泥亭子赤闌干，碧流環轉青錦湍。","深沈百丈洞海底，那知不有蛟龍蟠。","君不見綠珠潭水流東海，綠珠紅粉沈光彩。","綠珠樓下花滿園，今日曾無一枝在。","昨夜秋聲閶闔來，洞庭木落騷人哀。","遂將三五少年輩，登高遠望形神開。","生前一笑輕九鼎，魏武何悲銅雀臺。","我歌白雲倚牕牖，爾聞其聲但揮手。","長風吹月度海來，遙勸仙人一杯酒。","酒中樂酣宵向分，舉觴酹堯堯可聞。","何不令臯繇擁篲橫八極，直上青天揮浮雲。","高陽小飲真瑣瑣，山公酩酊何如我。","竹林七子去道賒，蘭亭雄筆安足誇。","堯祠笑殺五湖水，至今顦悴空荷花。","爾向西秦我東越，暫向瀛洲訪金闕。","藍田太白若可期，爲余掃灑石上月。"]', '["朝策犂眉騧，舉鞭力不堪。","强扶愁疾向何处，角巾微服堯祠南。","长楊掃地不见日，石门噴作金沙潭。","笑誇故人指絕境，山光水色青於藍。","廟中往往来擊鼓，堯本無心爾何苦。","门前长跪雙石人，有女如花日歌舞。","銀鞍繡轂往复迴，簸林蹶石鳴风雷。","远煙空翠时明滅，白鷗歷亂长飞雪。","紅泥亭子赤闌干，碧流环轉青錦湍。","深沈百丈洞海底，那知不有蛟龙蟠。","君不见綠珠潭水流东海，綠珠紅粉沈光彩。","綠珠楼下花满园，今日曾無一枝在。","昨夜秋声閶闔来，洞庭木落騷人哀。","遂將三五少年輩，登高远望形神开。","生前一笑轻九鼎，魏武何悲銅雀台。","我歌白云倚牕牖，爾闻其声但揮手。","长风吹月度海来，遙勸仙人一杯酒。","酒中乐酣宵向分，舉觴酹堯堯可闻。","何不令臯繇擁篲橫八極，直上青天揮浮云。","高陽小饮真瑣瑣，山公酩酊何如我。","竹林七子去道賒，蘭亭雄笔安足誇。","堯祠笑殺五湖水，至今顦悴空荷花。","爾向西秦我东越，暫向瀛洲訪金闕。","藍田太白若可期，爲余掃灑石上月。"]', '诗', 'shi', '', NULL, '魯郡堯祠送竇明府薄華還西京 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25baae5-ed69-4115-b06b-58b50d1cab42', '金鄉送韋八之西京', '金乡送韋八之西京', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["客自長安來，還歸長安去。","狂風吹我心，西挂咸陽樹。","此情不可道，此別何時遇。","望望不見君，連山起煙霧。"]', '["客自长安来，還归长安去。","狂风吹我心，西挂咸陽樹。","此情不可道，此別何时遇。","望望不见君，連山起煙霧。"]', '诗', 'shi', '', NULL, '金鄉送韋八之西京 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5297d9ed-84f3-4369-9f08-57993a2a185f', '送薛九被讒去魯', '送薛九被讒去魯', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["宋人不辨玉，魯賤東家丘。","我笑薛夫子，胡爲兩地遊。","黃金消衆口，白璧竟難投。","梧桐生蒺藜，綠竹乏佳實。","鳳凰宿誰家，遂與羣雞匹。","田家養老馬，窮士歸其門。","蛾眉笑躄者，賓客去平原。","却斬美人首，三千還駿奔。","毛公一挺劒，楚趙兩相存。","孟嘗習狡兔，三窟賴馮諼。","信陵奪兵符，爲用侯生言。","春申一何愚，刎首爲李園。","賢哉四公子，撫掌黃泉裏。","借問笑何人，笑人不好士。","爾去且勿諠，桃李竟何言。","沙丘無漂母，誰肯飯王孫。"]', '["宋人不辨玉，魯賤东家丘。","我笑薛夫子，胡爲兩地游。","黄金消衆口，白璧竟难投。","梧桐生蒺藜，綠竹乏佳實。","鳳凰宿誰家，遂與羣雞匹。","田家養老马，窮士归其门。","蛾眉笑躄者，賓客去平原。","却斬美人首，三千還駿奔。","毛公一挺劒，楚趙兩相存。","孟嘗習狡兔，三窟賴馮諼。","信陵奪兵符，爲用侯生言。","春申一何愚，刎首爲李园。","賢哉四公子，撫掌黄泉裏。","借问笑何人，笑人不好士。","爾去且勿諠，桃李竟何言。","沙丘無漂母，誰肯飯王孫。"]', '诗', 'shi', '', NULL, '送薛九被讒去魯 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a9ed68-08f2-47e1-a06d-15004d23bdf3', '單父東樓秋夜送族弟沈之秦', '單父东楼秋夜送族弟沈之秦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["爾從咸陽來，問我何勞苦。","沐猴而冠不足言，身騎土牛滯東魯。","沈弟欲行凝弟留，孤飛一雁秦雲秋。","坐來黃葉落四五，北斗已挂西城樓。","絲桐感人弦亦絕，滿堂送君皆惜別。","卷簾見月清興來，疑是山陰夜中雪。","明日斗酒別，惆悵清路塵。","遙望長安日，不見長安人。","長安宮闕九天上，此地曾經爲近臣。","一朝復一朝，髮白心不改。","屈原憔悴滯江潭，亭伯流離放遼海。","折翮翻飛隨轉蓬，聞弦墜虛下霜空。","聖朝久棄青雲士，他日誰憐張長公。"]', '["爾從咸陽来，问我何勞苦。","沐猴而冠不足言，身騎土牛滯东魯。","沈弟欲行凝弟留，孤飞一雁秦云秋。","坐来黄葉落四五，北斗已挂西城楼。","絲桐感人弦亦絕，满堂送君皆惜別。","卷簾见月清兴来，疑是山陰夜中雪。","明日斗酒別，惆悵清路塵。","遙望长安日，不见长安人。","长安宮闕九天上，此地曾經爲近臣。","一朝复一朝，髮白心不改。","屈原憔悴滯江潭，亭伯流離放遼海。","折翮翻飞隨轉蓬，闻弦墜虛下霜空。","聖朝久棄青云士，他日誰怜張长公。"]', '诗', 'shi', '', NULL, '單父東樓秋夜送族弟沈之秦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3773616-f026-453c-ae3f-356fea47a3a0', '送族弟凝至晏堌', '送族弟凝至晏堌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雪滿原野白，戎裝出盤遊。","揮鞭布獵騎，四顧登高丘。","兔起馬足間，蒼鷹下平疇。","喧呼相馳逐，取樂銷人憂。","舍此戒禽荒，微聲列齊謳。","鳴雞發晏堌，別雁驚淶溝。","西行有東音，寄與長河流。"]', '["雪满原野白，戎裝出盤游。","揮鞭布獵騎，四顧登高丘。","兔起马足间，蒼鷹下平疇。","喧呼相驰逐，取乐銷人憂。","舍此戒禽荒，微声列齊謳。","鳴雞發晏堌，別雁驚淶溝。","西行有东音，寄與长河流。"]', '诗', 'shi', '', NULL, '送族弟凝至晏堌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f821e44c-1c77-4aea-9a9c-edb7c391b832', '魯城北郭曲腰桑下送張子還嵩陽', '魯城北郭曲腰桑下送張子還嵩陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["送別枯桑下，凋葉落半空。","我行懵道遠，爾獨知天風。","誰念張仲蔚，還依蒿與蓬。","何時一杯酒，更與李膺同。"]', '["送別枯桑下，凋葉落半空。","我行懵道远，爾独知天风。","誰念張仲蔚，還依蒿與蓬。","何时一杯酒，更與李膺同。"]', '诗', 'shi', '', NULL, '魯城北郭曲腰桑下送張子還嵩陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0579b6e-b0bf-481f-a654-33f38f275b4b', '送魯郡劉長史遷弘農長史', '送魯郡劉长史遷弘農长史', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯國一杯水，難容橫海鱗。","仲尼且不敬，況乃尋常人。","白玉換斗粟，黃金買尺薪。","閉門木葉下，始覺秋非春。","聞君向西遷，地即鼎湖鄰。","寶鏡匣蒼蘚，丹經埋素塵。","軒后上天時，攀龍遺小臣。","及此留惠愛，庶幾風化淳。","魯縞如白煙，五縑不成束。","臨行贈貧交，一尺重山岳。","相國齊晏子，贈行不及言。","託陰當樹李，忘憂當樹萱。","他日見張祿，綈袍懷舊恩。"]', '["魯国一杯水，难容橫海鱗。","仲尼且不敬，況乃尋常人。","白玉換斗粟，黄金買尺薪。","閉门木葉下，始覺秋非春。","闻君向西遷，地即鼎湖鄰。","寶镜匣蒼蘚，丹經埋素塵。","軒后上天时，攀龙遺小臣。","及此留惠愛，庶幾风化淳。","魯縞如白煙，五縑不成束。","臨行贈貧交，一尺重山岳。","相国齊晏子，贈行不及言。","託陰當樹李，忘憂當樹萱。","他日见張祿，綈袍懷旧恩。"]', '诗', 'shi', '', NULL, '送魯郡劉長史遷弘農長史 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc5f4d7-c9b8-464a-a3c8-a5f618d374cc', '送族弟單父主簿凝攝宋城主簿至郭南月橋却迴棲霞山留飲贈之', '送族弟單父主簿凝攝宋城主簿至郭南月橋却迴棲霞山留饮贈之', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾家青萍劍，操割有餘閑。","往來糾二邑，此去何時還。","鞍馬月橋南，光輝岐路間。","賢豪相追餞，却到棲霞山。","羣花散芳園，斗酒開離顏。","樂酣相顧起，征馬無由攀。"]', '["吾家青萍劍，操割有餘闲。","往来糾二邑，此去何时還。","鞍马月橋南，光輝岐路间。","賢豪相追餞，却到棲霞山。","羣花散芳园，斗酒开離顏。","乐酣相顧起，征马無由攀。"]', '诗', 'shi', '', NULL, '送族弟單父主簿凝攝宋城主簿至郭南月橋却迴棲霞山留飲贈之 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432f0351-d99d-41eb-9712-143f2850cb42', '魯郡東石門送杜二甫', '魯郡东石门送杜二甫', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["醉別復幾日，登臨徧池臺。","何時石門路，重有金樽開。","秋波落泗水，海色明徂徠。","飛蓬各自遠，且盡手中杯。"]', '["醉別复幾日，登臨徧池台。","何时石门路，重有金樽开。","秋波落泗水，海色明徂徠。","飞蓬各自远，且尽手中杯。"]', '诗', 'shi', '', NULL, '魯郡東石門送杜二甫 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ca3ce18-f054-4812-9399-fd831efdf337', '魯郡堯祠送張十四遊河北', '魯郡堯祠送張十四游河北', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["猛虎伏尺草，雖藏難蔽身。","有如張公子，骯髒在風塵。","豈無橫腰劒，屈彼淮陰人。","擊筑向北燕，燕歌易水濱。","歸來泰山上，當與爾爲鄰。"]', '["猛虎伏尺草，雖藏难蔽身。","有如張公子，骯髒在风塵。","豈無橫腰劒，屈彼淮陰人。","擊筑向北燕，燕歌易水濱。","归来泰山上，當與爾爲鄰。"]', '诗', 'shi', '', NULL, '魯郡堯祠送張十四遊河北 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44151303-461e-45bb-9f23-ea06a04d66bb', '杭州送裴大澤赴廬州長史', '杭州送裴大澤赴廬州长史', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西江天柱遠，東越海門深。","去割慈親戀，行憂報國心。","好風吹落日，流水引長吟。","五月披裘者，應知不取金。"]', '["西江天柱远，东越海门深。","去割慈親戀，行憂報国心。","好风吹落日，流水引长吟。","五月披裘者，應知不取金。"]', '诗', 'shi', '', NULL, '杭州送裴大澤赴廬州長史 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('604817ba-67b1-4e3c-8390-c93753deb12f', '灞陵行送別', '灞陵行送別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["送君灞陵亭，灞水流浩浩。","上有無花之古樹，下有傷心之春草。","我向秦人問路岐，云是王粲南登之古道。","古道連綿走西京，紫闕落日浮雲生。","正當今夕斷腸處，黃鸝愁絕不忍聽。"]', '["送君灞陵亭，灞水流浩浩。","上有無花之古樹，下有傷心之春草。","我向秦人问路岐，云是王粲南登之古道。","古道連綿走西京，紫闕落日浮云生。","正當今夕斷腸处，黄鸝愁絕不忍听。"]', '诗', 'shi', '', NULL, '灞陵行送別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6605a4d-7343-4a17-9663-0cded2180293', '送賀監歸四明應制', '送賀監归四明應制', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["久辭榮祿遂初衣，曾向長生說息機。","真訣自從茅氏得，恩波寧阻洞庭歸。","瑤臺含霧星辰滿，仙嶠浮空島嶼微。","借問欲棲珠樹鶴，何年却向帝城飛。"]', '["久辞榮祿遂初衣，曾向长生说息機。","真訣自從茅氏得，恩波寧阻洞庭归。","瑤台含霧星辰满，仙嶠浮空島嶼微。","借问欲棲珠樹鹤，何年却向帝城飞。"]', '诗', 'shi', '', NULL, '送賀監歸四明應制 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fafa4d1f-a604-4719-b5fe-00d79fc1cfd6', '送竇司馬貶宜春', '送竇司马貶宜春', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天馬白銀鞍，親承明主歡。","鬬雞金宮裏，射鴈碧雲端。","堂上羅中貴，歌鍾清夜闌。","何言謫南國，拂劍坐長歎。","趙璧爲誰點，隋珠枉被彈。","聖朝多雨露，莫厭此行難。"]', '["天马白銀鞍，親承明主歡。","鬬雞金宮裏，射鴈碧云端。","堂上羅中貴，歌鍾清夜闌。","何言謫南国，拂劍坐长歎。","趙璧爲誰点，隋珠枉被彈。","聖朝多雨露，莫厭此行难。"]', '诗', 'shi', '', NULL, '送竇司馬貶宜春 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('824f6cd7-1d32-4f85-8bb0-0c67072094a8', '送羽林陶將軍', '送羽林陶將軍', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["將軍出使擁樓船，江上旌旗拂紫煙。","萬里橫戈探虎穴，三杯拔劍舞龍泉。","莫道詞人無膽氣，臨行將贈繞朝鞭。"]', '["將軍出使擁楼船，江上旌旗拂紫煙。","万里橫戈探虎穴，三杯拔劍舞龙泉。","莫道词人無膽氣，臨行將贈繞朝鞭。"]', '诗', 'shi', '', NULL, '送羽林陶將軍 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55e92c8e-80af-4dcc-a34d-706c95138e91', '送程劉二侍郎兼獨孤判官赴安西幕府', '送程劉二侍郎兼独孤判官赴安西幕府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["安西幕府多材雄，喧喧惟道三數公。","繡衣貂裘明積雪，飛書走檄如飄風。","朝辭明主出紫宮，銀鞍送別金城空。","天外飛霜下蔥海，火旗雲馬生光彩。","胡塞清塵幾日歸，漢家草綠遙相待。"]', '["安西幕府多材雄，喧喧惟道三數公。","繡衣貂裘明積雪，飞书走檄如飄风。","朝辞明主出紫宮，銀鞍送別金城空。","天外飞霜下蔥海，火旗云马生光彩。","胡塞清塵幾日归，漢家草綠遙相待。"]', '诗', 'shi', '', NULL, '送程劉二侍郎兼獨孤判官赴安西幕府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b49f2a8-865d-4327-80e3-96df2ed6db27', '送姪良攜二妓赴會稽戲有此贈', '送姪良携二妓赴會稽戲有此贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["攜妓東山去，春光半道催。","遙看若桃李，雙入鏡中開。"]', '["携妓东山去，春光半道催。","遙看若桃李，雙入镜中开。"]', '诗', 'shi', '', NULL, '送姪良攜二妓赴會稽戲有此贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e410354e-db61-419e-96f8-b2f28f9e7aca', '送賀賓客歸越', '送賀賓客归越', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鏡湖流水漾清波，狂客歸舟逸興多。","山陰道士如相見，應寫黃庭換白鵝。"]', '["镜湖流水漾清波，狂客归舟逸兴多。","山陰道士如相见，應寫黄庭換白鵝。"]', '诗', 'shi', '', NULL, '送賀賓客歸越 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d306d38-234e-48e7-a35f-d1f155264786', '送張遙之壽陽幕府', '送張遙之壽陽幕府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["壽陽信天險，天險橫荆關。","苻堅百萬衆，遙阻八公山。","不假築長城，大賢在其間。","戰夫若熊虎，破敵有餘閑。","張子勇且英，少輕衛霍孱。","投軀紫髯將，千里望風顏。","勗爾効才略，功成衣錦還。"]', '["壽陽信天險，天險橫荆关。","苻堅百万衆，遙阻八公山。","不假築长城，大賢在其间。","戰夫若熊虎，破敵有餘闲。","張子勇且英，少轻衛霍孱。","投軀紫髯將，千里望风顏。","勗爾効才略，功成衣錦還。"]', '诗', 'shi', '', NULL, '送張遙之壽陽幕府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c0f376-de6c-49b9-ace2-bdcefbaad76f', '送裴十八圖南歸嵩山二首 一', '送裴十八圖南归嵩山二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["何處可爲別，長安青綺門。","胡姬招素手，延客醉金樽。","臨當上馬時，我獨與君言。","風吹芳蘭折，日沒鳥雀喧。","舉手指飛鴻，此情難具論。","同歸無早晚，潁水有清源。"]', '["何处可爲別，长安青綺门。","胡姬招素手，延客醉金樽。","臨當上马时，我独與君言。","风吹芳蘭折，日沒鸟雀喧。","舉手指飞鴻，此情难具論。","同归無早晚，潁水有清源。"]', '诗', 'shi', '', NULL, '送裴十八圖南歸嵩山二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb0797b-6b0c-4e04-8be3-06cbb3c535fe', '送裴十八圖南歸嵩山二首 二', '送裴十八圖南归嵩山二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君思潁水綠，忽復歸嵩岑。","歸時莫洗耳，爲我洗其心。","洗心得真情，洗耳徒買名。","謝公終一起，相與濟蒼生。"]', '["君思潁水綠，忽复归嵩岑。","归时莫洗耳，爲我洗其心。","洗心得真情，洗耳徒買名。","謝公終一起，相與濟蒼生。"]', '诗', 'shi', '', NULL, '送裴十八圖南歸嵩山二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecaff990-891b-4270-be58-232b9ce0a501', '同王昌齡送族弟襄歸桂陽二首 一', '同王昌齡送族弟襄归桂陽二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦地見碧草，楚謠對清樽。","把酒爾何思，鷓鴣啼南園。","余欲羅浮隱，猶懷明主恩。","躊躇紫宮戀，孤負滄洲言。","終然無心雲，海上同飛翻。","相期乃不淺，幽桂有芳根。"]', '["秦地见碧草，楚謠对清樽。","把酒爾何思，鷓鴣啼南园。","余欲羅浮隐，猶懷明主恩。","躊躇紫宮戀，孤負滄洲言。","終然無心云，海上同飞翻。","相期乃不淺，幽桂有芳根。"]', '诗', 'shi', '', NULL, '同王昌齡送族弟襄歸桂陽二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f4fe6b-129d-4ab3-b888-b014cc21eef9', '同王昌齡送族弟襄歸桂陽二首 二', '同王昌齡送族弟襄归桂陽二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["爾家何在瀟湘川，青莎白石長沙邊。","昨夢江花照江日，幾枝正發東牕前。","覺來欲往心悠然，魂隨越鳥飛南天。","秦雲連山海相接，桂水橫煙不可涉。","送君此去令人愁，風帆茫茫隔河洲。","春潭瓊草綠可折，西寄長安明月樓。"]', '["爾家何在瀟湘川，青莎白石长沙邊。","昨梦江花照江日，幾枝正發东牕前。","覺来欲往心悠然，魂隨越鸟飞南天。","秦云連山海相接，桂水橫煙不可涉。","送君此去令人愁，风帆茫茫隔河洲。","春潭瓊草綠可折，西寄长安明月楼。"]', '诗', 'shi', '', NULL, '同王昌齡送族弟襄歸桂陽二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38cc5ab-e7ac-48ce-93fc-e89315ca64b7', '送外甥鄭灌從軍三首 一', '送外甥鄭灌從軍三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["六博爭雄好彩來，金盤一擲萬人開。","丈夫賭命報天子，當斬胡頭衣錦回。"]', '["六博爭雄好彩来，金盤一擲万人开。","丈夫賭命報天子，當斬胡头衣錦回。"]', '诗', 'shi', '', NULL, '送外甥鄭灌從軍三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb306ab2-2ab6-4420-a78d-14d23e4c4365', '送外甥鄭灌從軍三首 二', '送外甥鄭灌從軍三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["丈八蛇矛出隴西，彎弧拂箭白猨啼。","破胡必用龍韜策，積甲應將熊耳齊。"]', '["丈八蛇矛出隴西，彎弧拂箭白猨啼。","破胡必用龙韜策，積甲應將熊耳齊。"]', '诗', 'shi', '', NULL, '送外甥鄭灌從軍三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a86a1fa-6d4e-4878-bfb5-20797ad298ad', '送外甥鄭灌從軍三首 三', '送外甥鄭灌從軍三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月蝕西方破敵時，及瓜歸日未應遲。","斬胡血變黃河水，梟首當懸白鵲旗。"]', '["月蝕西方破敵时，及瓜归日未應遲。","斬胡血变黄河水，梟首當懸白鵲旗。"]', '诗', 'shi', '', NULL, '送外甥鄭灌從軍三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c589b3c-f792-4b59-b3d4-b81efc736077', '送于十八應四子舉落第還嵩山', '送于十八應四子舉落第還嵩山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾祖吹橐籥，天人信森羅。","歸根復太素，羣動熙元和。","炎炎四真人，摛辯若濤波。","交流無時寂，楊墨日成科。","夫子聞洛誦，誇才才固多。","爲金好踊躍，久客方蹉跎。","道可束賣之，五寶溢山河。","勸君還嵩丘，開酌盼庭柯。","三花如未落，乘興一來過。"]', '["吾祖吹橐籥，天人信森羅。","归根复太素，羣动熙元和。","炎炎四真人，摛辯若濤波。","交流無时寂，楊墨日成科。","夫子闻洛誦，誇才才固多。","爲金好踊躍，久客方蹉跎。","道可束賣之，五寶溢山河。","勸君還嵩丘，开酌盼庭柯。","三花如未落，乘兴一来過。"]', '诗', 'shi', '', NULL, '送于十八應四子舉落第還嵩山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fa83850-46d1-4f9e-b970-d8c24bbb353a', '送別', '送別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["尋陽五溪水，沿洄直入巫山裏。","勝境由來人共傳，君到南中自稱美。","送君別有八月秋，颯颯蘆花復益愁。","雲帆望遠不相見，日暮長江空自流。"]', '["尋陽五溪水，沿洄直入巫山裏。","勝境由来人共傳，君到南中自稱美。","送君別有八月秋，颯颯蘆花复益愁。","云帆望远不相见，日暮长江空自流。"]', '诗', 'shi', '', NULL, '送別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb506670-0684-403a-95a3-5404d868c97b', '送族弟綰從軍安西', '送族弟綰從軍安西', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢家兵馬乘北風，鼓行而西破犬戎。","爾隨漢將出門去，剪虜若草收奇功。","君王按劍望邊色，旄頭已落胡天空。","匈奴繫頭數應盡，明年應入蒲萄宮。"]', '["漢家兵马乘北风，鼓行而西破犬戎。","爾隨漢將出门去，剪虜若草收奇功。","君王按劍望邊色，旄头已落胡天空。","匈奴繫头數應尽，明年應入蒲萄宮。"]', '诗', 'shi', '', NULL, '送族弟綰從軍安西 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d3de06-7a8a-4b52-b740-fd9ceb59bddd', '送梁公昌從信安北征', '送梁公昌從信安北征', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["入幕推英選，捐書事遠戎。","高談百戰術，鬱作萬夫雄。","起舞蓮花劍，行歌明月弓。","將飛天地陣，兵出塞垣通。","祖席留丹景，征麾拂彩虹。","旋應獻凱入，麟閣佇深功。"]', '["入幕推英選，捐书事远戎。","高談百戰術，鬱作万夫雄。","起舞蓮花劍，行歌明月弓。","將飞天地陣，兵出塞垣通。","祖席留丹景，征麾拂彩虹。","旋應獻凱入，麟閣佇深功。"]', '诗', 'shi', '', NULL, '送梁公昌從信安北征 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e8a5439-6648-4b6b-aca8-a5420585c67d', '送白利從金吾董將軍西征', '送白利從金吾董將軍西征', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西羌延國討，白起佐軍威。","劍決浮雲氣，弓彎明月輝。","馬行邊草綠，旌卷曙霜飛。","抗手凜相顧，寒風生鐵衣。"]', '["西羌延国討，白起佐軍威。","劍決浮云氣，弓彎明月輝。","马行邊草綠，旌卷曙霜飞。","抗手凜相顧，寒风生鐵衣。"]', '诗', 'shi', '', NULL, '送白利從金吾董將軍西征 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e962ed06-2f60-49ae-9114-3650b2e72283', '送張秀才從軍', '送張秀才從軍', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["六駁食猛虎，恥從駑馬羣。","一朝長鳴去，矯若龍行雲。","壯士懷遠略，志存解世紛。","周粟猶不顧，齊珪安肯分。","抱劍辭高堂，將投崔冠軍。","長策掃河洛，寧親歸汝墳。","當令千古後，麟閣著奇勳。"]', '["六駁食猛虎，恥從駑马羣。","一朝长鳴去，矯若龙行云。","壯士懷远略，志存解世紛。","周粟猶不顧，齊珪安肯分。","抱劍辞高堂，將投崔冠軍。","长策掃河洛，寧親归汝墳。","當令千古後，麟閣著奇勳。"]', '诗', 'shi', '', NULL, '送張秀才從軍 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60e7aa0-bc6e-4bf5-8e2b-c28fd0295d69', '送崔度還吳', '送崔度還吳', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["幽燕沙雪地，萬里盡黃雲。","朝吹歸秋雁，南飛日幾羣。","中有孤鳳雛，哀鳴九天聞。","我乃重此鳥，綵章五色分。","胡爲雜凡禽，雛鶩輕賤君。","舉手捧爾足，疾心若火焚。","拂羽淚滿面，送之吳江濆。","去影忽不見，躊躇日將曛。"]', '["幽燕沙雪地，万里尽黄云。","朝吹归秋雁，南飞日幾羣。","中有孤鳳雛，哀鳴九天闻。","我乃重此鸟，綵章五色分。","胡爲杂凡禽，雛鶩轻賤君。","舉手捧爾足，疾心若火焚。","拂羽泪满面，送之吳江濆。","去影忽不见，躊躇日將曛。"]', '诗', 'shi', '', NULL, '送崔度還吳 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59ef98eb-2b16-40d4-9092-e497299b0aed', '送祝八之江東賦得浣紗石', '送祝八之江东賦得浣紗石', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西施越溪女，明豔光雲海。","未入吳王宮殿時，浣紗古石今猶在。","桃李新開映古查，菖蒲猶短出平沙。","昔時紅粉照流水，今日青苔覆落花。","君去西秦適東越，碧山青江幾超忽。","若到天涯思故人，浣紗石上窺明月。"]', '["西施越溪女，明豔光云海。","未入吳王宮殿时，浣紗古石今猶在。","桃李新开映古查，菖蒲猶短出平沙。","昔时紅粉照流水，今日青苔覆落花。","君去西秦適东越，碧山青江幾超忽。","若到天涯思故人，浣紗石上窺明月。"]', '诗', 'shi', '', NULL, '送祝八之江東賦得浣紗石 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0460180e-63da-42ae-870b-7d943e7913c5', '送侯十一', '送侯十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朱亥已擊晉，侯嬴尚隱身。","時無魏公子，豈貴抱關人。","余亦不火食，遊梁同在陳。","空餘湛盧劍，贈爾託交親。"]', '["朱亥已擊晉，侯嬴尚隐身。","时無魏公子，豈貴抱关人。","余亦不火食，游梁同在陳。","空餘湛盧劍，贈爾託交親。"]', '诗', 'shi', '', NULL, '送侯十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecedf7b9-697a-41be-a017-e66ea1d9a4f4', '魯中送二從弟赴舉之西京', '魯中送二從弟赴舉之西京', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯客向西笑，君門若夢中。","霜凋逐臣髮，日憶明光宮。","復羨二龍去，才華冠世雄。","平衢騁高足，逸翰凌長風。","舞袖拂秋月，歌筵聞蚤鴻。","送君日千里，良會何由同。"]', '["魯客向西笑，君门若梦中。","霜凋逐臣髮，日憶明光宮。","复羨二龙去，才华冠世雄。","平衢騁高足，逸翰凌长风。","舞袖拂秋月，歌筵闻蚤鴻。","送君日千里，良會何由同。"]', '诗', 'shi', '', NULL, '魯中送二從弟赴舉之西京 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee2b6255-9e07-43af-b7b6-28f39f33f8da', '奉餞高尊師如貴道士傳道籙畢歸北海', '奉餞高尊師如貴道士傳道籙畢归北海', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["道隱不可見，靈書藏洞天。","吾師四萬劫，歷世遰相傳。","別杖留青竹，行歌躡紫煙。","離心無遠近，長在玉京懸。"]', '["道隐不可见，靈书藏洞天。","吾師四万劫，歷世遰相傳。","別杖留青竹，行歌躡紫煙。","離心無远近，长在玉京懸。"]', '诗', 'shi', '', NULL, '奉餞高尊師如貴道士傳道籙畢歸北海 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5654e19-ae83-4262-918c-8916798f6da6', '金陵送張十一再遊東吳', '金陵送張十一再游东吳', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["張翰黃花句，風流五百年。","誰人今繼作，夫子世稱賢。","再動游吳櫂，還浮入海船。","春光白門柳，霞色赤城天。","去國難爲別，思歸各未旋。","空餘賈生淚，相顧共悽然。"]', '["張翰黄花句，风流五百年。","誰人今繼作，夫子世稱賢。","再动游吳櫂，還浮入海船。","春光白门柳，霞色赤城天。","去国难爲別，思归各未旋。","空餘賈生泪，相顧共悽然。"]', '诗', 'shi', '', NULL, '金陵送張十一再遊東吳 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc2f505-9c71-4539-a5c9-ab2bcbdd756a', '送紀秀才遊越', '送紀秀才游越', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海水不滿眼，觀濤難稱心。","即知蓬萊石，却是巨鼇簪。","送爾遊華頂，令余發舃吟。","仙人居射的，道士住山陰。","禹穴尋溪入，雲門隔嶺深。","綠蘿秋月夜，相憶在鳴琴。"]', '["海水不满眼，观濤难稱心。","即知蓬萊石，却是巨鼇簪。","送爾游华頂，令余發舃吟。","仙人居射的，道士住山陰。","禹穴尋溪入，云门隔嶺深。","綠蘿秋月夜，相憶在鳴琴。"]', '诗', 'shi', '', NULL, '送紀秀才遊越 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c79a97-d07a-425f-8dbd-11de4e9aa98d', '送長沙陳太守二首 一', '送长沙陳太守二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長沙陳太守，逸氣凌青松。","英主賜五馬，本是天池龍。","湘水迴九曲，衡山望五峰。","榮君按節去，不及遠相從。"]', '["长沙陳太守，逸氣凌青松。","英主賜五马，本是天池龙。","湘水迴九曲，衡山望五峰。","榮君按節去，不及远相從。"]', '诗', 'shi', '', NULL, '送長沙陳太守二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314f7709-ef88-4638-b8e3-6d9b4cd147ca', '送長沙陳太守二首 二', '送长沙陳太守二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["七郡長沙國，南連湘水濱。","定王垂舞袖，地窄不迴身。","莫小二千石，當安遠俗人。","洞庭鄉路遠，遙羨錦衣春。"]', '["七郡长沙国，南連湘水濱。","定王垂舞袖，地窄不迴身。","莫小二千石，當安远俗人。","洞庭乡路远，遙羨錦衣春。"]', '诗', 'shi', '', NULL, '送長沙陳太守二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c018949-4bbb-43bb-8af9-02690f2ca715', '送楊燕之東魯', '送楊燕之东魯', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["關西楊伯起，漢日舊稱賢。","四代三公族，清風播人天。","夫子華陰居，開門對玉蓮。","何事歷衡霍，雲帆今始還。","君坐稍解顏，爲君歌此篇。","我固侯門士，謬登聖主筵。","一辭金華殿，蹭蹬長江邊。","二子魯門東，別來已經年。","因君此中去，不覺淚如泉。"]', '["关西楊伯起，漢日旧稱賢。","四代三公族，清风播人天。","夫子华陰居，开门对玉蓮。","何事歷衡霍，云帆今始還。","君坐稍解顏，爲君歌此篇。","我固侯门士，謬登聖主筵。","一辞金华殿，蹭蹬长江邊。","二子魯门东，別来已經年。","因君此中去，不覺泪如泉。"]', '诗', 'shi', '', NULL, '送楊燕之東魯 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb6f5ac0-a2bb-406f-9049-28ac81cfee12', '送蔡山人', '送蔡山人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我本不棄世，世人自棄我。","一乘無倪舟，八極縱遠柂。","燕客期躍馬，唐生安敢譏。","採珠勿驚龍，大道可暗歸。","故山有松月，遲爾翫清暉。"]', '["我本不棄世，世人自棄我。","一乘無倪舟，八極縱远柂。","燕客期躍马，唐生安敢譏。","採珠勿驚龙，大道可暗归。","故山有松月，遲爾翫清暉。"]', '诗', 'shi', '', NULL, '送蔡山人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f394334a-c211-47e1-9a8f-04fb2a368b6e', '送蕭三十一之魯中兼問稚子伯禽', '送蕭三十一之魯中兼问稚子伯禽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["六月南風吹白沙，吳牛喘月氣成霞。","水國鬱蒸不可處，時炎道遠無行車。","夫子如何涉江路，雲帆嫋嫋金陵去。","高堂倚門望伯魚，魯中正是趨庭處。","我家寄在沙丘傍，三年不歸空斷腸。","君行既識伯禽子，應駕小車騎白羊。"]', '["六月南风吹白沙，吳牛喘月氣成霞。","水国鬱蒸不可处，时炎道远無行车。","夫子如何涉江路，云帆嫋嫋金陵去。","高堂倚门望伯鱼，魯中正是趨庭处。","我家寄在沙丘傍，三年不归空斷腸。","君行既識伯禽子，應駕小车騎白羊。"]', '诗', 'shi', '', NULL, '送蕭三十一之魯中兼問稚子伯禽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('581767e0-8a5f-4db3-8855-61b3163c7ad1', '送楊山人歸嵩山', '送楊山人归嵩山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我有萬古宅，嵩陽玉女峰。","長留一片月，挂在東溪松。","爾去掇仙草，菖蒲花紫茸。","歲晚或相訪，青天騎白龍。"]', '["我有万古宅，嵩陽玉女峰。","长留一片月，挂在东溪松。","爾去掇仙草，菖蒲花紫茸。","歲晚或相訪，青天騎白龙。"]', '诗', 'shi', '', NULL, '送楊山人歸嵩山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e42cf58-6dcd-43a4-9aa2-256c33dedaa4', '送殷淑三首 一', '送殷淑三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海水不可解，連江夜爲潮。","俄然蒲嶼闊，岸去酒船遙。","惜別耐取醉，鳴榔且長謠。","天明爾當去，應便有風飄。"]', '["海水不可解，連江夜爲潮。","俄然蒲嶼闊，岸去酒船遙。","惜別耐取醉，鳴榔且长謠。","天明爾當去，應便有风飄。"]', '诗', 'shi', '', NULL, '送殷淑三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd8eece-59e8-4a12-a883-23f87975623f', '送殷淑三首 二', '送殷淑三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白鷺洲前月，天明送客回。","青龍山後日，早出海雲來。","流水無情去，征帆逐吹開。","相看不忍別，更進手中杯。"]', '["白鷺洲前月，天明送客回。","青龙山後日，早出海云来。","流水無情去，征帆逐吹开。","相看不忍別，更進手中杯。"]', '诗', 'shi', '', NULL, '送殷淑三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a33769b-fc5f-499b-9c51-f6148e39b6bd', '送殷淑三首 三', '送殷淑三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["痛飲龍筇下，燈青月復寒。","醉歌驚白鷺，半夜起沙灘。"]', '["痛饮龙筇下，灯青月复寒。","醉歌驚白鷺，半夜起沙灘。"]', '诗', 'shi', '', NULL, '送殷淑三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0054440-69e5-4449-8264-132d442e293a', '送岑徵君歸鳴臯山', '送岑徵君归鳴臯山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["岑公相門子，雅望歸安石。","奕世皆夔龍，中台竟三拆。","至人達機兆，高揖九州伯。","奈何天地間，而作隱淪客。","貴道能全真，潛輝臥幽鄰。","探元入窅默，觀化游無垠。","光武有天下，嚴陵爲故人。","雖登洛陽殿，不屈巢由身。","余亦謝明主，今稱偃蹇臣。","登高覽萬古，思與廣成鄰。","蹈海寧受賞，還山非問津。","西來一搖扇，共拂元規塵。"]', '["岑公相门子，雅望归安石。","奕世皆夔龙，中台竟三拆。","至人達機兆，高揖九州伯。","奈何天地间，而作隐淪客。","貴道能全真，潛輝臥幽鄰。","探元入窅默，观化游無垠。","光武有天下，嚴陵爲故人。","雖登洛陽殿，不屈巢由身。","余亦謝明主，今稱偃蹇臣。","登高覽万古，思與廣成鄰。","蹈海寧受賞，還山非问津。","西来一搖扇，共拂元規塵。"]', '诗', 'shi', '', NULL, '送岑徵君歸鳴臯山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1be5a0f-d53a-4e62-859e-113d59c04fe6', '送范山人歸泰山', '送范山人归泰山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯客抱白鶴，別余往泰山。","初行若片雲，杳在青崖間。","高高至天門，日觀近可攀。","雲山望不及，此去何時還。"]', '["魯客抱白鹤，別余往泰山。","初行若片云，杳在青崖间。","高高至天门，日观近可攀。","云山望不及，此去何时還。"]', '诗', 'shi', '', NULL, '送范山人歸泰山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a21edaa7-dbf6-4eaf-b3b2-4e75862f7796', '送韓侍御之廣德', '送韓侍御之廣德', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔日繡衣何足榮，今宵貰酒與君傾。","暫就東山賒月色，酣歌一夜送泉明。"]', '["昔日繡衣何足榮，今宵貰酒與君傾。","暫就东山賒月色，酣歌一夜送泉明。"]', '诗', 'shi', '', NULL, '送韓侍御之廣德 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e91e6239-120e-4368-8ff1-d6aa69f0b2fe', '送通禪師還南陵隱靜寺', '送通禪師還南陵隐静寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我聞隱靜寺，山水多奇蹤。","巖種朗公橘，門深杯渡松。","道人制猛虎，振錫還孤峰。","他日南陵下，相期谷口逢。"]', '["我闻隐静寺，山水多奇蹤。","巖種朗公橘，门深杯渡松。","道人制猛虎，振錫還孤峰。","他日南陵下，相期谷口逢。"]', '诗', 'shi', '', NULL, '送通禪師還南陵隱靜寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f83fccf-7476-464b-8cd4-8a2b4569c7a0', '送友人', '送友人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青山橫北郭，白水遶東城。","此地一爲別，孤蓬萬里征。","浮雲遊子意，落日故人情。","揮手自茲去，蕭蕭班馬鳴。"]', '["青山橫北郭，白水遶东城。","此地一爲別，孤蓬万里征。","浮云游子意，落日故人情。","揮手自茲去，蕭蕭班马鳴。"]', '诗', 'shi', '', NULL, '送友人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9a4eff-8500-475e-ba0c-7799f8e76346', '送別', '送別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["斗酒渭城邊，壚頭醉不眠。","梨花千樹雪，楊葉萬條煙。","惜別傾壺醑，臨分贈馬鞭。","看君潁上去，新月到應圓。"]', '["斗酒渭城邊，壚头醉不眠。","梨花千樹雪，楊葉万條煙。","惜別傾壺醑，臨分贈马鞭。","看君潁上去，新月到應圓。"]', '诗', 'shi', '', NULL, '送別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b178a1e5-c1cf-42a0-bd17-8c11b5d524fa', '江上送女道士褚三清遊南嶽', '江上送女道士褚三清游南嶽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吳江女道士，頭戴蓮花巾。","霓衣不濕雨，特異陽臺雲。","足下遠遊履，凌波生素塵。","尋仙向南嶽，應見魏夫人。"]', '["吳江女道士，头戴蓮花巾。","霓衣不濕雨，特異陽台云。","足下远游履，凌波生素塵。","尋仙向南嶽，應见魏夫人。"]', '诗', 'shi', '', NULL, '江上送女道士褚三清遊南嶽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972ed983-f073-4cfb-b780-184a9553f458', '送友人入蜀', '送友人入蜀', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["見說蠶叢路，崎嶇不易行。","山從人面起，雲傍馬頭生。","芳樹籠秦棧，春流遶蜀城。","升沉應已定，不必問君平。"]', '["见说蠶叢路，崎嶇不易行。","山從人面起，云傍马头生。","芳樹籠秦棧，春流遶蜀城。","升沉應已定，不必问君平。"]', '诗', 'shi', '', NULL, '送友人入蜀 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e2966af-bfef-446e-8b14-e65dd19958cc', '送李青歸南葉陽川', '送李青归南葉陽川', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["伯陽仙家子，容色如青春。","日月祕靈洞，雲霞辭世人。","化心養精魄，隱几窅天真。","莫作千年別，歸來城郭新。"]', '["伯陽仙家子，容色如青春。","日月祕靈洞，云霞辞世人。","化心養精魄，隐几窅天真。","莫作千年別，归来城郭新。"]', '诗', 'shi', '', NULL, '送李青歸南葉陽川 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84f9fdd-5ef7-44a5-935a-840772cb7c38', '送舍弟', '送舍弟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾家白額駒，遠別臨東道。","他日相思一夢君，應得池塘生春草。"]', '["吾家白額駒，远別臨东道。","他日相思一梦君，應得池塘生春草。"]', '诗', 'shi', '', NULL, '送舍弟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88cbcc21-f372-4656-988c-088b4b1beabd', '送別得書字', '送別得书字', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水色南天遠，舟行若在虛。","遷人發佳興，吾子訪閑居。","日落看歸鳥，潭澄羨躍魚。","聖朝思賈誼，應降紫泥書。"]', '["水色南天远，舟行若在虛。","遷人發佳兴，吾子訪闲居。","日落看归鸟，潭澄羨躍鱼。","聖朝思賈誼，應降紫泥书。"]', '诗', 'shi', '', NULL, '送別得書字 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ef7870-ff4a-46eb-8518-64e0d9a63742', '送麴十少府', '送麴十少府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["試發清秋興，因爲吳會吟。","碧雲歛海色，流水折江心。","我有延陵劍，君無陸賈金。","艱難此爲別，惆悵一何深。"]', '["試發清秋兴，因爲吳會吟。","碧云歛海色，流水折江心。","我有延陵劍，君無陸賈金。","艱难此爲別，惆悵一何深。"]', '诗', 'shi', '', NULL, '送麴十少府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf451ee-3c75-458c-b898-d9b11b5cc887', '送張秀才謁高中丞', '送張秀才謁高中丞', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦帝淪玉鏡，留侯降氛氳。","感激黃石老，經過滄海君。","壯士揮金槌，報讐六國聞。","智勇冠終古，蕭陳難與羣。","兩龍爭鬬時，天地動風雲。","酒酣舞長劍，倉卒解漢紛。","宇宙初倒懸，鴻溝勢將分。","英謀信奇絕，夫子揚清芬。","胡月入紫微，三光亂天文。","高公鎮淮海，談笑却妖氛。","採爾幕中畫，戡難光殊勳。","我無燕霜感，玉石俱燒焚。","但灑一行淚，臨岐竟何云。"]', '["秦帝淪玉镜，留侯降氛氳。","感激黄石老，經過滄海君。","壯士揮金槌，報讐六国闻。","智勇冠終古，蕭陳难與羣。","兩龙爭鬬时，天地动风云。","酒酣舞长劍，倉卒解漢紛。","宇宙初倒懸，鴻溝勢將分。","英謀信奇絕，夫子揚清芬。","胡月入紫微，三光亂天文。","高公鎮淮海，談笑却妖氛。","採爾幕中畫，戡难光殊勳。","我無燕霜感，玉石俱燒焚。","但灑一行泪，臨岐竟何云。"]', '诗', 'shi', '', NULL, '送張秀才謁高中丞 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14eb557e-c913-4fcc-a0d7-9e95b091920f', '尋陽送弟昌峒鄱陽司馬作', '尋陽送弟昌峒鄱陽司马作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桑落洲渚連，滄江無雲煙。","潯陽非剡水，忽見子猷船。","飄然欲相近，來遲杳若仙。","人乘海上月，帆落湖中天。","一覩無二諾，朝懽更勝昨。","爾則吾惠連，吾非爾康樂。","朱紱白銀章，上官佐鄱陽。","松門拂中道，石鏡迴清光。","搖扇及于越，水亭風氣涼。","與爾期此亭，期在秋月滿。","時過或未來，兩鄉心已斷。","吳山對楚岸，彭蠡當中州。","相思定如此，有窮盡年愁。"]', '["桑落洲渚連，滄江無云煙。","潯陽非剡水，忽见子猷船。","飄然欲相近，来遲杳若仙。","人乘海上月，帆落湖中天。","一覩無二諾，朝懽更勝昨。","爾則吾惠連，吾非爾康乐。","朱紱白銀章，上官佐鄱陽。","松门拂中道，石镜迴清光。","搖扇及于越，水亭风氣涼。","與爾期此亭，期在秋月满。","时過或未来，兩乡心已斷。","吳山对楚岸，彭蠡當中州。","相思定如此，有窮尽年愁。"]', '诗', 'shi', '', NULL, '尋陽送弟昌峒鄱陽司馬作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1190a8c-2227-4651-8793-c9090c1b406f', '餞校書叔雲', '餞校书叔云', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["少年費白日，歌笑矜朱顏。","不知忽已老，喜見春風還。","惜別且爲歡，裴回桃李間。","看花飲美酒，聽鳥臨晴山。","向晚竹林寂，無人空閉關。"]', '["少年費白日，歌笑矜朱顏。","不知忽已老，喜见春风還。","惜別且爲歡，裴回桃李间。","看花饮美酒，听鸟臨晴山。","向晚竹林寂，無人空閉关。"]', '诗', 'shi', '', NULL, '餞校書叔雲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07e842a2-5d7c-4c5b-93f1-d485c2661410', '送王孝廉覲省', '送王孝廉覲省', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["彭蠡將天合，姑蘇在日邊。","寧親候海色，欲動孝廉船。","窈窕晴江轉，參差遠岫連。","相思無晝夜，東泣似長川。"]', '["彭蠡將天合，姑蘇在日邊。","寧親候海色，欲动孝廉船。","窈窕晴江轉，參差远岫連。","相思無晝夜，东泣似长川。"]', '诗', 'shi', '', NULL, '送王孝廉覲省 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ddfb05d-8274-4fba-b4be-c5432bb06bff', '同吳王送杜秀芝赴舉入京', '同吳王送杜秀芝赴舉入京', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秀才何翩翩，王許回也賢。","暫別廬江守，將遊京兆天。","秋山宜落日，秀水出寒烟。","欲折一枝桂，還來雁沼前。"]', '["秀才何翩翩，王許回也賢。","暫別廬江守，將游京兆天。","秋山宜落日，秀水出寒烟。","欲折一枝桂，還来雁沼前。"]', '诗', 'shi', '', NULL, '同吳王送杜秀芝赴舉入京 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c91cee-edab-4aeb-8082-743a00ebe9aa', '洞庭醉後送絳州呂使君果流澧州', '洞庭醉後送絳州呂使君果流澧州', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔別若夢中，天涯忽相逢。","洞庭破秋月，縱酒開愁容。","贈劍刻玉字，延平兩蛟龍。","送君不盡意，書及雁迴峯。"]', '["昔別若梦中，天涯忽相逢。","洞庭破秋月，縱酒开愁容。","贈劍刻玉字，延平兩蛟龙。","送君不尽意，书及雁迴峯。"]', '诗', 'shi', '', NULL, '洞庭醉後送絳州呂使君果流澧州 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bac8896f-6fbd-4d45-be8f-3510fb2e548d', '與諸公送陳郎將歸衡陽', '與諸公送陳郎將归衡陽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["衡山蒼蒼入紫冥，下看南極老人星。","迴飆吹散五峰雪，往往飛花落洞庭。","氣清嶽秀有如此，郎將一家拖金紫。","門前食客亂浮雲，世人皆比孟嘗君。","江上送行無白璧，臨歧惆悵若爲分。"]', '["衡山蒼蒼入紫冥，下看南極老人星。","迴飆吹散五峰雪，往往飞花落洞庭。","氣清嶽秀有如此，郎將一家拖金紫。","门前食客亂浮云，世人皆比孟嘗君。","江上送行無白璧，臨歧惆悵若爲分。"]', '诗', 'shi', '', NULL, '與諸公送陳郎將歸衡陽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65eadbc6-65ad-43d6-8b4a-1ba2a0bd0439', '送趙判官赴黔府中丞叔幕', '送趙判官赴黔府中丞叔幕', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["廓落青雲心，交結黃金盡。","富貴翻相忘，令人忽自哂。","蹭蹬鬢毛斑，盛時難再還。","巨源咄石生，何事馬蹄間。","綠蘿長不厭，却欲還東山。","君爲魯曾子，拜揖高堂裏。","叔繼趙平原，偏承明主恩。","風霜推獨坐，旌節鎮雄藩。","虎士秉金鉞，蛾眉開玉樽。","才高幕下去，義重林中言。","水宿五溪月，霜啼三峽猨。","東風春草綠，江上候歸軒。"]', '["廓落青云心，交結黄金尽。","富貴翻相忘，令人忽自哂。","蹭蹬鬢毛斑，盛时难再還。","巨源咄石生，何事马蹄间。","綠蘿长不厭，却欲還东山。","君爲魯曾子，拜揖高堂裏。","叔繼趙平原，偏承明主恩。","风霜推独坐，旌節鎮雄藩。","虎士秉金鉞，蛾眉开玉樽。","才高幕下去，義重林中言。","水宿五溪月，霜啼三峽猨。","东风春草綠，江上候归軒。"]', '诗', 'shi', '', NULL, '送趙判官赴黔府中丞叔幕 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc3c1811-4e94-4507-88f5-8423aed5454d', '送陸判官往琵琶峽', '送陸判官往琵琶峽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水國秋風夜，殊非遠別時。","長安如夢裏，何日是歸期。"]', '["水国秋风夜，殊非远別时。","长安如梦裏，何日是归期。"]', '诗', 'shi', '', NULL, '送陸判官往琵琶峽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b42fe36-c0b8-4a38-ad72-606c96e063df', '送梁四歸東平', '送梁四归东平', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉壺挈美酒，送別強爲歡。","大火南星月，長郊北路難。","殷王期負鼎，汶水起垂竿。","莫學東山臥，參差老謝安。"]', '["玉壺挈美酒，送別強爲歡。","大火南星月，长郊北路难。","殷王期負鼎，汶水起垂竿。","莫学东山臥，參差老謝安。"]', '诗', 'shi', '', NULL, '送梁四歸東平 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e953a156-417e-4dc8-8277-8d0e447ddae9', '江夏送友人', '江夏送友人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雪點翠雲裘，送君黃鶴樓。","黃鶴振玉羽，西飛帝王州。","鳳無瑯玕實，何以贈遠遊。","裴回相顧影，淚下漢江流。"]', '["雪点翠云裘，送君黄鹤楼。","黄鹤振玉羽，西飞帝王州。","鳳無瑯玕實，何以贈远游。","裴回相顧影，泪下漢江流。"]', '诗', 'shi', '', NULL, '江夏送友人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63caa6e1-7b61-44b5-a165-d25866147d31', '送郄昂謫巴中', '送郄昂謫巴中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["瑤草寒不死，移植滄江濱。","東風灑雨露，會入天地春。","予若洞庭葉，隨波送逐臣。","思歸未可得，書此謝情人。"]', '["瑤草寒不死，移植滄江濱。","东风灑雨露，會入天地春。","予若洞庭葉，隨波送逐臣。","思归未可得，书此謝情人。"]', '诗', 'shi', '', NULL, '送郄昂謫巴中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51e83caa-ceda-4586-9109-4ce8d3fe8295', '江夏送張丞', '江夏送張丞', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["欲別心不忍，臨行情更親。","酒傾無限月，客醉幾重春。","藉草依流水，攀花贈遠人。","送君從此去，迴首泣迷津。"]', '["欲別心不忍，臨行情更親。","酒傾無限月，客醉幾重春。","藉草依流水，攀花贈远人。","送君從此去，迴首泣迷津。"]', '诗', 'shi', '', NULL, '江夏送張丞 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c05057-064c-463f-b810-97caadf2da0a', '賦得白鷺鷥送宋少府入三峽', '賦得白鷺鷥送宋少府入三峽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白鷺拳一足，月明秋水寒。","人驚遠飛去，直向使君灘。"]', '["白鷺拳一足，月明秋水寒。","人驚远飞去，直向使君灘。"]', '诗', 'shi', '', NULL, '賦得白鷺鷥送宋少府入三峽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb55610a-61f5-4e16-9f21-aff30f8fc47d', '送二季之江東', '送二季之江东', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["初發强中作，題詩與惠連。","多慚一日長，不及二龍賢。","西塞當中路，南風欲進船。","雲峰出遠海，帆影挂清川。","禹穴藏書地，匡山種杏田。","此行俱有適，遲爾早歸旋。"]', '["初發强中作，題诗與惠連。","多慚一日长，不及二龙賢。","西塞當中路，南风欲進船。","云峰出远海，帆影挂清川。","禹穴藏书地，匡山種杏田。","此行俱有適，遲爾早归旋。"]', '诗', 'shi', '', NULL, '送二季之江東 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('960e1e5c-e218-4104-8f45-9fc62cfd7d6f', '江西送友人之羅浮', '江西送友人之羅浮', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桂水分五嶺，衡山朝九疑。","鄉關渺安西，流浪將何之。","素色愁明湖，秋渚晦寒姿。","疇昔紫芳意，已過黃髮期。","君王縱疎散，雲壑借巢夷。","爾去之羅浮，我還憩峨眉。","中闊道萬里，霞月遙相思。","如尋楚狂子，瓊樹有芳枝。"]', '["桂水分五嶺，衡山朝九疑。","乡关渺安西，流浪將何之。","素色愁明湖，秋渚晦寒姿。","疇昔紫芳意，已過黄髮期。","君王縱疎散，云壑借巢夷。","爾去之羅浮，我還憩峨眉。","中闊道万里，霞月遙相思。","如尋楚狂子，瓊樹有芳枝。"]', '诗', 'shi', '', NULL, '江西送友人之羅浮 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5593d522-b820-4c06-bab6-0ab5a0fc1d46', '宣州謝朓樓餞別校書叔雲', '宣州謝朓楼餞別校书叔云', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["棄我去者昨日之日不可留，亂我心者今日之日多煩憂。","長風萬里送秋雁，對此可以酣高樓。","蓬萊文章建安骨，中間小謝又清發。","俱懷逸興壯思飛，欲上青天覽日月。","抽刀斷水水更流，舉杯銷愁愁更愁。","人生在世不稱意，明朝散髮弄扁舟。"]', '["棄我去者昨日之日不可留，亂我心者今日之日多煩憂。","长风万里送秋雁，对此可以酣高楼。","蓬萊文章建安骨，中间小謝又清發。","俱懷逸兴壯思飞，欲上青天覽日月。","抽刀斷水水更流，舉杯銷愁愁更愁。","人生在世不稱意，明朝散髮弄扁舟。"]', '诗', 'shi', '', NULL, '宣州謝朓樓餞別校書叔雲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('142c446d-7944-4336-836d-cca5c1544299', '宣城送劉副使入秦', '宣城送劉副使入秦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君即劉越石，雄豪冠當時。","淒清橫吹曲，慷慨扶風詞。","虎嘯俟騰躍，雞鳴遭亂離。","千金市駿馬，萬里逐王師。","結交樓煩將，侍從羽林兒。","統兵捍吳越，豺虎不敢窺。","大勳竟莫敘，已過秋風吹。","秉鉞有季公，凜然負英姿。","寄深且戎幕，望重必台司。","感激一然諾，縱橫兩無疑。","伏奏歸北闕，鳴騶忽西馳。","列將咸出祖，英僚惜分離。","斗酒滿四筵，歌嘯宛溪湄。","君攜東山妓，我詠北門詩。","貴賤交不易，恐傷中園葵。","昔贈紫騮駒，今傾白玉巵。","同歡萬斛酒，未足解相思。","此別又千里，秦吳渺天涯。","月明關山苦，水劇隴頭悲。","借問幾時還，春風入黃池。","無令長相憶，折斷綠楊枝。"]', '["君即劉越石，雄豪冠當时。","淒清橫吹曲，慷慨扶风词。","虎嘯俟腾躍，雞鳴遭亂離。","千金市駿马，万里逐王師。","結交楼煩將，侍從羽林兒。","統兵捍吳越，豺虎不敢窺。","大勳竟莫敘，已過秋风吹。","秉鉞有季公，凜然負英姿。","寄深且戎幕，望重必台司。","感激一然諾，縱橫兩無疑。","伏奏归北闕，鳴騶忽西驰。","列將咸出祖，英僚惜分離。","斗酒满四筵，歌嘯宛溪湄。","君携东山妓，我詠北门诗。","貴賤交不易，恐傷中园葵。","昔贈紫騮駒，今傾白玉巵。","同歡万斛酒，未足解相思。","此別又千里，秦吳渺天涯。","月明关山苦，水劇隴头悲。","借问幾时還，春风入黄池。","無令长相憶，折斷綠楊枝。"]', '诗', 'shi', '', NULL, '宣城送劉副使入秦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('106d9d4c-02d5-41b2-b10e-6aeba5134628', '涇川送族弟錞', '涇川送族弟錞', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["涇川三百里，若耶羞見之。","錦石照碧山，兩邊白鷺鷥。","佳境千萬曲，客行無歇時。","上有琴高水，下有陵陽祠。","仙人不見我，明月空相知。","問我何事來，盧敖結幽期。","蓬山振雄筆，繡服揮清詞。","江湖發秀色，草木含榮滋。","置酒送惠連，吾家稱白眉。","愧無海嶠作，敢闕河梁詩。","見爾復幾朝，俄然告將離。","中流漾彩鷁，列岸叢金羈。","歎息蒼梧鳳，分棲瓊樹枝。","清晨各飛去，飄落天南垂。","望極落日盡，秋深暝猨悲。","寄情與流水，但有長相思。"]', '["涇川三百里，若耶羞见之。","錦石照碧山，兩邊白鷺鷥。","佳境千万曲，客行無歇时。","上有琴高水，下有陵陽祠。","仙人不见我，明月空相知。","问我何事来，盧敖結幽期。","蓬山振雄笔，繡服揮清词。","江湖發秀色，草木含榮滋。","置酒送惠連，吾家稱白眉。","愧無海嶠作，敢闕河梁诗。","见爾复幾朝，俄然告將離。","中流漾彩鷁，列岸叢金羈。","歎息蒼梧鳳，分棲瓊樹枝。","清晨各飞去，飄落天南垂。","望極落日尽，秋深暝猨悲。","寄情與流水，但有长相思。"]', '诗', 'shi', '', NULL, '涇川送族弟錞 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea526f7-0c75-442d-9451-0cd306fd9ad0', '五松山送殷淑', '五松山送殷淑', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秀色發江左，風流奈若何。","仲文了不還，獨立揚清波。","載酒五松山，頹然白雲歌。","中天度落月，萬里遙相過。","撫酒惜此月，流光畏蹉跎。","明日別離去，連峰鬱嵯峨。"]', '["秀色發江左，风流奈若何。","仲文了不還，独立揚清波。","載酒五松山，頹然白云歌。","中天度落月，万里遙相過。","撫酒惜此月，流光畏蹉跎。","明日別離去，連峰鬱嵯峨。"]', '诗', 'shi', '', NULL, '五松山送殷淑 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f85ff26-043f-4052-8cce-3162cb5013ae', '送崔氏昆季之金陵', '送崔氏昆季之金陵', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["放歌倚東樓，行子期曉發。","秋風渡江來，吹落山上月。","主人出美酒，滅燭延清光。","二崔向金陵，安得不盡觴。","水客弄歸櫂，雲帆卷輕霜。","扁舟敬亭下，五兩先飄揚。","峽石入水花，碧流日更長。","思君無歲月，西笑阻河梁。"]', '["放歌倚东楼，行子期晓發。","秋风渡江来，吹落山上月。","主人出美酒，滅燭延清光。","二崔向金陵，安得不尽觴。","水客弄归櫂，云帆卷轻霜。","扁舟敬亭下，五兩先飄揚。","峽石入水花，碧流日更长。","思君無歲月，西笑阻河梁。"]', '诗', 'shi', '', NULL, '送崔氏昆季之金陵 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030741a9-3313-4f3a-ade8-fff5f5fb5370', '登黃山凌歊臺送族弟溧陽尉濟充泛舟赴華陰', '登黄山凌歊台送族弟溧陽尉濟充泛舟赴华陰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鸞乃鳳之族，翱翔紫雲霓。","文章輝五色，雙在瓊樹棲。","一朝各飛去，鳳與鸞俱啼。","炎赫五月中，朱曦爍河堤。","爾從泛舟役，使我心魂悽。","秦地無碧草，南雲喧鼓鼙。","君王減玉膳，早起思鳴雞。","漕引救關輔，疲人免塗泥。","宰相作霖雨，農夫得耕犂。","靜者伏草間，羣才滿金閨。","空手無壯士，窮居使人低。","送君登黃山，長嘯倚天梯。","小舟若鳧鴈，大舟若鯨鯢。","開帆散長風，舒卷與雲齊。","日入牛渚晦，蒼然夕煙迷。","相思定何許，杳在洛陽西。"]', '["鸾乃鳳之族，翱翔紫云霓。","文章輝五色，雙在瓊樹棲。","一朝各飞去，鳳與鸾俱啼。","炎赫五月中，朱曦爍河堤。","爾從泛舟役，使我心魂悽。","秦地無碧草，南云喧鼓鼙。","君王減玉膳，早起思鳴雞。","漕引救关輔，疲人免塗泥。","宰相作霖雨，農夫得耕犂。","静者伏草间，羣才满金閨。","空手無壯士，窮居使人低。","送君登黄山，长嘯倚天梯。","小舟若鳧鴈，大舟若鯨鯢。","开帆散长风，舒卷與云齊。","日入牛渚晦，蒼然夕煙迷。","相思定何許，杳在洛陽西。"]', '诗', 'shi', '', NULL, '登黃山凌歊臺送族弟溧陽尉濟充泛舟赴華陰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76e44eb0-9d93-4d3e-a6b2-bb87ba7f200d', '送儲邕之武昌', '送儲邕之武昌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃鶴西樓月，長江萬里情。","春風三十度，空憶武昌城。","送爾難爲別，銜杯惜未傾。","湖連張樂地，山逐泛舟行。","諾爲楚人重，詩傳謝朓清。","滄浪吾有曲，寄入櫂歌聲。"]', '["黄鹤西楼月，长江万里情。","春风三十度，空憶武昌城。","送爾难爲別，銜杯惜未傾。","湖連張乐地，山逐泛舟行。","諾爲楚人重，诗傳謝朓清。","滄浪吾有曲，寄入櫂歌声。"]', '诗', 'shi', '', NULL, '送儲邕之武昌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57a217db-5002-456f-8cea-a3b34391733d', '詶談少府', '詶談少府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一尉居倏忽，梅生有僊骨。","三事或可羞，匈奴哂千秋。","壯士屈黃綬，浪跡寄滄洲。","昨觀荆峴作，如從雲漢遊。","老夫當暮矣，蹀足懼驊騮。"]', '["一尉居倏忽，梅生有僊骨。","三事或可羞，匈奴哂千秋。","壯士屈黄綬，浪跡寄滄洲。","昨观荆峴作，如從云漢游。","老夫當暮矣，蹀足懼驊騮。"]', '诗', 'shi', '', NULL, '詶談少府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('521ad669-99db-4a3f-95b1-21257e042e3a', '詶宇文少府見贈桃竹書筒', '詶宇文少府见贈桃竹书筒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桃竹書筒綺繡文，良工巧妙稱絕羣。","靈心圓映三江月，彩質疊成五色雲。","中藏寶訣峨眉去，千里提攜長憶君。"]', '["桃竹书筒綺繡文，良工巧妙稱絕羣。","靈心圓映三江月，彩質叠成五色云。","中藏寶訣峨眉去，千里提携长憶君。"]', '诗', 'shi', '', NULL, '詶宇文少府見贈桃竹書筒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d883127b-410b-4c45-9007-d1bcaa1c0823', '五月東魯行荅汶上君', '五月东魯行荅汶上君', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["五月梅始黃，蠶凋桑柘空。","魯人重織作，機杼鳴簾櫳。","顧余不及仕，學劍來山東。","舉鞭訪前途，獲笑汶上翁。","下愚忽壯士，未足論窮通。","我以一箭書，能取聊城功。","終然不受賞，羞與時人同。","西歸去直道，落日昏陰虹。","此去爾勿言，甘心爲轉蓬。"]', '["五月梅始黄，蠶凋桑柘空。","魯人重织作，機杼鳴簾櫳。","顧余不及仕，学劍来山东。","舉鞭訪前途，獲笑汶上翁。","下愚忽壯士，未足論窮通。","我以一箭书，能取聊城功。","終然不受賞，羞與时人同。","西归去直道，落日昏陰虹。","此去爾勿言，甘心爲轉蓬。"]', '诗', 'shi', '', NULL, '五月東魯行荅汶上君 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7cff6ef-5554-47d7-95d8-5266f2feb1e3', '早秋單父南樓詶竇公衡', '早秋單父南楼詶竇公衡', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白露見日滅，紅顏隨霜凋。","別君若俯仰，春芳辭秋條。","泰山嵯峨夏雲在，疑是白波漲東海。","散爲飛雨川上來，遙帷却卷清浮埃。","知君獨坐青軒下，此時結念同所懷。","我閉南樓看道書，幽簾清寂在仙居。","曾無好事來相訪，賴爾高文一起予。"]', '["白露见日滅，紅顏隨霜凋。","別君若俯仰，春芳辞秋條。","泰山嵯峨夏云在，疑是白波漲东海。","散爲飞雨川上来，遙帷却卷清浮埃。","知君独坐青軒下，此时結念同所懷。","我閉南楼看道书，幽簾清寂在仙居。","曾無好事来相訪，賴爾高文一起予。"]', '诗', 'shi', '', NULL, '早秋單父南樓詶竇公衡 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c917044e-fd87-42fe-aa91-9f09d7a8a704', '山中問荅', '山中问荅', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["問余何意栖碧山，笑而不荅心自閑。","桃花流水窅然去，別有天地非人間。"]', '["问余何意栖碧山，笑而不荅心自闲。","桃花流水窅然去，別有天地非人间。"]', '诗', 'shi', '', NULL, '山中問荅 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4e822c6-4f27-4e22-8869-ab99a688c8e6', '荅友人贈烏紗帽', '荅友人贈烏紗帽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["領得烏紗帽，全勝白接䍦。","山人不照鏡，稚子道相宜。"]', '["領得烏紗帽，全勝白接䍦。","山人不照镜，稚子道相宜。"]', '诗', 'shi', '', NULL, '荅友人贈烏紗帽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6fd78b7-835f-4e77-8dec-76850d74bdd8', '詶張司馬贈墨', '詶張司马贈墨', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["上黨碧松煙，夷陵丹砂末。","蘭麝凝珍墨，精光乃堪掇。","黃頭奴子雙鴉鬟，錦囊養之懷袖間。","今日贈予蘭亭去，興來灑筆會稽山。"]', '["上黨碧松煙，夷陵丹砂末。","蘭麝凝珍墨，精光乃堪掇。","黄头奴子雙鴉鬟，錦囊養之懷袖间。","今日贈予蘭亭去，兴来灑笔會稽山。"]', '诗', 'shi', '', NULL, '詶張司馬贈墨 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe494e2-d45f-47db-aad6-ceeacdfc52a8', '荅湖州迦葉司馬問白是何人', '荅湖州迦葉司马问白是何人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青蓮居士謫仙人，酒肆藏名三十春。","湖州司馬何須問，金粟如來是後身。"]', '["青蓮居士謫仙人，酒肆藏名三十春。","湖州司马何須问，金粟如来是後身。"]', '诗', 'shi', '', NULL, '荅湖州迦葉司馬問白是何人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be99fd0b-ad10-42b2-9f51-1e001e700ae5', '荅長安崔少府叔封遊終南翠微寺太宗皇帝金沙泉見寄', '荅长安崔少府叔封游終南翠微寺太宗皇帝金沙泉见寄', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["河伯見海若，傲然誇秋水。","小物昧遠圖，寧知通方士。","多君紫霄意，獨往蒼山裏。","地古寒雲深，巖高長風起。","初登翠微嶺，復憩金沙泉。","踐苔朝霜滑，弄波夕月圓。","飲彼石下流，結蘿宿溪煙。","鼎湖夢淥水，龍駕空茫然。","早行子午關，却登山路遠。","拂琴聽霜猨，滅燭乃星飯。","人煙無明異，鳥道絕往返。","攀厓倒青天，下視白日晚。","既過石門隱，還唱石潭歌。","涉雪搴紫芳，濯纓想清波。","此人不可見，此地君自過。","爲余謝風泉，其如幽意何。"]', '["河伯见海若，傲然誇秋水。","小物昧远圖，寧知通方士。","多君紫霄意，独往蒼山裏。","地古寒云深，巖高长风起。","初登翠微嶺，复憩金沙泉。","踐苔朝霜滑，弄波夕月圓。","饮彼石下流，結蘿宿溪煙。","鼎湖梦淥水，龙駕空茫然。","早行子午关，却登山路远。","拂琴听霜猨，滅燭乃星飯。","人煙無明異，鸟道絕往返。","攀厓倒青天，下視白日晚。","既過石门隐，還唱石潭歌。","涉雪搴紫芳，濯纓想清波。","此人不可见，此地君自過。","爲余謝风泉，其如幽意何。"]', '诗', 'shi', '', NULL, '荅長安崔少府叔封遊終南翠微寺太宗皇帝金沙泉見寄 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07433585-ef7a-40ab-bd05-90f4f144f768', '詶崔五郎中', '詶崔五郎中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朔雲橫高天，萬里起秋色。","壯士心飛揚，落日空歎息。","長嘯出原野，凜然寒風生。","幸遭聖明時，功業猶未成。","奈何懷良圖，鬱悒獨愁坐。","杖策尋英豪，立談乃知我。","崔公生民秀，緬邈青雲姿。","制作參造化，託諷含神祇。","海嶽尚可傾，吐諾終不移。","是時霜飆寒，逸興臨華池。","起舞拂長劍，四座皆揚眉。","因得窮懽情，贈我以新詩。","又結汗漫期，九垓遠相待。","舉身憩蓬壺，濯足弄滄海。","從此凌倒景，一去無時還。","朝遊明光宮，暮入閶闔關。","但得長把袂，何必嵩丘山。"]', '["朔云橫高天，万里起秋色。","壯士心飞揚，落日空歎息。","长嘯出原野，凜然寒风生。","幸遭聖明时，功業猶未成。","奈何懷良圖，鬱悒独愁坐。","杖策尋英豪，立談乃知我。","崔公生民秀，緬邈青云姿。","制作參造化，託諷含神祇。","海嶽尚可傾，吐諾終不移。","是时霜飆寒，逸兴臨华池。","起舞拂长劍，四座皆揚眉。","因得窮懽情，贈我以新诗。","又結汗漫期，九垓远相待。","舉身憩蓬壺，濯足弄滄海。","從此凌倒景，一去無时還。","朝游明光宮，暮入閶闔关。","但得长把袂，何必嵩丘山。"]', '诗', 'shi', '', NULL, '詶崔五郎中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c9547a-a949-4d41-b38b-ee3c39464cd7', '以詩代書荅元丹丘', '以诗代书荅元丹丘', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青鳥海上來，今朝發何處。","口銜雲錦字，與我忽飛去。","鳥去凌紫煙，書留綺窗前。","開緘方一笑，乃是故人傳。","故人深相勗，憶我勞心曲。","離居在咸陽，三見秦草綠。","置書雙袂間，引領不暫閑。","長望杳難見，浮雲橫遠山。"]', '["青鸟海上来，今朝發何处。","口銜云錦字，與我忽飞去。","鸟去凌紫煙，书留綺窗前。","开緘方一笑，乃是故人傳。","故人深相勗，憶我勞心曲。","離居在咸陽，三见秦草綠。","置书雙袂间，引領不暫闲。","长望杳难见，浮云橫远山。"]', '诗', 'shi', '', NULL, '以詩代書荅元丹丘 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04549ca6-3a4c-4a3e-b044-4cce3883bd59', '金門荅蘇秀才', '金门荅蘇秀才', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君還石門日，朱火始改木。","春草如有情，山中尚含綠。","折芳愧遙憶，永路當自勗。","遠見故人心，平生以此足。","巨海納百川，麟閣多才賢。","獻書入金闕，酌醴奉瓊筵。","屢忝白雲唱，恭聞黃竹篇。","恩光照拙薄，雲漢希騰遷。","銘鼎倘云逐，扁丹方渺然。","我留在金門，君去臥丹壑。","未果三山期，遙欣一丘樂。","玄珠寄象罔，赤水非寥廓。","願狎東海鷗，共營西山藥。","棲巖君寂滅，處世余龍蠖。","良辰不同賞，永日應閑居。","鳥吟簷間樹，花落窗下書。","緣溪見綠篠，隔岫窺紅蕖。","採薇行笑歌，眷我情何已。","月出石鏡間，松鳴風琴裏。","得心自虛妙，外物空頹靡。","身世如兩忘，從君老煙水。"]', '["君還石门日，朱火始改木。","春草如有情，山中尚含綠。","折芳愧遙憶，永路當自勗。","远见故人心，平生以此足。","巨海納百川，麟閣多才賢。","獻书入金闕，酌醴奉瓊筵。","屢忝白云唱，恭闻黄竹篇。","恩光照拙薄，云漢希腾遷。","銘鼎倘云逐，扁丹方渺然。","我留在金门，君去臥丹壑。","未果三山期，遙欣一丘乐。","玄珠寄象罔，赤水非寥廓。","願狎东海鷗，共營西山藥。","棲巖君寂滅，处世余龙蠖。","良辰不同賞，永日應闲居。","鸟吟簷间樹，花落窗下书。","緣溪见綠篠，隔岫窺紅蕖。","採薇行笑歌，眷我情何已。","月出石镜间，松鳴风琴裏。","得心自虛妙，外物空頹靡。","身世如兩忘，從君老煙水。"]', '诗', 'shi', '', NULL, '金門荅蘇秀才 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4089b003-8676-43b7-8fba-1850766efd93', '詶坊州王司馬與閻正字對雪見贈', '詶坊州王司马與閻正字对雪见贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遊子東南來，自宛適京國。","飄然無心雲，倏忽復西北。","訪戴昔未偶，尋嵇此相得。","愁顏發新懽，終宴敘前識。","閻公漢庭舊，沈鬱富才力。","價重銅龍樓，聲高重門側。","寧期此相遇，華館陪遊息。","積雪明遠峰，寒城鎖春色。","主人蒼生望，假我青雲翼。","風水如見資，投竿佐皇極。"]', '["游子东南来，自宛適京国。","飄然無心云，倏忽复西北。","訪戴昔未偶，尋嵇此相得。","愁顏發新懽，終宴敘前識。","閻公漢庭旧，沈鬱富才力。","價重銅龙楼，声高重门側。","寧期此相遇，华館陪游息。","積雪明远峰，寒城鎖春色。","主人蒼生望，假我青云翼。","风水如见資，投竿佐皇極。"]', '诗', 'shi', '', NULL, '詶坊州王司馬與閻正字對雪見贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db37c733-57f0-4134-9d05-8bd7aca4789a', '詶中都小吏攜斗酒雙魚於逆旅見贈', '詶中都小吏携斗酒雙鱼於逆旅见贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯酒若琥珀，汶魚紫錦鱗。","山東豪吏有俊氣，手攜此物贈遠人。","意氣相傾兩相顧，斗酒雙魚表情素。","雙鰓呀呷鰭鬣張，蹳刺銀盤欲飛去。","呼兒拂几霜刃揮，紅肌花落白雪霏。","爲君下筯一餐飽，醉著金鞍上馬歸。"]', '["魯酒若琥珀，汶鱼紫錦鱗。","山东豪吏有俊氣，手携此物贈远人。","意氣相傾兩相顧，斗酒雙鱼表情素。","雙鰓呀呷鰭鬣張，蹳刺銀盤欲飞去。","呼兒拂几霜刃揮，紅肌花落白雪霏。","爲君下筯一餐飽，醉著金鞍上马归。"]', '诗', 'shi', '', NULL, '詶中都小吏攜斗酒雙魚於逆旅見贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6bd5d14-d55c-4148-ae14-f92d8ca5404a', '詶張卿夜宿南陵見贈', '詶張卿夜宿南陵见贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月出魯城東，明如天上雪。","魯女驚莎雞，鳴機應秋節。","當君相思夜，火落金風高。","河漢挂戶牖，欲濟無輕舠。","我昔辭林丘，雲龍忽相見。","客星動太微，朝去洛陽殿。","爾來得茂彥，七葉仕漢餘。","身爲下邳客，家有圯橋書。","傅說未夢時，終當起巖野。","萬古騎辰星，光輝照天下。","與君各未遇，長策委蒿萊。","寶刀隱玉匣，鏽澀空莓苔。","遂令世上愚，輕我土與灰。","一朝攀龍去，鼃黽安在哉？","故山定有酒，與爾傾金罍。"]', '["月出魯城东，明如天上雪。","魯女驚莎雞，鳴機應秋節。","當君相思夜，火落金风高。","河漢挂戶牖，欲濟無轻舠。","我昔辞林丘，云龙忽相见。","客星动太微，朝去洛陽殿。","爾来得茂彥，七葉仕漢餘。","身爲下邳客，家有圯橋书。","傅说未梦时，終當起巖野。","万古騎辰星，光輝照天下。","與君各未遇，长策委蒿萊。","寶刀隐玉匣，鏽澀空莓苔。","遂令世上愚，轻我土與灰。","一朝攀龙去，鼃黽安在哉？","故山定有酒，與爾傾金罍。"]', '诗', 'shi', '', NULL, '詶張卿夜宿南陵見贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be282475-3b26-49f9-9e82-5e8de52f2938', '詶岑勳見尋就元丹丘對酒相待以詩見招', '詶岑勳见尋就元丹丘对酒相待以诗见招', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃鶴東南來，寄書寫心曲。","倚松開其緘，憶我腸斷續。","不以千里遙，命駕來相招。","中逢元丹丘，登嶺宴碧霄。","對酒忽思我，長嘯臨清飆。","蹇予未相知，茫茫綠雲垂。","俄然素書及，解此長渴飢。","策馬望山月，途窮造階墀。","喜茲一會面，若覩瓊樹枝。","憶君我遠來，我懽方速至。","開顏酌美酒，樂極忽成醉。","我情既不淺，君意方亦深。","相知兩相得，一顧輕千金。","且向山客笑，與君論素心。"]', '["黄鹤东南来，寄书寫心曲。","倚松开其緘，憶我腸斷續。","不以千里遙，命駕来相招。","中逢元丹丘，登嶺宴碧霄。","对酒忽思我，长嘯臨清飆。","蹇予未相知，茫茫綠云垂。","俄然素书及，解此长渴飢。","策马望山月，途窮造階墀。","喜茲一會面，若覩瓊樹枝。","憶君我远来，我懽方速至。","开顏酌美酒，乐極忽成醉。","我情既不淺，君意方亦深。","相知兩相得，一顧轻千金。","且向山客笑，與君論素心。"]', '诗', 'shi', '', NULL, '詶岑勳見尋就元丹丘對酒相待以詩見招 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b1260d3-387d-4279-8ff0-1f3ca652ab89', '荅從弟幼成過西園見贈', '荅從弟幼成過西园见贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一身自瀟灑，萬物何囂諠。","拙薄謝明時，棲閑歸故園。","二季過舊壑，四鄰馳華軒。","衣劍照松宇，賓徒光石門。","山童薦珍果，野老開芳樽。","上陳樵漁事，下敘農圃言。","昨來荷花滿，今見蘭苕繁。","一笑復一歌，不知夕景昏。","醉罷同所樂，此情難具論。"]', '["一身自瀟灑，万物何囂諠。","拙薄謝明时，棲闲归故园。","二季過旧壑，四鄰驰华軒。","衣劍照松宇，賓徒光石门。","山童薦珍果，野老开芳樽。","上陳樵漁事，下敘農圃言。","昨来荷花满，今见蘭苕繁。","一笑复一歌，不知夕景昏。","醉罷同所乐，此情难具論。"]', '诗', 'shi', '', NULL, '荅從弟幼成過西園見贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('063a9180-4dfe-49a1-95ec-ff727e0173b5', '詶王補闕惠翼莊廟宋丞泚贈別', '詶王補闕惠翼莊廟宋丞泚贈別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["學道三千春，自言羲和人。","軒蓋宛若夢，雲松長相親。","偶將二公合，復與三山鄰。","喜結海上契，自爲天外賓。","鸞翮我先鎩，龍性君莫馴。","朴散不尚古，時訛皆失真。","勿踏荒溪坡，朅來浩然津。","薜帶何辭楚，桃源堪避秦。","世迫且離別，心在期隱淪。","酬贈非炯誡，永言銘佩紳。"]', '["学道三千春，自言羲和人。","軒蓋宛若梦，云松长相親。","偶將二公合，复與三山鄰。","喜結海上契，自爲天外賓。","鸾翮我先鎩，龙性君莫馴。","朴散不尚古，时訛皆失真。","勿踏荒溪坡，朅来浩然津。","薜带何辞楚，桃源堪避秦。","世迫且離別，心在期隐淪。","酬贈非炯誡，永言銘佩紳。"]', '诗', 'shi', '', NULL, '詶王補闕惠翼莊廟宋丞泚贈別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc853655-75b8-468b-b213-75cabf00d1fd', '詶裴侍御對雨感時見贈', '詶裴侍御对雨感时见贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雨色秋來寒，風嚴清江爽。","孤高繡衣人，瀟灑青霞賞。","平生多感激，忠義非外獎。","禍連積怨生，事及徂川往。","楚邦有壯士，鄢郢翻掃蕩。","申包哭秦庭，泣血將安仰。","鞭屍辱已及，堂上羅宿莽。","頗似今之人，蟊賊陷忠讜。","渺然一水隔，何由稅歸鞅。","日夕聽猨怨，懷賢盈夢想。"]', '["雨色秋来寒，风嚴清江爽。","孤高繡衣人，瀟灑青霞賞。","平生多感激，忠義非外獎。","禍連積怨生，事及徂川往。","楚邦有壯士，鄢郢翻掃蕩。","申包哭秦庭，泣血將安仰。","鞭屍辱已及，堂上羅宿莽。","頗似今之人，蟊賊陷忠讜。","渺然一水隔，何由稅归鞅。","日夕听猨怨，懷賢盈梦想。"]', '诗', 'shi', '', NULL, '詶裴侍御對雨感時見贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c64927b7-0793-4eeb-8f81-3bc2f5c61ebc', '詶崔侍御', '詶崔侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嚴陵不從萬乘遊，歸臥空山釣碧流。","自是客星辭帝座，元非太白醉揚州。"]', '["嚴陵不從万乘游，归臥空山釣碧流。","自是客星辞帝座，元非太白醉揚州。"]', '诗', 'shi', '', NULL, '詶崔侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfde445a-0083-451f-af51-822c00e6db7a', '翫月金陵城西孫楚酒樓達曙歌吹日晚乘醉著紫綺裘烏紗巾與酒客數人櫂歌秦淮往石頭訪崔四侍御', '翫月金陵城西孫楚酒楼達曙歌吹日晚乘醉著紫綺裘烏紗巾與酒客數人櫂歌秦淮往石头訪崔四侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昨翫西城月，青天垂玉鉤。","朝沽金陵酒，歌吹孫楚樓。","忽憶繡衣人，乘船往石頭。","草裹烏紗巾，倒被紫綺裘。","兩岸拍手笑，疑是王子猷。","酒客十數公，崩騰醉中流。","謔浪櫂海客，喧呼傲陽侯。","半道逢吳姬，卷簾出揶揄。","我憶君到此，不知狂與羞。","一月一見君，三杯便回橈。","舍舟共連袂，行上南渡橋。","興發歌綠水，秦客爲之搖。","雞鳴復相招，清宴逸雲霄。","贈我數百字，字字凌風飆。","繫之衣裘上，相憶每長謠。"]', '["昨翫西城月，青天垂玉鉤。","朝沽金陵酒，歌吹孫楚楼。","忽憶繡衣人，乘船往石头。","草裹烏紗巾，倒被紫綺裘。","兩岸拍手笑，疑是王子猷。","酒客十數公，崩腾醉中流。","謔浪櫂海客，喧呼傲陽侯。","半道逢吳姬，卷簾出揶揄。","我憶君到此，不知狂與羞。","一月一见君，三杯便回橈。","舍舟共連袂，行上南渡橋。","兴發歌綠水，秦客爲之搖。","雞鳴复相招，清宴逸云霄。","贈我數百字，字字凌风飆。","繫之衣裘上，相憶每长謠。"]', '诗', 'shi', '', NULL, '翫月金陵城西孫楚酒樓達曙歌吹日晚乘醉著紫綺裘烏紗巾與酒客數人櫂歌秦淮往石頭訪崔四侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a3b471-ec83-4f0f-9229-a42c7ebff998', '江上答崔宣城', '江上答崔宣城', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["太華三芙蓉，明星玉女峰。","尋仙下西嶽，陶令忽相逢。","問我將何事，湍波歷幾重。","貂裘非季子，鶴氅似王恭。","謬忝燕臺召，而陪郭隗蹤。","水流知入海，雲去或從龍。","樹繞蘆洲月，山鳴鵲鎮鐘。","還期如可訪，台嶺蔭長松。"]', '["太华三芙蓉，明星玉女峰。","尋仙下西嶽，陶令忽相逢。","问我將何事，湍波歷幾重。","貂裘非季子，鹤氅似王恭。","謬忝燕台召，而陪郭隗蹤。","水流知入海，云去或從龙。","樹繞蘆洲月，山鳴鵲鎮鐘。","還期如可訪，台嶺蔭长松。"]', '诗', 'shi', '', NULL, '江上答崔宣城 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d389abf1-07e8-42f3-a9dc-6d2b22e13b37', '答族姪僧中孚贈玉泉仙人掌茶', '答族姪僧中孚贈玉泉仙人掌茶', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["常聞玉泉山，山洞多乳窟。","仙鼠如白鴉，倒懸清溪月。","茗生此中石，玉泉流不歇。","根柯灑芳津，採服潤肌骨。","叢老卷綠葉，枝枝相接連。","曝成仙人掌，似拍洪崖肩。","舉世未見之，其名定誰傳。","宗英乃禪伯，投贈有佳篇。","清鏡燭無鹽，顧慚西子妍。","朝坐有餘興，長吟播諸天。"]', '["常闻玉泉山，山洞多乳窟。","仙鼠如白鴉，倒懸清溪月。","茗生此中石，玉泉流不歇。","根柯灑芳津，採服潤肌骨。","叢老卷綠葉，枝枝相接連。","曝成仙人掌，似拍洪崖肩。","舉世未见之，其名定誰傳。","宗英乃禪伯，投贈有佳篇。","清镜燭無鹽，顧慚西子妍。","朝坐有餘兴，长吟播諸天。"]', '诗', 'shi', '', NULL, '答族姪僧中孚贈玉泉仙人掌茶 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30df8cfb-4e71-49b9-96e3-a8b770d50dd0', '詶裴侍御留岫師彈琴見寄', '詶裴侍御留岫師彈琴见寄', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君同鮑明遠，邀彼休上人。","鼓琴亂白雪，秋變江上春。","瑤草綠未衰，攀翻寄情親。","相思兩不見，流淚空盈巾。"]', '["君同鲍明远，邀彼休上人。","鼓琴亂白雪，秋变江上春。","瑤草綠未衰，攀翻寄情親。","相思兩不见，流泪空盈巾。"]', '诗', 'shi', '', NULL, '詶裴侍御留岫師彈琴見寄 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8338e3db-3f5d-49fa-b1c1-1ebcc9678d27', '張相公出鎮荆州尋除太子詹事余時流夜郎行至江夏與張公去千里公因太府丞王昔使車寄羅衣二事及五月五日贈余詩余答以此詩', '張相公出鎮荆州尋除太子詹事余时流夜郎行至江夏與張公去千里公因太府丞王昔使车寄羅衣二事及五月五日贈余诗余答以此诗', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["張衡殊不樂，應有四愁詩。","慙君錦繡段，贈我慰相思。","鴻鵠復矯翼，鳳凰憶故池。","榮樂一如此，商山老紫芝。"]', '["張衡殊不乐，應有四愁诗。","慙君錦繡段，贈我慰相思。","鴻鵠复矯翼，鳳凰憶故池。","榮乐一如此，商山老紫芝。"]', '诗', 'shi', '', NULL, '張相公出鎮荆州尋除太子詹事余時流夜郎行至江夏與張公去千里公因太府丞王昔使車寄羅衣二事及五月五日贈余詩余答以此詩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1224475-cb04-43fc-8d0c-3e901f65f656', '醉後荅丁十八以詩譏余搥碎黃鶴樓', '醉後荅丁十八以诗譏余搥碎黄鹤楼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃鶴高樓已槌碎，黃鶴仙人無所依。","黃鶴上天訴玉帝，卻放黃鶴江南歸。","神明太守再雕飾，新圖粉壁還芳菲。","一州笑我爲狂客，少年往往來相譏。","君平簾下誰家子，云是遼東丁令威。","作詩調我驚逸興，白雲遶筆窗前飛。","待取明朝酒醒罷，與君爛漫尋春暉。"]', '["黄鹤高楼已槌碎，黄鹤仙人無所依。","黄鹤上天訴玉帝，卻放黄鹤江南归。","神明太守再雕飾，新圖粉壁還芳菲。","一州笑我爲狂客，少年往往来相譏。","君平簾下誰家子，云是遼东丁令威。","作诗調我驚逸兴，白云遶笔窗前飞。","待取明朝酒醒罷，與君爛漫尋春暉。"]', '诗', 'shi', '', NULL, '醉後荅丁十八以詩譏余搥碎黃鶴樓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921a744a-2466-41be-966f-b31ae16c5b01', '荅裴侍御先行至石頭驛以書見招期月滿泛洞庭', '荅裴侍御先行至石头驛以书见招期月满泛洞庭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君至石頭驛，寄書黃鶴樓。","開緘識遠意，速此南行舟。","風水無定準，湍波或滯留。","憶昨新月生，西簷若瓊鉤。","今來何所似，破鏡懸清秋。","恨不三五明，平湖泛澄流。","此歡竟莫遂，狂殺王子猷。","巴陵定遙遠，持贈解人憂。"]', '["君至石头驛，寄书黄鹤楼。","开緘識远意，速此南行舟。","风水無定準，湍波或滯留。","憶昨新月生，西簷若瓊鉤。","今来何所似，破镜懸清秋。","恨不三五明，平湖泛澄流。","此歡竟莫遂，狂殺王子猷。","巴陵定遙远，持贈解人憂。"]', '诗', 'shi', '', NULL, '荅裴侍御先行至石頭驛以書見招期月滿泛洞庭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eafb2468-0e6a-4369-9c68-1aa857ed4a9d', '荅高山人兼呈權顧二侯', '荅高山人兼呈權顧二侯', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["虹霓掩天光，哲后起康濟。","應運生夔龍，開元掃氛翳。","太微廓金鏡，端拱清遐裔。","輕塵集嵩嶽，虛點盛明意。","謬揮紫泥詔，獻納青雲際。","讒惑英主心，恩疎佞臣計。","仿徨庭闕下，歎息光陰逝。","未作仲宣詩，先流賈生涕。","挂帆秋江上，不爲雲羅制。","山海向東傾，百川無盡勢。","我於鴟夷子，相去千餘歲。","運闊英達稀，同風遙執袂。","登艫望遠水，忽見滄浪枻。","高士何處來，虛舟渺安繫。","衣貌本淳古，文章多佳麗。","延引故鄉人，風義未淪替。","顧侯達語默，權子識通蔽。","曾是無心雲，俱爲此留滯。","雙萍易飄轉，獨鶴思凌厲。","明晨去瀟湘，共謁蒼梧帝。"]', '["虹霓掩天光，哲后起康濟。","應運生夔龙，开元掃氛翳。","太微廓金镜，端拱清遐裔。","轻塵集嵩嶽，虛点盛明意。","謬揮紫泥詔，獻納青云際。","讒惑英主心，恩疎佞臣計。","仿徨庭闕下，歎息光陰逝。","未作仲宣诗，先流賈生涕。","挂帆秋江上，不爲云羅制。","山海向东傾，百川無尽勢。","我於鴟夷子，相去千餘歲。","運闊英達稀，同风遙執袂。","登艫望远水，忽见滄浪枻。","高士何处来，虛舟渺安繫。","衣貌本淳古，文章多佳丽。","延引故乡人，风義未淪替。","顧侯達語默，權子識通蔽。","曾是無心云，俱爲此留滯。","雙萍易飄轉，独鹤思凌厲。","明晨去瀟湘，共謁蒼梧帝。"]', '诗', 'shi', '', NULL, '荅高山人兼呈權顧二侯 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dabdeffb-da9c-4f45-9b12-b421f5f15fd6', '荅杜秀才五松見贈', '荅杜秀才五松见贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔獻長楊賦，天開雲雨歡。","當時待詔承明裏，皆道揚雄才可觀。","勅賜飛龍二天馬，黃金絡頭白玉鞍。","浮雲蔽日去不返，總爲秋風摧紫蘭。","角巾東出商山道，採秀行歌詠芝草。","路逢園綺笑向人，兩君解來一何好。","聞道金陵龍虎盤，還同謝朓望長安。","千峰夾水向秋浦，五松名山當夏寒。","銅井炎爐歊九天，赫如鑄鼎荆山前。","陶公瞿鑠呵赤電，回祿睢盱揚紫煙。","此中豈是久留處，便欲燒丹從列仙。","愛聽松風且高臥，颼颼吹盡炎氛過。","登崖獨立望九州，陽春欲奏誰相和。","聞君往年遊錦城，章仇尚書倒屣迎。","飛箋洛繹奏明主，天書降問迴恩榮。","骯髒不能就珪組，至今空揚高蹈名。","夫子工文絕世奇，五松新作天下推。","吾非謝尚邀彥伯，異代風流各一時。","一時相逢樂在今，袖拂白雲開素琴，彈爲三峽流泉音。","從茲一別武陵去，去後桃花春水深。"]', '["昔獻长楊賦，天开云雨歡。","當时待詔承明裏，皆道揚雄才可观。","勅賜飞龙二天马，黄金絡头白玉鞍。","浮云蔽日去不返，總爲秋风摧紫蘭。","角巾东出商山道，採秀行歌詠芝草。","路逢园綺笑向人，兩君解来一何好。","闻道金陵龙虎盤，還同謝朓望长安。","千峰夾水向秋浦，五松名山當夏寒。","銅井炎爐歊九天，赫如鑄鼎荆山前。","陶公瞿鑠呵赤電，回祿睢盱揚紫煙。","此中豈是久留处，便欲燒丹從列仙。","愛听松风且高臥，颼颼吹尽炎氛過。","登崖独立望九州，陽春欲奏誰相和。","闻君往年游錦城，章仇尚书倒屣迎。","飞箋洛繹奏明主，天书降问迴恩榮。","骯髒不能就珪組，至今空揚高蹈名。","夫子工文絕世奇，五松新作天下推。","吾非謝尚邀彥伯，異代风流各一时。","一时相逢乐在今，袖拂白云开素琴，彈爲三峽流泉音。","從茲一別武陵去，去後桃花春水深。"]', '诗', 'shi', '', NULL, '荅杜秀才五松見贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4650220-b06a-4ab1-809c-974a850d795d', '至陵陽山登天柱石詶韓侍御見招隱黃山', '至陵陽山登天柱石詶韓侍御见招隐黄山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["韓衆騎白鹿，西往華山中。","玉女千餘人，相隨在雲空。","見我傳祕訣，精誠與天通。","何意到陵陽，遊目送飛鴻。","天子昔避狄，與君亦乘驄。","擁兵五陵下，長策遏胡戎。","時泰解繡衣，脫身若飛蓬。","鸞鳳翻羽翼，啄粟坐樊籠。","海鶴一笑之，思歸向遼東。","黃山過石柱，巘崿上攢叢。","因巢翠玉樹，忽見浮丘公。","又引王子喬，吹笙舞松風。","朗詠紫霞篇，請開蘂珠宮。","步綱繞碧落，倚樹招青童。","何日可攜手，遺形入無窮。"]', '["韓衆騎白鹿，西往华山中。","玉女千餘人，相隨在云空。","见我傳祕訣，精誠與天通。","何意到陵陽，游目送飞鴻。","天子昔避狄，與君亦乘驄。","擁兵五陵下，长策遏胡戎。","时泰解繡衣，脫身若飞蓬。","鸾鳳翻羽翼，啄粟坐樊籠。","海鹤一笑之，思归向遼东。","黄山過石柱，巘崿上攢叢。","因巢翠玉樹，忽见浮丘公。","又引王子喬，吹笙舞松风。","朗詠紫霞篇，請开蘂珠宮。","步綱繞碧落，倚樹招青童。","何日可携手，遺形入無窮。"]', '诗', 'shi', '', NULL, '至陵陽山登天柱石詶韓侍御見招隱黃山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3c2df6-a096-484b-93de-3ed3d24f8d70', '詶崔十五見招', '詶崔十五见招', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["爾有鳥跡書，相招琴溪飲。","手跡尺素中，如天落雲錦。","讀罷向空笑，疑君在我前。","長吟字不滅，懷袖且三年。"]', '["爾有鸟跡书，相招琴溪饮。","手跡尺素中，如天落云錦。","读罷向空笑，疑君在我前。","长吟字不滅，懷袖且三年。"]', '诗', 'shi', '', NULL, '詶崔十五見招 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4c4c27-28fc-43cf-a53f-9ada39b65d94', '荅王十二寒夜獨酌有懷', '荅王十二寒夜独酌有懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昨夜吳中雪，子猷佳興發。","萬里浮雲卷碧山，青天中道流孤月。","孤月滄浪河漢清，北斗錯落長庚明。","懷余對酒夜霜白，玉牀金井水崢嶸。","人生飄忽百年內，且須酣暢萬古情。","君不能狸膏金距學鬬雞，坐令鼻息吹虹霓。","君不能學哥舒橫行青海夜帶刀，西屠石堡取紫袍。","吟詩作賦北牕裏，萬言不直一杯水。","世人聞此皆掉頭，有如東風射馬耳。","魚目亦笑我，請與明月同。","驊騮拳跼不能食，蹇驢得志鳴春風。","折楊皇華合流俗，晉君聽琴枉清角。","巴人誰肯和陽春，楚地由來賤奇璞。","黃金散盡交不成，白首爲儒身被輕。","一談一笑失顏色，蒼蠅貝錦喧謗聲。","曾參豈是殺人者，讒言三及慈母驚。","與君論心握君手，榮辱於余亦何有。","孔聖猶聞傷鳳麟，董龍更是何雞狗。","一生傲岸苦不諧，恩疎媒勞志多乖。","嚴陵高揖漢天子，何必長劍拄頤事玉階。","達亦不足貴，窮亦不足悲。","韓信羞將絳灌比，禰衡恥逐屠沽兒。","君不見李北海，英風豪氣今何在？","君不見裴尚書，土墳三尺蒿棘居。","少年早欲五湖去，見此彌將鐘鼎疎。"]', '["昨夜吳中雪，子猷佳兴發。","万里浮云卷碧山，青天中道流孤月。","孤月滄浪河漢清，北斗錯落长庚明。","懷余对酒夜霜白，玉牀金井水崢嶸。","人生飄忽百年內，且須酣暢万古情。","君不能狸膏金距学鬬雞，坐令鼻息吹虹霓。","君不能学哥舒橫行青海夜带刀，西屠石堡取紫袍。","吟诗作賦北牕裏，万言不直一杯水。","世人闻此皆掉头，有如东风射马耳。","鱼目亦笑我，請與明月同。","驊騮拳跼不能食，蹇驢得志鳴春风。","折楊皇华合流俗，晉君听琴枉清角。","巴人誰肯和陽春，楚地由来賤奇璞。","黄金散尽交不成，白首爲儒身被轻。","一談一笑失顏色，蒼蠅貝錦喧謗声。","曾參豈是殺人者，讒言三及慈母驚。","與君論心握君手，榮辱於余亦何有。","孔聖猶闻傷鳳麟，董龙更是何雞狗。","一生傲岸苦不諧，恩疎媒勞志多乖。","嚴陵高揖漢天子，何必长劍拄頤事玉階。","達亦不足貴，窮亦不足悲。","韓信羞將絳灌比，禰衡恥逐屠沽兒。","君不见李北海，英风豪氣今何在？","君不见裴尚书，土墳三尺蒿棘居。","少年早欲五湖去，见此彌將鐘鼎疎。"]', '诗', 'shi', '', NULL, '荅王十二寒夜獨酌有懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('591b076f-722d-439e-8ce1-d934b5b87e07', '遊南陽白水登石激作', '游南陽白水登石激作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝涉白水源，暫與人俗疎。","島嶼佳境色，江天涵清虛。","目送去海雲，心閑遊川魚。","長歌盡落日，乘月歸田廬。"]', '["朝涉白水源，暫與人俗疎。","島嶼佳境色，江天涵清虛。","目送去海云，心闲游川鱼。","长歌尽落日，乘月归田廬。"]', '诗', 'shi', '', NULL, '遊南陽白水登石激作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb92cd5b-f833-4dc6-b0b4-6d7f45cc651b', '遊南陽清泠泉', '游南陽清泠泉', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["惜彼落日暮，愛此寒泉清。","西輝逐流水，蕩漾遊子情。","空歌望雲月，曲盡長松聲。"]', '["惜彼落日暮，愛此寒泉清。","西輝逐流水，蕩漾游子情。","空歌望云月，曲尽长松声。"]', '诗', 'shi', '', NULL, '遊南陽清泠泉 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbfe3dd9-ea4a-4130-8e31-b3fc0acd90bf', '尋魯城北范居士失道落蒼耳中見范置酒摘蒼耳作', '尋魯城北范居士失道落蒼耳中见范置酒摘蒼耳作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雁度秋色遠，日靜無雲時。","客心不自得，浩漫將何之。","忽憶范野人，閑園養幽姿。","茫然起逸興，但恐行來遲。","城壕失往路，馬首迷荒陂。","不惜翠雲裘，遂爲蒼耳欺。","入門且一笑，把臂君爲誰。","酒客愛秋蔬，山盤薦霜梨。","他筵不下筯，此席忘朝飢。","酸棗垂北郭，寒瓜蔓東籬。","還傾四五酌，自詠猛虎詞。","近作十日歡，遠爲千載期。","風流自簸蕩，謔浪偏相宜。","酣來上馬去，却笑高陽池。"]', '["雁度秋色远，日静無云时。","客心不自得，浩漫將何之。","忽憶范野人，闲园養幽姿。","茫然起逸兴，但恐行来遲。","城壕失往路，马首迷荒陂。","不惜翠云裘，遂爲蒼耳欺。","入门且一笑，把臂君爲誰。","酒客愛秋蔬，山盤薦霜梨。","他筵不下筯，此席忘朝飢。","酸棗垂北郭，寒瓜蔓东籬。","還傾四五酌，自詠猛虎词。","近作十日歡，远爲千載期。","风流自簸蕩，謔浪偏相宜。","酣来上马去，却笑高陽池。"]', '诗', 'shi', '', NULL, '尋魯城北范居士失道落蒼耳中見范置酒摘蒼耳作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b0b448-8d15-461e-b806-7d94fcb66f49', '東魯門泛舟二首 一', '东魯门泛舟二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日落沙明天倒開，波搖石動水縈迴。","輕舟泛月尋溪轉，疑是山隱雪後來。"]', '["日落沙明天倒开，波搖石动水縈迴。","轻舟泛月尋溪轉，疑是山隐雪後来。"]', '诗', 'shi', '', NULL, '東魯門泛舟二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb386a3-6488-46f1-a53d-c5a4a2e0b90d', '東魯門泛舟二首 二', '东魯门泛舟二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水作青龍盤石堤，桃花夾岸魯門西。","若教月下乘舟去，何啻風流到剡溪。"]', '["水作青龙盤石堤，桃花夾岸魯门西。","若教月下乘舟去，何啻风流到剡溪。"]', '诗', 'shi', '', NULL, '東魯門泛舟二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f8f5fe7-eae7-4e94-acd2-3b712e629ae3', '秋獵孟諸夜歸置酒單父東樓觀妓', '秋獵孟諸夜归置酒單父东楼观妓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["傾暉速短炬，走海無停川。","冀餐圓丘草，欲以還頹年。","此事不可得，微生若浮煙。","駿發跨名駒，雕弓控鳴弦。","鷹豪魯草白，狐兔多肥鮮。","邀遮相馳逐，遂出城東田。","一掃四野空，喧呼鞍馬前。","歸來獻所獲，炮炙宜霜天。","出舞兩美人，飄颻若雲仙。","留歡不知疲，清曉方來旋。"]', '["傾暉速短炬，走海無停川。","冀餐圓丘草，欲以還頹年。","此事不可得，微生若浮煙。","駿發跨名駒，雕弓控鳴弦。","鷹豪魯草白，狐兔多肥鲜。","邀遮相驰逐，遂出城东田。","一掃四野空，喧呼鞍马前。","归来獻所獲，炮炙宜霜天。","出舞兩美人，飄颻若云仙。","留歡不知疲，清晓方来旋。"]', '诗', 'shi', '', NULL, '秋獵孟諸夜歸置酒單父東樓觀妓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25b6402c-ca6d-4bcb-8a91-fa17eb8a99a9', '遊泰山六首 一', '游泰山六首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["四月上泰山，石屏御道開。","六龍過萬壑，澗谷隨縈迴。","馬跡遶碧峯，于今滿青苔。","飛流灑絕巘，水急松聲哀。","北眺崿嶂奇，傾崖向東摧。","洞門閉石扇，地底興雲雷。","登高望蓬瀛，想象金銀臺。","天門一長嘯，萬里清風來。","玉女四五人，飄颻下九垓。","含笑引素手，遺我流霞杯。","稽首再拜之，自愧非仙才。","曠然小宇宙，棄世何悠哉。"]', '["四月上泰山，石屏御道开。","六龙過万壑，澗谷隨縈迴。","马跡遶碧峯，于今满青苔。","飞流灑絕巘，水急松声哀。","北眺崿嶂奇，傾崖向东摧。","洞门閉石扇，地底兴云雷。","登高望蓬瀛，想象金銀台。","天门一长嘯，万里清风来。","玉女四五人，飄颻下九垓。","含笑引素手，遺我流霞杯。","稽首再拜之，自愧非仙才。","曠然小宇宙，棄世何悠哉。"]', '诗', 'shi', '', NULL, '遊泰山六首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a6fda5-a253-4172-87e8-04f071d1f6f5', '遊泰山六首 二', '游泰山六首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清曉騎白鹿，直上天門山。","山際逢羽人，方瞳好容顏。","捫蘿欲就語，却掩青雲關。","遺我鳥跡書，飄然落巖間。","其字乃上古，讀之了不閑。","感此三歎息，從師方未還。"]', '["清晓騎白鹿，直上天门山。","山際逢羽人，方瞳好容顏。","捫蘿欲就語，却掩青云关。","遺我鸟跡书，飄然落巖间。","其字乃上古，读之了不闲。","感此三歎息，從師方未還。"]', '诗', 'shi', '', NULL, '遊泰山六首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('211e6b5b-433a-44f4-b205-2f00ae6781c6', '遊泰山六首 三', '游泰山六首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["平明登日觀，舉手開雲關。","精神四飛揚，如出天地間。","黃河從西來，窈窕入遠山。","憑崖攬八極，目盡長空閑。","偶然值青童，綠髮雙雲鬟。","笑我晚學仙，蹉跎凋朱顏。","躊躇忽不見，浩蕩難追攀。"]', '["平明登日观，舉手开云关。","精神四飞揚，如出天地间。","黄河從西来，窈窕入远山。","憑崖攬八極，目尽长空闲。","偶然值青童，綠髮雙云鬟。","笑我晚学仙，蹉跎凋朱顏。","躊躇忽不见，浩蕩难追攀。"]', '诗', 'shi', '', NULL, '遊泰山六首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbf0796-7fc7-4cf1-8a9b-bd65a604c6b0', '遊泰山六首 四', '游泰山六首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清齋三千日，裂素寫道經。","吟誦有所得，衆神衛我形。","雲行信長風，颯若羽翼生。","攀崖上日觀，伏檻窺東溟。","海色動遠山，天雞已先鳴。","銀臺出倒景，白浪翻長鯨。","安得不死藥，高飛向蓬瀛。"]', '["清斋三千日，裂素寫道經。","吟誦有所得，衆神衛我形。","云行信长风，颯若羽翼生。","攀崖上日观，伏檻窺东溟。","海色动远山，天雞已先鳴。","銀台出倒景，白浪翻长鯨。","安得不死藥，高飞向蓬瀛。"]', '诗', 'shi', '', NULL, '遊泰山六首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a349100-cd71-49b6-858b-fc40576b8711', '遊泰山六首 五', '游泰山六首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日觀東北傾，兩崖夾雙石。","海水落眼前，天光遙空碧。","千峯爭攢聚，萬壑絕凌歷。","緬彼鶴上仙，去無雲中跡。","長松入雲漢，遠望不盈尺。","山花異人間，五月雪中白。","終當遇安期，於此鍊玉液。"]', '["日观东北傾，兩崖夾雙石。","海水落眼前，天光遙空碧。","千峯爭攢聚，万壑絕凌歷。","緬彼鹤上仙，去無云中跡。","长松入云漢，远望不盈尺。","山花異人间，五月雪中白。","終當遇安期，於此鍊玉液。"]', '诗', 'shi', '', NULL, '遊泰山六首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5066dabc-0991-4da6-b1b4-ef55b625e769', '遊泰山六首 六', '游泰山六首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝飲王母池，暝投天門關。","獨抱綠綺琴，夜行青山間。","山明月露白，夜靜松風歇。","仙人遊碧峯，處處笙歌發。","寂靜娛清暉，玉真連翠微。","想象鸞鳳舞，飄颻龍虎衣。","捫天摘匏瓜，恍惚不憶歸。","舉手弄清淺，誤攀織女機。","明晨坐相失，但見五雲飛。"]', '["朝饮王母池，暝投天门关。","独抱綠綺琴，夜行青山间。","山明月露白，夜静松风歇。","仙人游碧峯，处处笙歌發。","寂静娛清暉，玉真連翠微。","想象鸾鳳舞，飄颻龙虎衣。","捫天摘匏瓜，恍惚不憶归。","舉手弄清淺，誤攀织女機。","明晨坐相失，但见五云飞。"]', '诗', 'shi', '', NULL, '遊泰山六首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37577056-1e0c-458b-80c3-460ff23da105', '秋夜與劉碭山泛宴喜亭池', '秋夜與劉碭山泛宴喜亭池', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["明宰試舟楫，張燈宴華池。","文招梁苑客，歌動郢中兒。","月色望不盡，空天交相宜。","令人欲泛海，只待長風吹。"]', '["明宰試舟楫，張灯宴华池。","文招梁苑客，歌动郢中兒。","月色望不尽，空天交相宜。","令人欲泛海，只待长风吹。"]', '诗', 'shi', '', NULL, '秋夜與劉碭山泛宴喜亭池 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b77eb28-18f7-442c-974a-286a9c65e796', '攜妓登梁王棲霞山孟氏桃園中', '携妓登梁王棲霞山孟氏桃园中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["碧草已滿地，柳與梅爭春。","謝公自有東山妓，金屏笑坐如花人。","今日非昨日，明日還復來。","白髮對綠酒，強歌心已摧。","君不見梁王池上月，昔照梁王樽酒中。","梁王已去明月在，黃鸝愁醉啼春風。","分明感激眼前事，莫惜醉臥桃園東。"]', '["碧草已满地，柳與梅爭春。","謝公自有东山妓，金屏笑坐如花人。","今日非昨日，明日還复来。","白髮对綠酒，強歌心已摧。","君不见梁王池上月，昔照梁王樽酒中。","梁王已去明月在，黄鸝愁醉啼春风。","分明感激眼前事，莫惜醉臥桃园东。"]', '诗', 'shi', '', NULL, '攜妓登梁王棲霞山孟氏桃園中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1743f743-b5f7-4403-945f-4e10e20da60a', '與從姪杭州刺史良遊天竺寺', '與從姪杭州刺史良游天竺寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["挂席凌蓬丘，觀濤憩樟樓。","三山動逸興，五馬同遨遊。","天竺森在眼，松風颯驚秋。","覽雲測變化，弄水窮清幽。","疊嶂隔遙海，當軒寫歸流。","詩成傲雲月，佳趣滿吳洲。"]', '["挂席凌蓬丘，观濤憩樟楼。","三山动逸兴，五马同遨游。","天竺森在眼，松风颯驚秋。","覽云測变化，弄水窮清幽。","叠嶂隔遙海，當軒寫归流。","诗成傲云月，佳趣满吳洲。"]', '诗', 'shi', '', NULL, '與從姪杭州刺史良遊天竺寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0084e4f7-d47a-4a2b-8804-1b7b5c9d9220', '同友人舟行遊台越作', '同友人舟行游台越作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["楚臣傷江楓，謝客拾海月。","懷沙去瀟湘，挂席泛溟渤。","蹇予訪前跡，獨往造窮髮。","古人不可攀，去若浮雲沒。","願言弄倒景，從此鍊真骨。","華頂窺絕溟，蓬壺望超忽。","不知青春度，但怪綠芳歇。","空持釣鼇心，從此謝魏闕。"]', '["楚臣傷江楓，謝客拾海月。","懷沙去瀟湘，挂席泛溟渤。","蹇予訪前跡，独往造窮髮。","古人不可攀，去若浮云沒。","願言弄倒景，從此鍊真骨。","华頂窺絕溟，蓬壺望超忽。","不知青春度，但怪綠芳歇。","空持釣鼇心，從此謝魏闕。"]', '诗', 'shi', '', NULL, '同友人舟行遊台越作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4cc6b3-a324-48c0-89c0-bb36c09c4930', '下終南山過斛斯山人宿置酒', '下終南山過斛斯山人宿置酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["暮從碧山下，山月隨人歸。","却顧所來徑，蒼蒼橫翠微。","相攜及田家，童稚開荆扉。","綠竹入幽徑，青蘿拂行衣。","歡言得所憩，美酒聊共揮。","長歌吟松風，曲盡河星稀。","我醉君復樂，陶然共忘機。"]', '["暮從碧山下，山月隨人归。","却顧所来徑，蒼蒼橫翠微。","相携及田家，童稚开荆扉。","綠竹入幽徑，青蘿拂行衣。","歡言得所憩，美酒聊共揮。","长歌吟松风，曲尽河星稀。","我醉君复乐，陶然共忘機。"]', '诗', 'shi', '', NULL, '下終南山過斛斯山人宿置酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4fbfaa7-4355-4357-b6aa-292e8b2cb05c', '朝下過盧郎中敘舊遊', '朝下過盧郎中敘旧游', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君登金華省，我入銀臺門。","幸遇聖明主，俱承雲雨恩。","復此休浣時，閑爲疇昔言。","却話山海事，宛然林壑存。","明湖思曉月，疊嶂憶清猿。","何由返初服，田野醉芳樽。"]', '["君登金华省，我入銀台门。","幸遇聖明主，俱承云雨恩。","复此休浣时，闲爲疇昔言。","却話山海事，宛然林壑存。","明湖思晓月，叠嶂憶清猿。","何由返初服，田野醉芳樽。"]', '诗', 'shi', '', NULL, '朝下過盧郎中敘舊遊 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2310cb5d-4326-4bb8-b1ed-69321e803e0b', '侍從遊宿溫泉宮作', '侍從游宿溫泉宮作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["羽林十二將，羅列應星文。","霜仗懸秋月，霓旌卷夜雲。","嚴更千戶肅，清樂九天聞。","日出瞻佳氣，蔥蔥繞聖君。"]', '["羽林十二將，羅列應星文。","霜仗懸秋月，霓旌卷夜云。","嚴更千戶肅，清乐九天闻。","日出瞻佳氣，蔥蔥繞聖君。"]', '诗', 'shi', '', NULL, '侍從遊宿溫泉宮作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3563ce30-ecca-41e1-ba9a-79feea89b8d6', '邯鄲南亭觀妓', '邯鄲南亭观妓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["歌鼓燕趙兒，魏姝弄鳴絲。","粉色豔日彩，舞袖拂花枝。","把酒顧美人，請歌邯鄲詞。","清箏何繚繞，度曲綠雲垂。","平原君安在，科斗生古池。","座客三千人，于今知有誰。","我輩不作樂，但爲後代悲。"]', '["歌鼓燕趙兒，魏姝弄鳴絲。","粉色豔日彩，舞袖拂花枝。","把酒顧美人，請歌邯鄲词。","清箏何繚繞，度曲綠云垂。","平原君安在，科斗生古池。","座客三千人，于今知有誰。","我輩不作乐，但爲後代悲。"]', '诗', 'shi', '', NULL, '邯鄲南亭觀妓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa65e1c8-1b13-47d6-919b-e50f7ae5d10a', '春日遊羅敷潭', '春日游羅敷潭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["行歌入谷口，路盡無人躋。","攀崖度絕壑，弄水尋迴溪。","雲從石上起，客到花間迷。","淹留未盡興，日落羣峯西。"]', '["行歌入谷口，路尽無人躋。","攀崖度絕壑，弄水尋迴溪。","云從石上起，客到花间迷。","淹留未尽兴，日落羣峯西。"]', '诗', 'shi', '', NULL, '春日遊羅敷潭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2846a5c-282d-4d64-95d0-c6e8906ce700', '春陪商州裴使君遊石娥溪', '春陪商州裴使君游石娥溪', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["裴公有僊標，拔俗數千丈。","澹蕩滄洲雲，飄颻紫霞想。","剖竹商洛間，政成心已閑。","蕭條出世表，冥寂閉玄關。","我來屬芳節，解榻時相悅。","褰帷對雲峯，揚袂指松雪。","蹔出東城邊，遂遊西巖前。","橫天聳翠壁，噴壑鳴紅泉。","尋幽殊未歇，愛此春光發。","溪傍饒名花，石上有好月。","命駕歸去來，露華生翠苔。","淹留惜將晚，復聽清猨哀。","清猨斷人腸，遊子思故鄉。","明發首東路，此懽焉可忘。"]', '["裴公有僊標，拔俗數千丈。","澹蕩滄洲云，飄颻紫霞想。","剖竹商洛间，政成心已闲。","蕭條出世表，冥寂閉玄关。","我来屬芳節，解榻时相悅。","褰帷对云峯，揚袂指松雪。","蹔出东城邊，遂游西巖前。","橫天聳翠壁，噴壑鳴紅泉。","尋幽殊未歇，愛此春光發。","溪傍饒名花，石上有好月。","命駕归去来，露华生翠苔。","淹留惜將晚，复听清猨哀。","清猨斷人腸，游子思故乡。","明發首东路，此懽焉可忘。"]', '诗', 'shi', '', NULL, '春陪商州裴使君遊石娥溪 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9217d5-9d09-4921-bf96-6eeeea0763ea', '陪從祖濟南太守泛鵲山湖三首 一', '陪從祖濟南太守泛鵲山湖三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["初謂鵲山近，寧知湖水遙。","此行殊訪戴，自可緩歸橈。"]', '["初謂鵲山近，寧知湖水遙。","此行殊訪戴，自可緩归橈。"]', '诗', 'shi', '', NULL, '陪從祖濟南太守泛鵲山湖三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af18d853-1ee7-4a38-a824-25c8946dd5b1', '陪從祖濟南太守泛鵲山湖三首 二', '陪從祖濟南太守泛鵲山湖三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["湖闊數千里，湖光搖碧山。","湖西正有月，獨送李膺還。"]', '["湖闊數千里，湖光搖碧山。","湖西正有月，独送李膺還。"]', '诗', 'shi', '', NULL, '陪從祖濟南太守泛鵲山湖三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db175472-50f3-4755-9825-0713a41bae5c', '陪從祖濟南太守泛鵲山湖三首 三', '陪從祖濟南太守泛鵲山湖三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水入北湖去，舟從南浦回。","遙看鵲山轉，却似送人來。"]', '["水入北湖去，舟從南浦回。","遙看鵲山轉，却似送人来。"]', '诗', 'shi', '', NULL, '陪從祖濟南太守泛鵲山湖三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e60472f1-6945-4a2b-a06f-953ef7fc16ba', '春日陪楊江寧及諸官宴北湖感古作', '春日陪楊江寧及諸官宴北湖感古作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔聞顏光祿，攀龍宴京湖。","樓船入天鏡，帳殿開雲衢。","君王歌大風，如樂豐沛都。","延年獻佳作，邈與詩人俱。","我來不及此，獨立鍾山孤。","楊宰穆清風，芳聲騰海隅。","英僚滿四座，粲若瓊林敷。","鷁首弄倒景，蛾眉綴明珠。","新弦採梨園，古舞嬌吳歈。","曲度繞雲漢，聽者皆歡娛。","雞棲何嘈嘈，沿月沸笙竽。","古之帝宮苑，今乃人樵蘇。","感此勸一觴，願君覆瓢壺。","榮盛當作樂，無令後賢吁。"]', '["昔闻顏光祿，攀龙宴京湖。","楼船入天镜，帳殿开云衢。","君王歌大风，如乐豐沛都。","延年獻佳作，邈與诗人俱。","我来不及此，独立鍾山孤。","楊宰穆清风，芳声腾海隅。","英僚满四座，粲若瓊林敷。","鷁首弄倒景，蛾眉綴明珠。","新弦採梨园，古舞嬌吳歈。","曲度繞云漢，听者皆歡娛。","雞棲何嘈嘈，沿月沸笙竽。","古之帝宮苑，今乃人樵蘇。","感此勸一觴，願君覆瓢壺。","榮盛當作乐，無令後賢吁。"]', '诗', 'shi', '', NULL, '春日陪楊江寧及諸官宴北湖感古作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c91d56b3-e004-4a4f-83ef-475273a3d91b', '宴鄭參卿山池', '宴鄭參卿山池', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["爾恐碧草晚，我畏朱顏移。","愁看楊花飛，置酒正相宜。","歌聲送落日，舞影迴清池。","今夕不盡杯，留歡更邀誰。"]', '["爾恐碧草晚，我畏朱顏移。","愁看楊花飞，置酒正相宜。","歌声送落日，舞影迴清池。","今夕不尽杯，留歡更邀誰。"]', '诗', 'shi', '', NULL, '宴鄭參卿山池 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71ed838-db42-4a19-b6a2-9ee8b77332aa', '遊謝氏山亭', '游謝氏山亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淪老臥江海，再歡天地清。","病閑久寂寞，歲物徒芬榮。","借君西池遊，聊以散我情。","掃雪松下去，捫蘿石道行。","謝公池塘上，春草颯已生。","花枝拂人來，山鳥向我鳴。","田家有美酒，落日與之傾。","醉罷弄歸月，遙欣稚子迎。"]', '["淪老臥江海，再歡天地清。","病闲久寂寞，歲物徒芬榮。","借君西池游，聊以散我情。","掃雪松下去，捫蘿石道行。","謝公池塘上，春草颯已生。","花枝拂人来，山鸟向我鳴。","田家有美酒，落日與之傾。","醉罷弄归月，遙欣稚子迎。"]', '诗', 'shi', '', NULL, '遊謝氏山亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd0e68fe-0e16-4b10-9345-ac567ce9cb62', '把酒問月', '把酒问月', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青天有月來幾時，我今停杯一問之。","人攀明月不可得，月行却與人相隨。","皎如飛鏡臨丹闕，綠烟滅盡清輝發。","但見宵從海上來，寧知曉向雲間沒。","白兔擣藥秋復春，嫦娥孤棲與誰鄰。","今人不見古時月，今月曾經照古人。","古人今人若流水，共看明月皆如此。","唯願當歌對酒時，月光長照金樽裏。"]', '["青天有月来幾时，我今停杯一问之。","人攀明月不可得，月行却與人相隨。","皎如飞镜臨丹闕，綠烟滅尽清輝發。","但见宵從海上来，寧知晓向云间沒。","白兔擣藥秋复春，嫦娥孤棲與誰鄰。","今人不见古时月，今月曾經照古人。","古人今人若流水，共看明月皆如此。","唯願當歌对酒时，月光长照金樽裏。"]', '诗', 'shi', '', NULL, '把酒問月 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f55f53d-0062-4afa-9dd9-69c4d7985ac8', '同族姪評事黯遊昌禪師山池二首 一', '同族姪評事黯游昌禪師山池二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遠公愛康樂，爲我開禪關。","蕭然松石下，何異清涼山。","花將色不染，水與心俱閑。","一坐度小劫，觀空天地間。"]', '["远公愛康乐，爲我开禪关。","蕭然松石下，何異清涼山。","花將色不染，水與心俱闲。","一坐度小劫，观空天地间。"]', '诗', 'shi', '', NULL, '同族姪評事黯遊昌禪師山池二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('591f1059-8d57-4004-b34a-62b6be925723', '同族姪評事黯遊昌禪師山池二首 二', '同族姪評事黯游昌禪師山池二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["客來花雨際，秋水落金池。","片石寒青錦，疎楊挂綠絲。","高僧拂玉柄，童子獻霜梨。","惜去愛佳景，煙蘿欲暝時。"]', '["客来花雨際，秋水落金池。","片石寒青錦，疎楊挂綠絲。","高僧拂玉柄，童子獻霜梨。","惜去愛佳景，煙蘿欲暝时。"]', '诗', 'shi', '', NULL, '同族姪評事黯遊昌禪師山池二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af667e00-f3a4-4a68-8f89-3e69d6eaa7a9', '金陵鳳凰臺置酒', '金陵鳳凰台置酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["置酒延落景，金陵鳳凰臺。","長波寫萬古，心與雲俱開。","借問往昔時，鳳凰爲誰來。","鳳凰去已久，正當今日迴。","明君越羲軒，天老坐三台。","豪士無所用，彈弦醉金罍。","東風吹山花，安可不盡杯。","六帝沒幽草，深宮冥綠苔。","置酒勿復道，歌鐘但相催。"]', '["置酒延落景，金陵鳳凰台。","长波寫万古，心與云俱开。","借问往昔时，鳳凰爲誰来。","鳳凰去已久，正當今日迴。","明君越羲軒，天老坐三台。","豪士無所用，彈弦醉金罍。","东风吹山花，安可不尽杯。","六帝沒幽草，深宮冥綠苔。","置酒勿复道，歌鐘但相催。"]', '诗', 'shi', '', NULL, '金陵鳳凰臺置酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2cde2ee-ef80-4089-b343-a5502ca94020', '秋浦清溪雪夜對酒客有唱山鷓鴣者', '秋浦清溪雪夜对酒客有唱山鷓鴣者', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["披君貂襜褕，對君白玉壺。","雪花酒上滅，頓覺夜寒無。","客有桂陽至，能吟山鷓鴣。","清風動窗竹，越鳥起相呼。","持此足爲樂，何煩笙與竽。"]', '["披君貂襜褕，对君白玉壺。","雪花酒上滅，頓覺夜寒無。","客有桂陽至，能吟山鷓鴣。","清风动窗竹，越鸟起相呼。","持此足爲乐，何煩笙與竽。"]', '诗', 'shi', '', NULL, '秋浦清溪雪夜對酒客有唱山鷓鴣者 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d22aad4e-2887-40b0-bdfe-71b2a5add45a', '與周剛清溪玉鏡潭宴別', '與周剛清溪玉镜潭宴別', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["康樂上官去，永嘉遊石門。","江亭有孤嶼，千載跡猶存。","我來游秋浦，三入桃陂源。","千峯照積雪，萬壑盡啼猨。","興與謝公合，文因周子論。","掃厓去落葉，席月開清樽。","溪當大樓南，溪水正南奔。","迴作玉鏡潭，澄明洗心魂。","此中得佳境，可以絕囂喧。","清夜方歸來，酣歌出平原。","別後經此地，爲余謝蘭蓀。"]', '["康乐上官去，永嘉游石门。","江亭有孤嶼，千載跡猶存。","我来游秋浦，三入桃陂源。","千峯照積雪，万壑尽啼猨。","兴與謝公合，文因周子論。","掃厓去落葉，席月开清樽。","溪當大楼南，溪水正南奔。","迴作玉镜潭，澄明洗心魂。","此中得佳境，可以絕囂喧。","清夜方归来，酣歌出平原。","別後經此地，爲余謝蘭蓀。"]', '诗', 'shi', '', NULL, '與周剛清溪玉鏡潭宴別 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3de2bf2-1566-4332-9115-81fffaaf6a3c', '遊秋浦白笴陂二首 一', '游秋浦白笴陂二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["何處夜行好，月明白笴陂。","山光搖積雪，猨影挂寒枝。","但恐佳景晚，小令歸櫂移。","人來有清興，及此有相思。"]', '["何处夜行好，月明白笴陂。","山光搖積雪，猨影挂寒枝。","但恐佳景晚，小令归櫂移。","人来有清兴，及此有相思。"]', '诗', 'shi', '', NULL, '遊秋浦白笴陂二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d305addc-bb71-4e60-ad20-40c499a4a75a', '遊秋浦白笴陂二首 二', '游秋浦白笴陂二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白笴夜長嘯，爽然溪谷寒。","魚龍動陂水，處處生波瀾。","天借一明月，飛來碧雲端。","故鄉不可見，腸斷正西看。"]', '["白笴夜长嘯，爽然溪谷寒。","鱼龙动陂水，处处生波瀾。","天借一明月，飞来碧云端。","故乡不可见，腸斷正西看。"]', '诗', 'shi', '', NULL, '遊秋浦白笴陂二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace9fe7f-c5cb-4b0a-9eac-90408377e833', '宴陶家亭子', '宴陶家亭子', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["曲巷幽人宅，高門大士家。","池開照膽鏡，林吐破顏花。","綠水藏春日，青軒祕晚霞。","若聞弦管妙，金谷不能誇。"]', '["曲巷幽人宅，高门大士家。","池开照膽镜，林吐破顏花。","綠水藏春日，青軒祕晚霞。","若闻弦管妙，金谷不能誇。"]', '诗', 'shi', '', NULL, '宴陶家亭子 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a78ae783-79eb-43ab-b491-fe782bd46525', '在水軍宴韋司馬樓船觀妓', '在水軍宴韋司马楼船观妓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["搖曳帆在空，清流順歸風。","詩因鼓吹發，酒爲劒歌雄。","對舞青樓妓，雙鬟白玉童。","行雲且莫去，留醉楚王宮。"]', '["搖曳帆在空，清流順归风。","诗因鼓吹發，酒爲劒歌雄。","对舞青楼妓，雙鬟白玉童。","行云且莫去，留醉楚王宮。"]', '诗', 'shi', '', NULL, '在水軍宴韋司馬樓船觀妓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0b411fd-df07-468b-9484-dea696ec7b60', '流夜郎至江夏陪長史叔及薛明府宴興德寺南閣', '流夜郎至江夏陪长史叔及薛明府宴兴德寺南閣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紺殿橫江上，青山落鏡中。","岸迴沙不盡，日暎水成空。","天樂流香閣，蓮舟颺晚風。","恭陪竹林宴，留醉與陶公。"]', '["紺殿橫江上，青山落镜中。","岸迴沙不尽，日暎水成空。","天乐流香閣，蓮舟颺晚风。","恭陪竹林宴，留醉與陶公。"]', '诗', 'shi', '', NULL, '流夜郎至江夏陪長史叔及薛明府宴興德寺南閣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c3dc0c-0894-4131-bbc9-09d2052c8423', '泛沔州城南郎官湖', '泛沔州城南郎官湖', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["張公多逸興，共泛沔城隅。","當時秋月好，不減武昌都。","四座醉清光，爲歡古來無。","郎官愛此水，因號郎官湖。","風流若未減，名與此山俱。"]', '["張公多逸兴，共泛沔城隅。","當时秋月好，不減武昌都。","四座醉清光，爲歡古来無。","郎官愛此水，因號郎官湖。","风流若未減，名與此山俱。"]', '诗', 'shi', '', NULL, '泛沔州城南郎官湖 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d481a1a-57ef-4546-b9d9-2e7c3e5b296c', '陪侍郎叔遊洞庭醉後三首 一', '陪侍郎叔游洞庭醉後三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["今日竹林宴，我家賢侍郎。","三杯容小阮，醉後發清狂。"]', '["今日竹林宴，我家賢侍郎。","三杯容小阮，醉後發清狂。"]', '诗', 'shi', '', NULL, '陪侍郎叔遊洞庭醉後三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8efedf3e-fbae-491b-b123-0a5a39bc37f0', '陪侍郎叔遊洞庭醉後三首 二', '陪侍郎叔游洞庭醉後三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["船上齊橈樂，湖心泛月歸。","白鷗閑不去，爭拂酒筵飛。"]', '["船上齊橈乐，湖心泛月归。","白鷗闲不去，爭拂酒筵飞。"]', '诗', 'shi', '', NULL, '陪侍郎叔遊洞庭醉後三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed76d8ed-267a-49c3-82e8-4ee0919bd9f6', '陪侍郎叔遊洞庭醉後三首 三', '陪侍郎叔游洞庭醉後三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["剗却君山好，平鋪湘水流。","巴陵無限酒，醉殺洞庭秋。"]', '["剗却君山好，平鋪湘水流。","巴陵無限酒，醉殺洞庭秋。"]', '诗', 'shi', '', NULL, '陪侍郎叔遊洞庭醉後三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc361275-25d0-4efc-840f-e3ebf563a6fc', '夜泛洞庭尋裴侍御清酌', '夜泛洞庭尋裴侍御清酌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日晚湘水綠，孤舟無端倪。","明湖漲秋月，獨泛巴陵西。","過憩裴逸人，巖居陵丹梯。","抱琴出深竹，爲我彈鵾雞。","曲盡酒亦傾，北窗醉如泥。","人生且行樂，何必組與珪。"]', '["日晚湘水綠，孤舟無端倪。","明湖漲秋月，独泛巴陵西。","過憩裴逸人，巖居陵丹梯。","抱琴出深竹，爲我彈鵾雞。","曲尽酒亦傾，北窗醉如泥。","人生且行乐，何必組與珪。"]', '诗', 'shi', '', NULL, '夜泛洞庭尋裴侍御清酌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a759f1f9-138e-40dc-b75c-0e9923ab71fe', '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 一', '陪族叔刑部侍郎曄及中书賈舍人至游洞庭五首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["洞庭西望楚江分，水盡南天不見雲。","日落長沙秋色遠，不知何處弔湘君。"]', '["洞庭西望楚江分，水尽南天不见云。","日落长沙秋色远，不知何处弔湘君。"]', '诗', 'shi', '', NULL, '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f6ab4f-11e2-43c1-8db3-3c7faebc17f8', '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 二', '陪族叔刑部侍郎曄及中书賈舍人至游洞庭五首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["南湖秋水夜無烟，耐可乘流直上天。","且就洞庭賒月色，將船買酒白雲邊。"]', '["南湖秋水夜無烟，耐可乘流直上天。","且就洞庭賒月色，將船買酒白云邊。"]', '诗', 'shi', '', NULL, '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53718a9e-e29a-42fb-8edb-630fed52a722', '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 三', '陪族叔刑部侍郎曄及中书賈舍人至游洞庭五首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["洛陽才子謫湘川，元禮同舟月下仙。","記得長安還欲笑，不知何處是西天。"]', '["洛陽才子謫湘川，元禮同舟月下仙。","記得长安還欲笑，不知何处是西天。"]', '诗', 'shi', '', NULL, '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6fb5943-be0a-4559-853c-222c60be55a6', '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 四', '陪族叔刑部侍郎曄及中书賈舍人至游洞庭五首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["洞庭湖西秋月輝，瀟湘江北早鴻飛。","醉客滿船歌白苧，不知霜露入秋衣。"]', '["洞庭湖西秋月輝，瀟湘江北早鴻飞。","醉客满船歌白苧，不知霜露入秋衣。"]', '诗', 'shi', '', NULL, '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc97ffb-bbe7-47e0-bbf4-47d3479095d1', '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 五', '陪族叔刑部侍郎曄及中书賈舍人至游洞庭五首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["帝子瀟湘去不還，空餘秋草洞庭間。","淡掃明湖開玉鏡，丹青畫出是君山。"]', '["帝子瀟湘去不還，空餘秋草洞庭间。","淡掃明湖开玉镜，丹青畫出是君山。"]', '诗', 'shi', '', NULL, '陪族叔刑部侍郎曄及中書賈舍人至遊洞庭五首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a064d5-b601-41d7-af93-1a73497582f5', '楚江黃龍磯南宴楊執戟治樓', '楚江黄龙磯南宴楊執戟治楼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["五月入五洲，碧山對青樓。","故人楊執戟，春賞楚江流。","一見醉漂月，三杯歌櫂謳。","桂枝攀不盡，他日更相求。"]', '["五月入五洲，碧山对青楼。","故人楊執戟，春賞楚江流。","一见醉漂月，三杯歌櫂謳。","桂枝攀不尽，他日更相求。"]', '诗', 'shi', '', NULL, '楚江黃龍磯南宴楊執戟治樓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b599c3b8-bf4d-4718-b1f7-5b1c4a28d83b', '銅官山醉後絕句', '銅官山醉後絕句', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我愛銅官樂，千年未擬還。","要須迴舞袖，拂盡五松山。"]', '["我愛銅官乐，千年未擬還。","要須迴舞袖，拂尽五松山。"]', '诗', 'shi', '', NULL, '銅官山醉後絕句 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a93ec327-32ba-4570-970e-0e754e20a0f7', '與南陵常贊府遊五松山', '與南陵常贊府游五松山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["安石泛溟渤，獨嘯長風還。","逸韻動海上，高情出人間。","靈異可並跡，澹然與世閑。","我來五松下，置酒窮躋攀。","徵古絕遺老，因名五松山。","五松何清幽，勝境美沃州。","蕭颯鳴洞壑，終年風雨秋。","響入百泉去，聽如三峽流。","剪竹掃天花，且從傲吏遊。","龍堂若可憩，吾欲歸精修。"]', '["安石泛溟渤，独嘯长风還。","逸韻动海上，高情出人间。","靈異可並跡，澹然與世闲。","我来五松下，置酒窮躋攀。","徵古絕遺老，因名五松山。","五松何清幽，勝境美沃州。","蕭颯鳴洞壑，終年风雨秋。","响入百泉去，听如三峽流。","剪竹掃天花，且從傲吏游。","龙堂若可憩，吾欲归精修。"]', '诗', 'shi', '', NULL, '與南陵常贊府遊五松山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26ea17e1-8091-4a1d-90a5-5f73dd80c8bb', '宣城青溪', '宣城青溪', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青溪勝桐廬，水木有佳色。","山貌日高古，石容天傾側。","綵鳥昔未名，白猨初相識。","不見同懷人，對之空歎息。"]', '["青溪勝桐廬，水木有佳色。","山貌日高古，石容天傾側。","綵鸟昔未名，白猨初相識。","不见同懷人，对之空歎息。"]', '诗', 'shi', '', NULL, '宣城青溪 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3150a4bc-eee3-4d04-b4be-54731acf80f3', '與謝良輔遊涇川陵巖寺', '與謝良輔游涇川陵巖寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["乘君素舸泛涇西，宛似雲門對若溪。","且從康樂尋山水，何必東遊入會稽。"]', '["乘君素舸泛涇西，宛似云门对若溪。","且從康乐尋山水，何必东游入會稽。"]', '诗', 'shi', '', NULL, '與謝良輔遊涇川陵巖寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28f30cf-3eba-433f-8e0f-e42e7b05a786', '遊水西簡鄭明府', '游水西簡鄭明府', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天宮水西寺，雲錦照東郭。","清湍鳴迴溪，綠水遶飛閣。","涼風日瀟灑，幽客時憩泊。","五月思貂裘，謂言秋霜落。","石蘿引古蔓，岸筍開新籜。","吟翫空復情，相思爾佳作。","鄭公詩人秀，逸韻宏寥廓。","何當一來遊，愜我雪山諾。"]', '["天宮水西寺，云錦照东郭。","清湍鳴迴溪，綠水遶飞閣。","涼风日瀟灑，幽客时憩泊。","五月思貂裘，謂言秋霜落。","石蘿引古蔓，岸筍开新籜。","吟翫空复情，相思爾佳作。","鄭公诗人秀，逸韻宏寥廓。","何當一来游，愜我雪山諾。"]', '诗', 'shi', '', NULL, '遊水西簡鄭明府 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d006f5-9145-47ca-bdbd-ab91189d5b64', '九日登山', '九日登山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淵明歸去來，不與世相逐。","爲無杯中物，遂偶本州牧。","因招白衣人，笑酌黃花菊。","我來不得意，虛過重陽時。","題輿何俊發，遂結城南期。","築土按響山，俯臨宛水湄。","胡人呌玉笛，越女彈霜絲。","自作英王胄，斯樂不可窺。","赤鯉湧琴高，白龜道馮夷。","靈仙如彷彿，奠酹遙相知。","古來登高人，今復幾人在。","滄洲違宿諾，明日猶可待。","連山似驚波，合沓出溟海。","揚袂揮四座，酩酊安所知。","齊歌送清揚，起舞亂參差。","賓隨落葉散，帽逐秋風吹。","別後登此臺，願言長相思。"]', '["淵明归去来，不與世相逐。","爲無杯中物，遂偶本州牧。","因招白衣人，笑酌黄花菊。","我来不得意，虛過重陽时。","題輿何俊發，遂結城南期。","築土按响山，俯臨宛水湄。","胡人呌玉笛，越女彈霜絲。","自作英王胄，斯乐不可窺。","赤鯉湧琴高，白龟道馮夷。","靈仙如彷彿，奠酹遙相知。","古来登高人，今复幾人在。","滄洲違宿諾，明日猶可待。","連山似驚波，合沓出溟海。","揚袂揮四座，酩酊安所知。","齊歌送清揚，起舞亂參差。","賓隨落葉散，帽逐秋风吹。","別後登此台，願言长相思。"]', '诗', 'shi', '', NULL, '九日登山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40cb9862-a17a-4d2e-a955-6cec79c2f1d1', '九日', '九日', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["今日雲景好，水綠秋山明。","攜壺酌流霞，搴菊泛寒榮。","地遠松石古，風揚弦管清。","窺觴照歡顏，獨笑還自傾。","落帽醉山月，空歌懷友生。"]', '["今日云景好，水綠秋山明。","携壺酌流霞，搴菊泛寒榮。","地远松石古，风揚弦管清。","窺觴照歡顏，独笑還自傾。","落帽醉山月，空歌懷友生。"]', '诗', 'shi', '', NULL, '九日 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b550f8c-c635-4b27-808e-1ee7b14acf07', '九日龍山飲', '九日龙山饮', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["九日龍山飲，黃花笑逐臣。","醉看風落帽，舞愛月留人。"]', '["九日龙山饮，黄花笑逐臣。","醉看风落帽，舞愛月留人。"]', '诗', 'shi', '', NULL, '九日龍山飲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d49e6f8-1cb3-4c16-bc9f-250edead9286', '九月十日即事', '九月十日即事', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昨日登高罷，今朝更舉觴。","菊花何太苦，遭此兩重陽。"]', '["昨日登高罷，今朝更舉觴。","菊花何太苦，遭此兩重陽。"]', '诗', 'shi', '', NULL, '九月十日即事 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b87e14c-3133-4232-a797-4d916ca5ed8c', '陪族叔當塗宰遊化城寺升公清風亭', '陪族叔當塗宰游化城寺升公清风亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["化城若化出，金牓天宮開。","疑是海上雲，飛空結樓臺。","升公湖上秀，粲然有辯才。","濟人不利己，立俗無嫌猜。","了見水中月，青蓮出塵埃。","閑居清風亭，左右清風來。","當暑陰廣殿，太陽爲裴回。","茗酌待幽客，珍盤薦彫梅。","飛文何灑落，萬象爲之摧。","季父擁鳴琴，德聲布雲雷。","雖遊道林室，亦舉陶潛杯。","清樂動諸天，長松自吟哀。","留歡若可盡，劫石乃成灰。"]', '["化城若化出，金牓天宮开。","疑是海上云，飞空結楼台。","升公湖上秀，粲然有辯才。","濟人不利己，立俗無嫌猜。","了见水中月，青蓮出塵埃。","闲居清风亭，左右清风来。","當暑陰廣殿，太陽爲裴回。","茗酌待幽客，珍盤薦彫梅。","飞文何灑落，万象爲之摧。","季父擁鳴琴，德声布云雷。","雖游道林室，亦舉陶潛杯。","清乐动諸天，长松自吟哀。","留歡若可尽，劫石乃成灰。"]', '诗', 'shi', '', NULL, '陪族叔當塗宰遊化城寺升公清風亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b53c418-c778-429f-ac6b-556bd2a5e36d', '登錦城散花樓', '登錦城散花楼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日照錦城頭，朝光散花樓。","金窗夾繡戶，珠箔懸銀鉤。","飛梯綠雲中，極目散我憂。","暮雨向三峽，春江繞雙流。","今來一登望，如上九天遊。"]', '["日照錦城头，朝光散花楼。","金窗夾繡戶，珠箔懸銀鉤。","飞梯綠云中，極目散我憂。","暮雨向三峽，春江繞雙流。","今来一登望，如上九天游。"]', '诗', 'shi', '', NULL, '登錦城散花樓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baf00a44-ea8c-4f88-918a-3c0ed7f1cd5d', '登峨眉山', '登峨眉山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蜀國多仙山，峨眉邈難匹。","周流試登覽，絕怪安可息。","青冥倚天開，彩錯疑畫出。","泠然紫霞賞，果得錦囊術。","雲間吟瓊簫，石上弄寶瑟。","平生有微尚，歡笑自此畢。","烟容如在顏，塵累忽相失。","儻逢騎羊子，攜手凌白日。"]', '["蜀国多仙山，峨眉邈难匹。","周流試登覽，絕怪安可息。","青冥倚天开，彩錯疑畫出。","泠然紫霞賞，果得錦囊術。","云间吟瓊簫，石上弄寶瑟。","平生有微尚，歡笑自此畢。","烟容如在顏，塵累忽相失。","儻逢騎羊子，携手凌白日。"]', '诗', 'shi', '', NULL, '登峨眉山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27560ab0-d135-4dcf-a0a9-52c6f7366ed7', '大庭庫', '大庭庫', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝登大庭庫，雲物何蒼然。","莫辨陳鄭火，空霾鄒魯煙。","我來尋梓慎，觀化入寥天。","古木朔氣多，松風如五弦。","帝圖終冥沒，歎息滿山川。"]', '["朝登大庭庫，云物何蒼然。","莫辨陳鄭火，空霾鄒魯煙。","我来尋梓慎，观化入寥天。","古木朔氣多，松风如五弦。","帝圖終冥沒，歎息满山川。"]', '诗', 'shi', '', NULL, '大庭庫 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f9f0c8e-d8b1-4b3a-86eb-18679f73b0fe', '登單父陶少府半月臺', '登單父陶少府半月台', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["陶公有逸興，不與常人俱。","築臺像半月，迴向高城隅。","置酒望白雲，商飆起寒梧。","秋山入遠海，桑柘羅平蕪。","水色淥且明，令人思鏡湖。","終當過江去，愛此暫踟躕。"]', '["陶公有逸兴，不與常人俱。","築台像半月，迴向高城隅。","置酒望白云，商飆起寒梧。","秋山入远海，桑柘羅平蕪。","水色淥且明，令人思镜湖。","終當過江去，愛此暫踟躕。"]', '诗', 'shi', '', NULL, '登單父陶少府半月臺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('589ca8b3-49ab-4d01-8749-207e80f425d3', '天台曉望', '天台晓望', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天台鄰四明，華頂高百越。","門標赤城霞，樓棲滄島月。","憑高登遠覽，直下見溟渤。","雲垂大鵬翻，波動巨鼇沒。","風潮爭洶湧，神怪何翕忽。","觀奇跡無倪，好道心不歇。","攀條摘朱實，服藥鍊金骨。","安得生羽毛，千春臥蓬闕。"]', '["天台鄰四明，华頂高百越。","门標赤城霞，楼棲滄島月。","憑高登远覽，直下见溟渤。","云垂大鵬翻，波动巨鼇沒。","风潮爭洶湧，神怪何翕忽。","观奇跡無倪，好道心不歇。","攀條摘朱實，服藥鍊金骨。","安得生羽毛，千春臥蓬闕。"]', '诗', 'shi', '', NULL, '天台曉望 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f2d630-f325-4caa-b96e-a61731c3412d', '早望海霞邊', '早望海霞邊', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["四明三千里，朝起赤城霞。","日出紅光散，分輝照雪厓。","一餐嚥瓊液，五內發金沙。","舉手何所待，青龍白虎車。"]', '["四明三千里，朝起赤城霞。","日出紅光散，分輝照雪厓。","一餐嚥瓊液，五內發金沙。","舉手何所待，青龙白虎车。"]', '诗', 'shi', '', NULL, '早望海霞邊 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc819866-1931-4db1-bfed-759913252a04', '焦山望寥山', '焦山望寥山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["石壁望松寥，宛然在碧霄。","安得五綵虹，駕天作長橋。","仙人如愛我，舉手來相招。"]', '["石壁望松寥，宛然在碧霄。","安得五綵虹，駕天作长橋。","仙人如愛我，舉手来相招。"]', '诗', 'shi', '', NULL, '焦山望寥山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86612734-8646-4fdb-a8e7-cbebc13c0140', '杜陵絕句', '杜陵絕句', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["南登杜陵上，北望五陵間。","秋水明落日，流光滅遠山。"]', '["南登杜陵上，北望五陵间。","秋水明落日，流光滅远山。"]', '诗', 'shi', '', NULL, '杜陵絕句 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e804c8-f626-4b82-81bb-6d9ac96b43b7', '登太白峰', '登太白峰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西上太白峯，夕陽窮登攀。","太白與我語，爲我開天關。","願乘泠風去，直出浮雲間。","舉手可近月，前行若無山。","一別武功去，何時復見還。"]', '["西上太白峯，夕陽窮登攀。","太白與我語，爲我开天关。","願乘泠风去，直出浮云间。","舉手可近月，前行若無山。","一別武功去，何时复见還。"]', '诗', 'shi', '', NULL, '登太白峰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6a8c07e-5fb9-432c-af0b-ae0eebc0bb73', '登邯鄲洪波臺置酒觀發兵', '登邯鄲洪波台置酒观發兵', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我把兩赤羽，來遊燕趙間。","天狼正可射，感激無時閑。","觀兵洪波臺，倚劒望玉關。","請纓不繫越，且向燕然山。","風引龍虎旗，歌鐘昔追攀。","擊筑落高月，投壺破愁顏。","遙知百戰勝，定掃鬼方還。"]', '["我把兩赤羽，来游燕趙间。","天狼正可射，感激無时闲。","观兵洪波台，倚劒望玉关。","請纓不繫越，且向燕然山。","风引龙虎旗，歌鐘昔追攀。","擊筑落高月，投壺破愁顏。","遙知百戰勝，定掃鬼方還。"]', '诗', 'shi', '', NULL, '登邯鄲洪波臺置酒觀發兵 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432d8f62-b1ed-438e-92bf-91c5af04a6c3', '登新平樓', '登新平楼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["去國登茲樓，懷歸傷暮秋。","天長落日遠，水淨寒波流。","秦雲起嶺樹，胡雁飛沙洲。","蒼蒼幾萬里，目極令人愁。"]', '["去国登茲楼，懷归傷暮秋。","天长落日远，水淨寒波流。","秦云起嶺樹，胡雁飞沙洲。","蒼蒼幾万里，目極令人愁。"]', '诗', 'shi', '', NULL, '登新平樓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('657e2878-b1a1-4ff9-8084-d2a957ab031b', '謁老君廟', '謁老君廟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["先君懷聖德，靈廟肅神心。","草合人蹤斷，塵濃鳥跡深。","流沙丹竈滅，關路紫煙沈。","獨傷千載後，空餘松柏林。"]', '["先君懷聖德，靈廟肅神心。","草合人蹤斷，塵濃鸟跡深。","流沙丹竈滅，关路紫煙沈。","独傷千載後，空餘松柏林。"]', '诗', 'shi', '', NULL, '謁老君廟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffd1b916-0e65-4d35-a718-53725bc02964', '秋日登揚州西靈塔', '秋日登揚州西靈塔', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["寶塔凌蒼蒼，登攀覽四荒。","頂高元氣合，標出海雲長。","萬象分空界，三天接畫梁。","水搖金剎影，日動火珠光。","鳥拂瓊簾度，霞連繡栱張。","目隨征路斷，心逐去帆揚。","露浴梧楸白，霜催橘柚黃。","玉毫如可見，於此照迷方。"]', '["寶塔凌蒼蒼，登攀覽四荒。","頂高元氣合，標出海云长。","万象分空界，三天接畫梁。","水搖金剎影，日动火珠光。","鸟拂瓊簾度，霞連繡栱張。","目隨征路斷，心逐去帆揚。","露浴梧楸白，霜催橘柚黄。","玉毫如可见，於此照迷方。"]', '诗', 'shi', '', NULL, '秋日登揚州西靈塔 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4903cf79-3b14-4714-abc7-2b4d54bcb1fb', '登金陵冶城西北謝安墩', '登金陵冶城西北謝安墩', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["晉室昔橫潰，永嘉遂南奔。","沙塵何茫茫，龍虎鬬朝昏。","胡馬風漢草，天驕蹙中原。","哲匠感頹運，雲鵬忽飛翻。","組練照楚國，旌旗連海門。","西秦百萬衆，戈甲如雲屯。","投鞭可填江，一埽不足論。","皇運有返正，醜虜無遺魂。","談笑遏橫流，蒼生望斯存。","冶城訪古跡，猶有謝安墩。","憑覽周地險，高標絕人喧。","想像東山姿，緬懷右軍言。","梧桐識嘉樹，蕙草留芳根。","白鷺暎春洲，青龍見朝暾。","地古雲物在，臺傾禾黍繁。","我來酌清波，於此樹名園。","功成拂衣去，歸入武陵源。"]', '["晉室昔橫潰，永嘉遂南奔。","沙塵何茫茫，龙虎鬬朝昏。","胡马风漢草，天驕蹙中原。","哲匠感頹運，云鵬忽飞翻。","組練照楚国，旌旗連海门。","西秦百万衆，戈甲如云屯。","投鞭可填江，一埽不足論。","皇運有返正，醜虜無遺魂。","談笑遏橫流，蒼生望斯存。","冶城訪古跡，猶有謝安墩。","憑覽周地險，高標絕人喧。","想像东山姿，緬懷右軍言。","梧桐識嘉樹，蕙草留芳根。","白鷺暎春洲，青龙见朝暾。","地古云物在，台傾禾黍繁。","我来酌清波，於此樹名园。","功成拂衣去，归入武陵源。"]', '诗', 'shi', '', NULL, '登金陵冶城西北謝安墩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bec12bd-f48b-4c3c-83a6-4443892f69d2', '登瓦官閣', '登瓦官閣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["晨登瓦官閣，極眺金陵城。","鍾山對北戶，淮水入南榮。","漫漫雨花落，嘈嘈天樂鳴。","兩廊振法鼓，四角吟風箏。","杳出霄漢上，仰攀日月行。","山空霸氣滅，地古寒陰生。","寥廓雲海晚，蒼茫宮觀平。","門餘閶闔字，樓識鳳凰名。","雷作百山動，神扶萬栱傾。","靈光何足貴，長此鎮吳京。"]', '["晨登瓦官閣，極眺金陵城。","鍾山对北戶，淮水入南榮。","漫漫雨花落，嘈嘈天乐鳴。","兩廊振法鼓，四角吟风箏。","杳出霄漢上，仰攀日月行。","山空霸氣滅，地古寒陰生。","寥廓云海晚，蒼茫宮观平。","门餘閶闔字，楼識鳳凰名。","雷作百山动，神扶万栱傾。","靈光何足貴，长此鎮吳京。"]', '诗', 'shi', '', NULL, '登瓦官閣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78eb70d1-cf6d-475c-96b6-2c8c4bab4a90', '登梅岡望金陵贈族姪高座寺僧中孚', '登梅岡望金陵贈族姪高座寺僧中孚', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鍾山抱金陵，霸氣昔騰發。","天開帝王居，海色照宮闕。","羣峰如逐鹿，奔走相馳突。","江水九道來，雲端遙明沒。","時遷大運去，龍虎勢休歇。","我來屬天清，登覽窮楚越。","吾宗挺禪伯，特秀鸞鳳骨。","衆星羅青天，明者獨有月。","冥居順生理，草木不剪伐。","烟窗引薔薇，石壁老野蕨。","吳風謝安屐，白足傲履韈。","幾宿一下山，蕭然忘干謁。","談經演金偈，降鶴舞海雪。","時聞天香來，了與世事絕。","佳遊不可得，春風惜遠別。","賦詩留巖屏，千載庶不滅。"]', '["鍾山抱金陵，霸氣昔腾發。","天开帝王居，海色照宮闕。","羣峰如逐鹿，奔走相驰突。","江水九道来，云端遙明沒。","时遷大運去，龙虎勢休歇。","我来屬天清，登覽窮楚越。","吾宗挺禪伯，特秀鸾鳳骨。","衆星羅青天，明者独有月。","冥居順生理，草木不剪伐。","烟窗引薔薇，石壁老野蕨。","吳风謝安屐，白足傲履韈。","幾宿一下山，蕭然忘干謁。","談經演金偈，降鹤舞海雪。","时闻天香来，了與世事絕。","佳游不可得，春风惜远別。","賦诗留巖屏，千載庶不滅。"]', '诗', 'shi', '', NULL, '登梅岡望金陵贈族姪高座寺僧中孚 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af86c76-18b3-4069-be90-6d8cef430bc7', '登金陵鳳凰臺', '登金陵鳳凰台', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鳳凰臺上鳳凰遊，鳳去臺空江自流。","吳宮花草埋幽徑，晉代衣冠成古丘。","三山半落青天外，二水中分白鷺洲。","總爲浮雲能蔽日，長安不見使人愁。"]', '["鳳凰台上鳳凰游，鳳去台空江自流。","吳宮花草埋幽徑，晉代衣冠成古丘。","三山半落青天外，二水中分白鷺洲。","總爲浮云能蔽日，长安不见使人愁。"]', '诗', 'shi', '', NULL, '登金陵鳳凰臺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d15ef0b-73f9-488a-859c-e5b9fdf0a2ac', '望廬山瀑布水二首 一', '望廬山瀑布水二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西登香爐峰，南見瀑布水。","挂流三百丈，噴壑數十里。","歘如飛電來，隱若白虹起。","初驚河漢落，半灑雲天裏。","仰觀勢轉雄，壯哉造化功。","海風吹不斷，江月照還空。","空中亂潨射，左右洗青壁。","飛珠散輕霞，流沫沸穹石。","而我樂名山，對之心益閑。","無論潄瓊液，還得洗塵顏。","且諧宿所好，永願辭人間。"]', '["西登香爐峰，南见瀑布水。","挂流三百丈，噴壑數十里。","歘如飞電来，隐若白虹起。","初驚河漢落，半灑云天裏。","仰观勢轉雄，壯哉造化功。","海风吹不斷，江月照還空。","空中亂潨射，左右洗青壁。","飞珠散轻霞，流沫沸穹石。","而我乐名山，对之心益闲。","無論潄瓊液，還得洗塵顏。","且諧宿所好，永願辞人间。"]', '诗', 'shi', '', NULL, '望廬山瀑布水二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c155ff88-deac-4c17-8648-91f478d77ef9', '望廬山瀑布水二首 二', '望廬山瀑布水二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日照香爐生紫煙，遙看瀑布挂前川。","飛流直下三千尺，疑是銀河落九天。"]', '["日照香爐生紫煙，遙看瀑布挂前川。","飞流直下三千尺，疑是銀河落九天。"]', '诗', 'shi', '', NULL, '望廬山瀑布水二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa3c73e-023d-4295-8ca7-7fef63b29207', '登廬山五老峰', '登廬山五老峰', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["廬山東南五老峰，青天削出金芙蓉。","九江秀色可攬結，吾將此地巢雲松。"]', '["廬山东南五老峰，青天削出金芙蓉。","九江秀色可攬結，吾將此地巢云松。"]', '诗', 'shi', '', NULL, '登廬山五老峰 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c172e467-ee99-4896-86b9-f1491d127403', '江上望皖公山', '江上望皖公山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["奇峰出奇雲，秀木含秀氣。","清宴皖公山，巉絕稱人意。","獨遊滄江上，終日淡無味。","但愛茲嶺高，何由討靈異。","默然遙相許，欲徃心莫遂。","待吾還丹成，投跡歸此地。"]', '["奇峰出奇云，秀木含秀氣。","清宴皖公山，巉絕稱人意。","独游滄江上，終日淡無味。","但愛茲嶺高，何由討靈異。","默然遙相許，欲徃心莫遂。","待吾還丹成，投跡归此地。"]', '诗', 'shi', '', NULL, '江上望皖公山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7060e8f-cb6c-43de-bcf8-e6753e3e42f1', '望黃鶴樓', '望黄鹤楼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["東望黃鶴山，雄雄半空出。","四面生白雲，中峰倚紅日。","巖巒行穹跨，峰嶂亦冥密。","頗聞列仙人，於此學飛術。","一朝向蓬海，千載空石室。","金竈生烟埃，玉潭祕清謐。","地古遺草木，庭寒老芝朮。","蹇予羨攀躋，因欲保閑逸。","觀奇徧諸嶽，茲嶺不可匹。","結心寄青松，永悟客情畢。"]', '["东望黄鹤山，雄雄半空出。","四面生白云，中峰倚紅日。","巖巒行穹跨，峰嶂亦冥密。","頗闻列仙人，於此学飞術。","一朝向蓬海，千載空石室。","金竈生烟埃，玉潭祕清謐。","地古遺草木，庭寒老芝朮。","蹇予羨攀躋，因欲保闲逸。","观奇徧諸嶽，茲嶺不可匹。","結心寄青松，永悟客情畢。"]', '诗', 'shi', '', NULL, '望黃鶴樓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e92b69c-cc6d-44ed-b873-573300ac14ac', '鸚鵡洲', '鸚鵡洲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鸚鵡來過吳江水，江上洲傳鸚鵡名。","鸚鵡西飛隴山去，芳洲之樹何青青。","烟開蘭葉香風暖，岸夾桃花錦浪生。","遷客此時徒極目，長洲孤月向誰明。"]', '["鸚鵡来過吳江水，江上洲傳鸚鵡名。","鸚鵡西飞隴山去，芳洲之樹何青青。","烟开蘭葉香风暖，岸夾桃花錦浪生。","遷客此时徒極目，长洲孤月向誰明。"]', '诗', 'shi', '', NULL, '鸚鵡洲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ad3a0b-6682-4338-be5b-8825f2b9c54f', '九日登巴陵置酒望洞庭水軍', '九日登巴陵置酒望洞庭水軍', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["九日天氣清，登高無秋雲。","造化闢川嶽，了然楚漢分。","長風鼓橫波，合沓蹙龍文。","憶昔傳遊豫，樓船壯橫汾。","今茲討鯨鯢，旌斾何繽紛。","白羽落酒樽，洞庭羅三軍。","黃花不掇手，戰鼓遙相聞。","劒舞轉頹陽，當時日停曛。","酣歌激壯士，可以摧妖氛。","齷齪東籬下，淵明不足羣。"]', '["九日天氣清，登高無秋云。","造化闢川嶽，了然楚漢分。","长风鼓橫波，合沓蹙龙文。","憶昔傳游豫，楼船壯橫汾。","今茲討鯨鯢，旌斾何繽紛。","白羽落酒樽，洞庭羅三軍。","黄花不掇手，戰鼓遙相闻。","劒舞轉頹陽，當时日停曛。","酣歌激壯士，可以摧妖氛。","齷齪东籬下，淵明不足羣。"]', '诗', 'shi', '', NULL, '九日登巴陵置酒望洞庭水軍 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1098b99e-9464-4339-8640-301ac4664e04', '秋登巴陵望洞庭', '秋登巴陵望洞庭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清晨登巴陵，周覽無不極。","明湖暎天光，徹底見秋色。","秋色何蒼然，際海俱澄鮮。","山青滅遠樹，水綠無寒烟。","來帆出江中，去鳥向日邊。","風清長沙浦，山空雲夢田。","瞻光惜頹髮，閱水悲徂年。","北渚既蕩漾，東流自潺湲。","郢人唱白雪，越女歌採蓮。","聽此更腸斷，憑厓淚如泉。"]', '["清晨登巴陵，周覽無不極。","明湖暎天光，徹底见秋色。","秋色何蒼然，際海俱澄鲜。","山青滅远樹，水綠無寒烟。","来帆出江中，去鸟向日邊。","风清长沙浦，山空云梦田。","瞻光惜頹髮，閱水悲徂年。","北渚既蕩漾，东流自潺湲。","郢人唱白雪，越女歌採蓮。","听此更腸斷，憑厓泪如泉。"]', '诗', 'shi', '', NULL, '秋登巴陵望洞庭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fdb5cd2-7b86-4c2d-9da0-cac80d36b3bc', '與夏十二登岳陽樓', '與夏十二登岳陽楼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["樓觀岳陽盡，川逈洞庭開。","雁引愁心去，山銜好月來。","雲間連下榻，天上接行杯。","醉後涼風起，吹人舞袖迴。"]', '["楼观岳陽尽，川逈洞庭开。","雁引愁心去，山銜好月来。","云间連下榻，天上接行杯。","醉後涼风起，吹人舞袖迴。"]', '诗', 'shi', '', NULL, '與夏十二登岳陽樓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('575a389f-2b6c-4946-b711-4f457ce3f6de', '登巴陵開元寺西閣贈衡嶽僧方外', '登巴陵开元寺西閣贈衡嶽僧方外', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["衡嶽有闡士，五峯秀真骨。","見君萬里心，海水照秋月。","大臣南溟去，問道皆請謁。","灑以甘露言，清涼潤肌髮。","明湖落天鏡，香閣凌銀闕。","登眺餐惠風，新花期啓發。"]', '["衡嶽有闡士，五峯秀真骨。","见君万里心，海水照秋月。","大臣南溟去，问道皆請謁。","灑以甘露言，清涼潤肌髮。","明湖落天镜，香閣凌銀闕。","登眺餐惠风，新花期啓發。"]', '诗', 'shi', '', NULL, '登巴陵開元寺西閣贈衡嶽僧方外 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('193e48e6-35b7-42c7-95e0-f57073c1476d', '與賈至舍人於龍興寺剪落梧桐枝望㴩湖', '與賈至舍人於龙兴寺剪落梧桐枝望㴩湖', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["剪落青梧枝，㴩湖坐可窺。","雨洗秋山淨，林光澹碧滋。","水閑明鏡轉，雲繞畫屏移。","千古風流事，名賢共此時。"]', '["剪落青梧枝，㴩湖坐可窺。","雨洗秋山淨，林光澹碧滋。","水闲明镜轉，云繞畫屏移。","千古风流事，名賢共此时。"]', '诗', 'shi', '', NULL, '與賈至舍人於龍興寺剪落梧桐枝望㴩湖 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd1f3ce3-4368-44be-a1b8-42e54ceeb421', '挂席江上待月有懷', '挂席江上待月有懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["待月月未出，望江江自流。","倏忽城西郭，青天懸玉鉤。","素華雖可攬，清景不可遊。","耿耿金波裏，空瞻鳷鵲樓。"]', '["待月月未出，望江江自流。","倏忽城西郭，青天懸玉鉤。","素华雖可攬，清景不可游。","耿耿金波裏，空瞻鳷鵲楼。"]', '诗', 'shi', '', NULL, '挂席江上待月有懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cac5b4f-8afd-440d-8346-663eb8d8d3e6', '金陵望漢江', '金陵望漢江', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢江迴萬里，派作九龍盤。","橫潰豁中國，崔嵬飛迅湍。","六帝淪亡後，三吳不足觀。","我君混區宇，垂拱衆流安。","今日任公子，滄浪罷釣竿。"]', '["漢江迴万里，派作九龙盤。","橫潰豁中国，崔嵬飞迅湍。","六帝淪亡後，三吳不足观。","我君混區宇，垂拱衆流安。","今日任公子，滄浪罷釣竿。"]', '诗', 'shi', '', NULL, '金陵望漢江 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eb19484-ee82-4fe0-8412-3b61951ef1e9', '秋登宣城謝朓北樓', '秋登宣城謝朓北楼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["江城如畫裏，山曉望晴空。","兩水夾明鏡，雙橋落彩虹。","人煙寒橘柚，秋色老梧桐。","誰念北樓上，臨風懷謝公。"]', '["江城如畫裏，山晓望晴空。","兩水夾明镜，雙橋落彩虹。","人煙寒橘柚，秋色老梧桐。","誰念北楼上，臨风懷謝公。"]', '诗', 'shi', '', NULL, '秋登宣城謝朓北樓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc7dff19-adc9-4f03-8862-057d1e7722b3', '望天門山', '望天门山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天門中斷楚江開，碧水東流至北迴。","兩岸青山相對出，孤帆一片日邊來。"]', '["天门中斷楚江开，碧水东流至北迴。","兩岸青山相对出，孤帆一片日邊来。"]', '诗', 'shi', '', NULL, '望天門山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('857b0aba-32b8-4d71-be68-f6b3eac5974a', '望木瓜山', '望木瓜山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["早起見日出，暮見棲鳥還。","客心自酸楚，況對木瓜山。"]', '["早起见日出，暮见棲鸟還。","客心自酸楚，況对木瓜山。"]', '诗', 'shi', '', NULL, '望木瓜山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b0b77ea-48cc-48cf-abf8-ed34e73325d8', '登敬亭北二小山余時送客逢崔侍御並登此地', '登敬亭北二小山余时送客逢崔侍御並登此地', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["送客謝亭北，逢君縱酒還。","屈盤戲白馬，大笑上青山。","迴鞭指長安，西日落秦關。","帝鄉三千里，杳在碧雲間。"]', '["送客謝亭北，逢君縱酒還。","屈盤戲白马，大笑上青山。","迴鞭指长安，西日落秦关。","帝乡三千里，杳在碧云间。"]', '诗', 'shi', '', NULL, '登敬亭北二小山余時送客逢崔侍御並登此地 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29d892d-8d75-4e8c-846c-bd751dcd8b3a', '過崔八丈水亭', '過崔八丈水亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["高閣橫秀氣，清幽併在君。","簷飛宛溪水，窗落敬亭雲。","猨嘯風中斷，漁歌月裏聞。","閑隨白鷗去，沙上自爲羣。"]', '["高閣橫秀氣，清幽併在君。","簷飞宛溪水，窗落敬亭云。","猨嘯风中斷，漁歌月裏闻。","闲隨白鷗去，沙上自爲羣。"]', '诗', 'shi', '', NULL, '過崔八丈水亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1a2777-6bfa-419e-806c-970e60fece30', '登廣武古戰場懷古', '登廣武古戰場懷古', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦鹿奔野草，逐之若飛蓬。","項王氣蓋世，紫電明雙瞳。","呼吸八千人，橫行起江東。","赤精斬白帝，叱咤入關中。","兩龍不並躍，五緯與天同。","楚滅無英圖，漢興有成功。","按劒清八極，歸酣歌大風。","伊昔臨廣武，連兵決雌雄。","分我一杯羹，太皇乃汝翁。","戰爭有古跡，壁壘頹層穹。","猛虎嘯洞壑，飢鷹鳴秋空。","翔雲列曉陣，殺氣赫長虹。","撥亂屬豪聖，俗儒安可通。","沈湎呼豎子，狂言非至公。","撫掌黃河曲，嗤嗤阮嗣宗。"]', '["秦鹿奔野草，逐之若飞蓬。","項王氣蓋世，紫電明雙瞳。","呼吸八千人，橫行起江东。","赤精斬白帝，叱咤入关中。","兩龙不並躍，五緯與天同。","楚滅無英圖，漢兴有成功。","按劒清八極，归酣歌大风。","伊昔臨廣武，連兵決雌雄。","分我一杯羹，太皇乃汝翁。","戰爭有古跡，壁壘頹層穹。","猛虎嘯洞壑，飢鷹鳴秋空。","翔云列晓陣，殺氣赫长虹。","撥亂屬豪聖，俗儒安可通。","沈湎呼豎子，狂言非至公。","撫掌黄河曲，嗤嗤阮嗣宗。"]', '诗', 'shi', '', NULL, '登廣武古戰場懷古 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e914e3a4-36f3-4d04-8c60-036c7b034f1c', '安州應城玉女湯作', '安州應城玉女湯作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["神女歿幽境，湯池流大川。","陰陽結炎炭，造化開靈泉。","地底爍朱火，沙傍歊素煙。","沸珠躍明月，皎鏡函空天。","氣浮蘭芳滿，色漲桃花然。","精覽萬殊入，潛行七澤連。","愈疾功莫尚，變盈道乃全。","濯濯氣清泚，晞髮弄潺湲。","散下楚王國，分澆宋玉田。","可以奉巡幸，奈何隔窮偏。","獨隨朝宗水，赴海輸微涓。"]', '["神女歿幽境，湯池流大川。","陰陽結炎炭，造化开靈泉。","地底爍朱火，沙傍歊素煙。","沸珠躍明月，皎镜函空天。","氣浮蘭芳满，色漲桃花然。","精覽万殊入，潛行七澤連。","愈疾功莫尚，变盈道乃全。","濯濯氣清泚，晞髮弄潺湲。","散下楚王国，分澆宋玉田。","可以奉巡幸，奈何隔窮偏。","独隨朝宗水，赴海輸微涓。"]', '诗', 'shi', '', NULL, '安州應城玉女湯作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eca97f2-6916-444d-9b67-53ea52355fbf', '之廣陵宿常二南郭幽居', '之廣陵宿常二南郭幽居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["綠水接柴門，有如桃花源。","忘憂或假草，滿院羅叢萱。","[暝]色湖上來，微雨飛南軒。","故人宿茅宇，夕鳥棲楊園。","還惜詩酒別，深爲江海言。","明朝廣陵道，獨憶此傾樽。"]', '["綠水接柴门，有如桃花源。","忘憂或假草，满院羅叢萱。","[暝]色湖上来，微雨飞南軒。","故人宿茅宇，夕鸟棲楊园。","還惜诗酒別，深爲江海言。","明朝廣陵道，独憶此傾樽。"]', '诗', 'shi', '', NULL, '之廣陵宿常二南郭幽居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f066769-61bb-469b-8224-e90424e5cddf', '夜下征虜亭', '夜下征虜亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["船下廣陵去，月明征虜亭。","山花如繡頰，江火似流螢。"]', '["船下廣陵去，月明征虜亭。","山花如繡頰，江火似流螢。"]', '诗', 'shi', '', NULL, '夜下征虜亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5def7d-2b21-4034-a4f2-f63ce6a1c793', '下途歸石門舊居', '下途归石门旧居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吳山高，越水清，握手無言傷別情。","將欲辭君挂帆去，離魂不散煙郊樹。","此心鬱悵誰能論，有愧叨承國士恩。","雲物共傾三月酒，歲時同餞五侯門。","羨君素書嘗滿案，含丹照白霞色爛。","余嘗學道窮冥筌，夢中往往遊仙山。","何當脫屣謝時去，壺中別有日月天。","俛仰人間易凋朽，鍾峰五雲在軒牖。","惜別愁窺玉女窗，歸來笑把洪厓手。","隱居寺，隱居山，陶公鍊液棲其間。","靈神閉氣昔登攀，恬然但覺心緒閑。","數人不知幾甲子，昨夜猶帶冰霜顏。","我離雖則歲物改，如今了然失所在。","別君莫道不盡歡，懸知樂客遙相待。","石門流水徧桃花，我亦曾到秦人家。","不知何處得雞豕，就中仍見繁桑麻。","翛然遠與世事間，裝鸞駕鶴又復遠。","何必長從七貴遊，勞生徒聚萬金產。","挹君去，長相思，雲遊雨散從此辭。","欲知悵別心易苦，向暮春風楊柳絲。"]', '["吳山高，越水清，握手無言傷別情。","將欲辞君挂帆去，離魂不散煙郊樹。","此心鬱悵誰能論，有愧叨承国士恩。","云物共傾三月酒，歲时同餞五侯门。","羨君素书嘗满案，含丹照白霞色爛。","余嘗学道窮冥筌，梦中往往游仙山。","何當脫屣謝时去，壺中別有日月天。","俛仰人间易凋朽，鍾峰五云在軒牖。","惜別愁窺玉女窗，归来笑把洪厓手。","隐居寺，隐居山，陶公鍊液棲其间。","靈神閉氣昔登攀，恬然但覺心緒闲。","數人不知幾甲子，昨夜猶带冰霜顏。","我離雖則歲物改，如今了然失所在。","別君莫道不尽歡，懸知乐客遙相待。","石门流水徧桃花，我亦曾到秦人家。","不知何处得雞豕，就中仍见繁桑麻。","翛然远與世事间，裝鸾駕鹤又复远。","何必长從七貴游，勞生徒聚万金產。","挹君去，长相思，云游雨散從此辞。","欲知悵別心易苦，向暮春风楊柳絲。"]', '诗', 'shi', '', NULL, '下途歸石門舊居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edea2ab7-a187-497a-8382-bba6b71ba476', '客中行', '客中行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蘭陵美酒鬱金香，玉椀盛來琥珀光。","但使主人能醉客，不知何處是他鄉。"]', '["蘭陵美酒鬱金香，玉椀盛来琥珀光。","但使主人能醉客，不知何处是他乡。"]', '诗', 'shi', '', NULL, '客中行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a632c7-6efc-44aa-a963-6c62e90589b6', '太原早秋', '太原早秋', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["歲落衆芳歇，時當大火流。","霜威出塞早，雲色渡河秋。","夢繞邊城月，心飛故國樓。","思歸若汾水，無日不悠悠。"]', '["歲落衆芳歇，时當大火流。","霜威出塞早，云色渡河秋。","梦繞邊城月，心飞故国楼。","思归若汾水，無日不悠悠。"]', '诗', 'shi', '', NULL, '太原早秋 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d2c478f-18d3-4477-9ae4-209fd7426eab', '奔亡道中五首 一', '奔亡道中五首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蘇武天山上，田橫海島邊。","萬重關塞斷，何日是歸年。"]', '["蘇武天山上，田橫海島邊。","万重关塞斷，何日是归年。"]', '诗', 'shi', '', NULL, '奔亡道中五首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed7382c4-83f6-494a-8a23-4c1c4380c1c5', '奔亡道中五首 二', '奔亡道中五首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["亭伯去安在，李陵降未歸。","愁容變海色，短服改胡衣。"]', '["亭伯去安在，李陵降未归。","愁容变海色，短服改胡衣。"]', '诗', 'shi', '', NULL, '奔亡道中五首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa166845-fac4-4a9c-8df5-731afd1ca151', '奔亡道中五首 三', '奔亡道中五首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["談笑三軍却，交游七貴疎。","仍留一隻箭，未射魯連書。"]', '["談笑三軍却，交游七貴疎。","仍留一隻箭，未射魯連书。"]', '诗', 'shi', '', NULL, '奔亡道中五首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d26f178-0226-4bfa-9929-0e47726046e2', '奔亡道中五首 四', '奔亡道中五首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["函谷如玉關，幾時可生還。","洛陽爲易水，嵩嶽是燕山。","俗變羗胡語，人多沙塞顏。","申包惟慟哭，七日鬢毛斑。"]', '["函谷如玉关，幾时可生還。","洛陽爲易水，嵩嶽是燕山。","俗变羗胡語，人多沙塞顏。","申包惟慟哭，七日鬢毛斑。"]', '诗', 'shi', '', NULL, '奔亡道中五首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf8d13d-79be-4657-8f96-ae6c7b5c0692', '奔亡道中五首 五', '奔亡道中五首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["淼淼望湖水，青青蘆葉齊。","歸心落何處，日沒大江西。","歇馬傍春草，欲行遠道迷。","誰忍子規鳥，連聲向我啼。"]', '["淼淼望湖水，青青蘆葉齊。","归心落何处，日沒大江西。","歇马傍春草，欲行远道迷。","誰忍子規鸟，連声向我啼。"]', '诗', 'shi', '', NULL, '奔亡道中五首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('546a04ac-8e3d-4bb3-b73d-3a5bdaaacc40', '郢門秋懷', '郢门秋懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["郢門一爲客，巴月三成弦。","朔風正搖落，行子愁歸旋。","杳杳山外日，茫茫江上天。","人迷洞庭水，雁度瀟湘烟。","清曠諧宿好，緇磷及此年。","百齡何蕩漾，萬化相推遷。","空謁蒼梧帝，徒尋溟海仙。","已聞蓬海淺，豈見三桃圓。","倚劒增浩歎，捫襟還自憐。","終當遊五湖，濯足滄浪泉。"]', '["郢门一爲客，巴月三成弦。","朔风正搖落，行子愁归旋。","杳杳山外日，茫茫江上天。","人迷洞庭水，雁度瀟湘烟。","清曠諧宿好，緇磷及此年。","百齡何蕩漾，万化相推遷。","空謁蒼梧帝，徒尋溟海仙。","已闻蓬海淺，豈见三桃圓。","倚劒增浩歎，捫襟還自怜。","終當游五湖，濯足滄浪泉。"]', '诗', 'shi', '', NULL, '郢門秋懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3763e6be-0dad-43e7-a277-c4253d87197a', '至鴨欄驛上白馬磯贈裴侍御', '至鴨欄驛上白马磯贈裴侍御', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["側疊萬古石，橫爲白馬磯。","亂流若電轉，舉櫂揚珠輝。","臨驛卷緹幕，升堂接繡衣。","情親不避馬，爲我解霜威。"]', '["側叠万古石，橫爲白马磯。","亂流若電轉，舉櫂揚珠輝。","臨驛卷緹幕，升堂接繡衣。","情親不避马，爲我解霜威。"]', '诗', 'shi', '', NULL, '至鴨欄驛上白馬磯贈裴侍御 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d771394-9918-46f0-a621-abdb5ebc9101', '荆門浮舟望蜀江', '荆门浮舟望蜀江', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["春水月峽來，浮舟望安極。","正是桃花流，依然錦江色。","江色綠且明，茫茫與天平。","逶迤巴山盡，搖曳楚雲行。","雪照聚沙雁，花飛出谷鶯。","芳洲却已轉，碧樹森森迎。","流目浦烟夕，揚帆海月生。","江陵識遙火，應到渚宮城。"]', '["春水月峽来，浮舟望安極。","正是桃花流，依然錦江色。","江色綠且明，茫茫與天平。","逶迤巴山尽，搖曳楚云行。","雪照聚沙雁，花飞出谷鶯。","芳洲却已轉，碧樹森森迎。","流目浦烟夕，揚帆海月生。","江陵識遙火，應到渚宮城。"]', '诗', 'shi', '', NULL, '荆門浮舟望蜀江 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b04d7649-3406-40a7-a582-1b319540a7f4', '上三峽', '上三峽', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["巫山夾青天，巴水流若茲。","巴水忽可盡，青天無到時。","三朝上黃牛，三暮行太遲。","三朝又三暮，不覺鬢成絲。"]', '["巫山夾青天，巴水流若茲。","巴水忽可尽，青天無到时。","三朝上黄牛，三暮行太遲。","三朝又三暮，不覺鬢成絲。"]', '诗', 'shi', '', NULL, '上三峽 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26391863-c700-46d7-b13d-d941358a4c7b', '自巴東舟行經瞿唐峽登巫山最高峰晚還題壁', '自巴东舟行經瞿唐峽登巫山最高峰晚還題壁', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["江行幾千里，海月十五圓。","始經瞿唐峽，遂步巫山巔。","巫山高不窮，巴國盡所歷。","日邊攀垂蘿，霞外倚穹石。","飛步凌絕頂，極目無纖烟。","却顧失舟壑，仰觀臨青天。","青天若可捫，銀漢去安在。","望雲知蒼梧，記水辨瀛海。","周遊孤光晚，歷覽幽意多。","積雪照空谷，悲風鳴森柯。","歸途行欲曛，佳趣尚未歇。","江寒早啼猨，松暝已吐月。","月色何悠悠，清猨響啾啾。","辭山不忍聽，揮策還孤舟。"]', '["江行幾千里，海月十五圓。","始經瞿唐峽，遂步巫山巔。","巫山高不窮，巴国尽所歷。","日邊攀垂蘿，霞外倚穹石。","飞步凌絕頂，極目無纖烟。","却顧失舟壑，仰观臨青天。","青天若可捫，銀漢去安在。","望云知蒼梧，記水辨瀛海。","周游孤光晚，歷覽幽意多。","積雪照空谷，悲风鳴森柯。","归途行欲曛，佳趣尚未歇。","江寒早啼猨，松暝已吐月。","月色何悠悠，清猨响啾啾。","辞山不忍听，揮策還孤舟。"]', '诗', 'shi', '', NULL, '自巴東舟行經瞿唐峽登巫山最高峰晚還題壁 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9525f99d-39cb-4d04-8650-263493d223e0', '早發白帝城', '早發白帝城', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝辭白帝彩雲間，千里江陵一日還。","兩岸猨聲啼不盡，輕舟已過萬重山。"]', '["朝辞白帝彩云间，千里江陵一日還。","兩岸猨声啼不尽，轻舟已過万重山。"]', '诗', 'shi', '', NULL, '早發白帝城 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7743536b-ca93-405f-80b4-95d156f70219', '秋下荆門', '秋下荆门', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["霜落荆門江樹空，布帆無恙挂秋風。","此行不爲鱸魚鱠，自愛名山入剡中。"]', '["霜落荆门江樹空，布帆無恙挂秋风。","此行不爲鱸鱼鱠，自愛名山入剡中。"]', '诗', 'shi', '', NULL, '秋下荆門 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e22a48b0-781e-4c01-a3fd-7bbed834945b', '江行寄遠', '江行寄远', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["刳木出吳楚，危槎百餘尺。","疾風吹片帆，日暮千里隔。","別時酒猶在，已爲異鄉客。","思君不可得，愁見江水碧。"]', '["刳木出吳楚，危槎百餘尺。","疾风吹片帆，日暮千里隔。","別时酒猶在，已爲異乡客。","思君不可得，愁见江水碧。"]', '诗', 'shi', '', NULL, '江行寄遠 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f7059e-2f45-4d80-9b86-7fc0d3003163', '宿五松山下荀媼家', '宿五松山下荀媼家', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我宿五松下，寂寥無所歡。","田家秋作苦，鄰女夜舂寒。","跪進雕胡飯，月光明素盤。","令人慚漂母，三謝不能餐。"]', '["我宿五松下，寂寥無所歡。","田家秋作苦，鄰女夜舂寒。","跪進雕胡飯，月光明素盤。","令人慚漂母，三謝不能餐。"]', '诗', 'shi', '', NULL, '宿五松山下荀媼家 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a048cbb0-9793-4abd-b1d9-b925c8077a07', '下涇縣陵陽溪至澁灘', '下涇縣陵陽溪至澁灘', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["澁灘鳴嘈嘈，兩山足猨猱。","白波若卷雪，側足不容舠。","漁子與舟人，撐折萬張篙。"]', '["澁灘鳴嘈嘈，兩山足猨猱。","白波若卷雪，側足不容舠。","漁子與舟人，撐折万張篙。"]', '诗', 'shi', '', NULL, '下涇縣陵陽溪至澁灘 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc8b9d4-3e07-4233-a574-0689bb95c6b4', '下陵陽沿高溪三門六剌灘', '下陵陽沿高溪三门六剌灘', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三門橫峻灘，六剌走波瀾。","石驚虎伏起，水狀龍縈盤。","何慙七里瀨，使我欲垂竿。"]', '["三门橫峻灘，六剌走波瀾。","石驚虎伏起，水狀龙縈盤。","何慙七里瀨，使我欲垂竿。"]', '诗', 'shi', '', NULL, '下陵陽沿高溪三門六剌灘 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc8cb4d0-bdb1-45ab-84ba-eff238065e00', '夜泊黃山聞殷十四吳吟', '夜泊黄山闻殷十四吳吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昨夜誰爲吳會吟，風生萬壑振空林。","龍驚不敢水中臥，猨嘯時聞巖下音。","我宿黃山碧溪月，聽之却罷松間琴。","朝來果是滄洲逸，酤酒醍盤飯霜栗。","半酣更發江海聲，客愁頓向杯中失。"]', '["昨夜誰爲吳會吟，风生万壑振空林。","龙驚不敢水中臥，猨嘯时闻巖下音。","我宿黄山碧溪月，听之却罷松间琴。","朝来果是滄洲逸，酤酒醍盤飯霜栗。","半酣更發江海声，客愁頓向杯中失。"]', '诗', 'shi', '', NULL, '夜泊黃山聞殷十四吳吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01a954e3-4ca7-4564-9e7d-8db629560b0b', '宿鰕湖', '宿鰕湖', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雞鳴發黃山，暝投鰕湖宿。","白雨暎寒山，森森似銀竹。","提攜採鉛客，結荷水邊沐。","半夜四天開，星河爛人目。","明晨大樓去，岡隴多屈伏。","當與持斧翁，前溪伐雲木。"]', '["雞鳴發黄山，暝投鰕湖宿。","白雨暎寒山，森森似銀竹。","提携採鉛客，結荷水邊沐。","半夜四天开，星河爛人目。","明晨大楼去，岡隴多屈伏。","當與持斧翁，前溪伐云木。"]', '诗', 'shi', '', NULL, '宿鰕湖 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb86c78-913e-4b2b-a1e3-1bdd6408fdd1', '西施', '西施', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西施越溪女，出自苧蘿山。","秀色掩今古，荷花羞玉顏。","浣紗弄碧水，自與清波閑。","皓齒信難開，沈吟碧雲間。","句踐徵絕豔，揚蛾入吳關。","提攜館娃宮，杳渺詎可攀。","一破夫差國，千秋竟不還。"]', '["西施越溪女，出自苧蘿山。","秀色掩今古，荷花羞玉顏。","浣紗弄碧水，自與清波闲。","皓齒信难开，沈吟碧云间。","句踐徵絕豔，揚蛾入吳关。","提携館娃宮，杳渺詎可攀。","一破夫差国，千秋竟不還。"]', '诗', 'shi', '', NULL, '西施 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b50a83-3a22-4297-9106-20dcee9c3a37', '王右軍', '王右軍', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["右軍本清真，瀟灑出風塵。","山陰過羽客，愛此好鵝賓。","掃素寫道經，筆精妙入神。","書罷籠鵝去，何曾別主人。"]', '["右軍本清真，瀟灑出风塵。","山陰過羽客，愛此好鵝賓。","掃素寫道經，笔精妙入神。","书罷籠鵝去，何曾別主人。"]', '诗', 'shi', '', NULL, '王右軍 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f21a8baf-4b8d-4d67-9c06-6122a512d9fc', '上元夫人', '上元夫人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["上元誰夫人，偏得王母嬌。","嵯峨三角髻，餘髮散垂腰。","裘披青毛錦，身著赤霜袍。","手提嬴女兒，閑與鳳吹簫。","眉語兩自笑，忽然隨風飄。"]', '["上元誰夫人，偏得王母嬌。","嵯峨三角髻，餘髮散垂腰。","裘披青毛錦，身著赤霜袍。","手提嬴女兒，闲與鳳吹簫。","眉語兩自笑，忽然隨风飄。"]', '诗', 'shi', '', NULL, '上元夫人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41618979-004e-4d9f-b032-c69316eeb660', '蘇臺覽古', '蘇台覽古', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["舊苑荒臺楊柳新，菱歌清唱不勝春。","只今惟有西江月，曾照吳王宮裏人。"]', '["旧苑荒台楊柳新，菱歌清唱不勝春。","只今惟有西江月，曾照吳王宮裏人。"]', '诗', 'shi', '', NULL, '蘇臺覽古 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce6ab82-5b1a-4117-908a-819af59e47ae', '越中覽古', '越中覽古', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["越王句踐破吳歸，義士還鄉盡錦衣。","宮女如花滿春殿，只今惟有鷓鴣飛。"]', '["越王句踐破吳归，義士還乡尽錦衣。","宮女如花满春殿，只今惟有鷓鴣飞。"]', '诗', 'shi', '', NULL, '越中覽古 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c2eb6b-d408-4b7e-b9ff-3ad80fde6a25', '商山四皓', '商山四皓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白髮四老人，昂藏南山側。","偃臥松雪間，冥翳不可識。","雲窗拂青靄，石壁橫翠色。","龍虎方戰爭，於焉自休息。","秦人失金鏡，漢祖昇紫極。","陰虹濁太陽，前星遂淪匿。","一行佐明聖，倏起生羽翼。","功成身不居，舒卷在胸臆。","窅冥合元化，茫昧信難測。","飛聲塞天衢，萬古仰遺則。"]', '["白髮四老人，昂藏南山側。","偃臥松雪间，冥翳不可識。","云窗拂青靄，石壁橫翠色。","龙虎方戰爭，於焉自休息。","秦人失金镜，漢祖昇紫極。","陰虹濁太陽，前星遂淪匿。","一行佐明聖，倏起生羽翼。","功成身不居，舒卷在胸臆。","窅冥合元化，茫昧信难測。","飞声塞天衢，万古仰遺則。"]', '诗', 'shi', '', NULL, '商山四皓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c54de925-9760-4d21-bfb1-fcfec238ccad', '過四皓墓', '過四皓墓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我行至商洛，幽獨訪神仙。","園綺復安在，雲蘿尚宛然。","荒涼千古跡，蕪沒四墳連。","伊昔鍊金鼎，何年閉玉泉。","隴寒惟有月，松古漸無煙。","木魅風號去，山精雨嘯旋。","紫芝高詠罷，青史舊名傳。","今日併如此，哀哉信可憐。"]', '["我行至商洛，幽独訪神仙。","园綺复安在，云蘿尚宛然。","荒涼千古跡，蕪沒四墳連。","伊昔鍊金鼎，何年閉玉泉。","隴寒惟有月，松古漸無煙。","木魅风號去，山精雨嘯旋。","紫芝高詠罷，青史旧名傳。","今日併如此，哀哉信可怜。"]', '诗', 'shi', '', NULL, '過四皓墓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53dd2dfa-4479-4932-a262-a80648e55557', '峴山懷古', '峴山懷古', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["訪古登峴首，憑高眺襄中。","天清遠峰出，水落寒沙空。","弄珠見遊女，醉酒懷山公。","感歎發秋興，長松鳴夜風。"]', '["訪古登峴首，憑高眺襄中。","天清远峰出，水落寒沙空。","弄珠见游女，醉酒懷山公。","感歎發秋兴，长松鳴夜风。"]', '诗', 'shi', '', NULL, '峴山懷古 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94388fcc-9175-4551-a4f2-08a20319cd53', '蘇武', '蘇武', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蘇武在匈奴，十年持漢節。","白雁上林飛，空傳一書札。","牧羊邊地苦，落日歸心絕。","渴飲月窟冰，肌餐天上雪。","東還沙塞遠，北愴河梁別。","泣把李陵衣，相看淚成血。"]', '["蘇武在匈奴，十年持漢節。","白雁上林飞，空傳一书札。","牧羊邊地苦，落日归心絕。","渴饮月窟冰，肌餐天上雪。","东還沙塞远，北愴河梁別。","泣把李陵衣，相看泪成血。"]', '诗', 'shi', '', NULL, '蘇武 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93d35411-4b3c-4b98-8fc2-a319bf1fa6ef', '經下邳圯橋懷張子房', '經下邳圯橋懷張子房', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["子房未虎嘯，破產不爲家。","滄海得壯士，椎秦博浪沙。","報韓雖不成，天地皆振動。","潛匿遊下邳，豈曰非智勇。","我來圯橋上，懷古欽英風。","惟見碧流水，曾無黃石公。","歎息此人去，蕭條徐泗空。"]', '["子房未虎嘯，破產不爲家。","滄海得壯士，椎秦博浪沙。","報韓雖不成，天地皆振动。","潛匿游下邳，豈曰非智勇。","我来圯橋上，懷古欽英风。","惟见碧流水，曾無黄石公。","歎息此人去，蕭條徐泗空。"]', '诗', 'shi', '', NULL, '經下邳圯橋懷張子房 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9d1226-344a-4620-81cb-368bc9bf8c50', '金陵三首 一', '金陵三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["晉家南渡日，此地舊長安。","地即帝王宅，山爲龍虎盤。","金陵空壯觀，天塹淨波瀾。","醉客回橈去，吳歌且自歡。"]', '["晉家南渡日，此地旧长安。","地即帝王宅，山爲龙虎盤。","金陵空壯观，天塹淨波瀾。","醉客回橈去，吳歌且自歡。"]', '诗', 'shi', '', NULL, '金陵三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0493fe73-9709-4bba-9d88-196de5ff1932', '金陵三首 二', '金陵三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["地擁金陵勢，城迴江水流。","當時百萬戶，夾道起朱樓。","亡國生春草，離宮沒古丘。","空餘後湖月，波上對江州。"]', '["地擁金陵勢，城迴江水流。","當时百万戶，夾道起朱楼。","亡国生春草，離宮沒古丘。","空餘後湖月，波上对江州。"]', '诗', 'shi', '', NULL, '金陵三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1e5229-512c-4ebd-9966-f23bd8895e41', '金陵三首 三', '金陵三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["六代興亡國，三杯爲爾歌。","苑方秦地少，山似洛陽多。","古殿吳花草，深宮晉綺羅。","併隨人事滅，東逝與滄波。"]', '["六代兴亡国，三杯爲爾歌。","苑方秦地少，山似洛陽多。","古殿吳花草，深宮晉綺羅。","併隨人事滅，东逝與滄波。"]', '诗', 'shi', '', NULL, '金陵三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc856594-e3fa-417c-a607-17e891c84cbd', '秋夜板橋浦泛月獨酌懷謝朓', '秋夜板橋浦泛月独酌懷謝朓', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天上何所有，迢迢白玉繩。","斜低建章闕，耿耿對金陵。","漢水舊如練，霜江夜清澄。","長川瀉落月，洲渚曉寒凝。","獨酌板橋浦，古人誰可徵。","玄暉難再得，灑酒氣填膺。"]', '["天上何所有，迢迢白玉繩。","斜低建章闕，耿耿对金陵。","漢水旧如練，霜江夜清澄。","长川瀉落月，洲渚晓寒凝。","独酌板橋浦，古人誰可徵。","玄暉难再得，灑酒氣填膺。"]', '诗', 'shi', '', NULL, '秋夜板橋浦泛月獨酌懷謝朓 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4c800e1-8162-4727-9216-a1044731140d', '入彭蠡經松門觀石鏡緬懷謝康樂題詩書遊覽之志', '入彭蠡經松门观石镜緬懷謝康乐題诗书游覽之志', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["謝公之彭蠡，因此遊松門。","余方窺石鏡，兼得窮江源。","將欲繼風雅，豈徒清心魂。","前賞逾所見，後來道空存。","況屬臨汎美，而無洲渚喧。","漾水向東去，漳流直南奔。","空濛三川夕，回合千里昏。","青桂隱遙月，綠楓鳴愁猨。","水碧或可采，金精祕莫論。","吾將學仙去，冀與琴高言。"]', '["謝公之彭蠡，因此游松门。","余方窺石镜，兼得窮江源。","將欲繼风雅，豈徒清心魂。","前賞逾所见，後来道空存。","況屬臨汎美，而無洲渚喧。","漾水向东去，漳流直南奔。","空濛三川夕，回合千里昏。","青桂隐遙月，綠楓鳴愁猨。","水碧或可采，金精祕莫論。","吾將学仙去，冀與琴高言。"]', '诗', 'shi', '', NULL, '入彭蠡經松門觀石鏡緬懷謝康樂題詩書遊覽之志 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59700741-34ac-4b86-8e8f-bfa50e21b896', '廬江主人婦', '廬江主人婦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["孔雀東飛何處棲，廬江小吏仲卿妻。","爲客裁縫君自見，城烏獨宿夜空啼。"]', '["孔雀东飞何处棲，廬江小吏仲卿妻。","爲客裁縫君自见，城烏独宿夜空啼。"]', '诗', 'shi', '', NULL, '廬江主人婦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc70bec0-2c97-40e3-a3b8-043b00385568', '陪宋中丞武昌夜飲懷古', '陪宋中丞武昌夜饮懷古', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清景南樓夜，風流在武昌。","庾公愛秋月，乘興坐胡牀。","龍笛吟寒水，天河落曉霜。","我心還不淺，懷古醉餘觴。"]', '["清景南楼夜，风流在武昌。","庾公愛秋月，乘兴坐胡牀。","龙笛吟寒水，天河落晓霜。","我心還不淺，懷古醉餘觴。"]', '诗', 'shi', '', NULL, '陪宋中丞武昌夜飲懷古 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75cb17e4-7da4-4eaa-a2f7-456161eb6a0c', '望鸚鵡洲懷禰衡', '望鸚鵡洲懷禰衡', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魏帝營八極，蟻觀一禰衡。","黃祖斗筲人，殺之受惡名。","吳江賦鸚鵡，落筆超羣英。","鏘鏘振金玉，句句欲飛鳴。","鷙鶚啄孤鳳，千春傷我情。","五嶽起方寸，隱然詎可平。","才高竟何施，寡識冒天刑。","至今芳洲上，蘭蕙不忍生。"]', '["魏帝營八極，蟻观一禰衡。","黄祖斗筲人，殺之受惡名。","吳江賦鸚鵡，落笔超羣英。","鏘鏘振金玉，句句欲飞鳴。","鷙鶚啄孤鳳，千春傷我情。","五嶽起方寸，隐然詎可平。","才高竟何施，寡識冒天刑。","至今芳洲上，蘭蕙不忍生。"]', '诗', 'shi', '', NULL, '望鸚鵡洲懷禰衡 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b4078e-5417-4fee-ae8d-23e35a09c429', '宿巫山下', '宿巫山下', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昨夜巫山下，猨聲夢裏長。","桃花飛綠水，三月下瞿塘。","雨色風吹去，南行拂楚王。","高丘懷宋玉，訪古一霑裳。"]', '["昨夜巫山下，猨声梦裏长。","桃花飞綠水，三月下瞿塘。","雨色风吹去，南行拂楚王。","高丘懷宋玉，訪古一霑裳。"]', '诗', 'shi', '', NULL, '宿巫山下 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23fcc4ef-2c9a-4659-bee8-2b1af4f4965f', '金陵白楊十字巷', '金陵白楊十字巷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白楊十字巷，北夾湖溝道。","不見吳時人，空生唐年草。","天地有反覆，宮城盡傾倒。","六帝餘古丘，樵蘇泣遺老。"]', '["白楊十字巷，北夾湖溝道。","不见吳时人，空生唐年草。","天地有反覆，宮城尽傾倒。","六帝餘古丘，樵蘇泣遺老。"]', '诗', 'shi', '', NULL, '金陵白楊十字巷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('727eb3e0-7ce3-4886-a25d-1b2238703a74', '謝公亭', '謝公亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["謝公離別處，風景每生愁。","客散青天月，山空碧水流。","池花春暎日，窗竹夜鳴秋。","今古一相接，長歌懷舊遊。"]', '["謝公離別处，风景每生愁。","客散青天月，山空碧水流。","池花春暎日，窗竹夜鳴秋。","今古一相接，长歌懷旧游。"]', '诗', 'shi', '', NULL, '謝公亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4d7c6d-ffb1-4674-9053-292b475ec9fd', '紀南陵題五松山', '紀南陵題五松山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["聖達有去就，潛光愚其德。","魚與龍同池，龍去魚不測。","當時版築輩，豈知傅說情。","一朝和殷羹，光氣爲列星。","伊尹生空桑，捐庖佐皇極。","桐宮放太甲，攝政無愧色。","三年帝道明，委質終輔翼。","曠哉至人心，萬古可爲則。","時命或大繆，仲尼將奈何。","鸞鳳忽覆巢，麒麟不來過。","龜山蔽魯國，有斧且無柯。","歸來歸去來，宵濟越洪波。"]', '["聖達有去就，潛光愚其德。","鱼與龙同池，龙去鱼不測。","當时版築輩，豈知傅说情。","一朝和殷羹，光氣爲列星。","伊尹生空桑，捐庖佐皇極。","桐宮放太甲，攝政無愧色。","三年帝道明，委質終輔翼。","曠哉至人心，万古可爲則。","时命或大繆，仲尼將奈何。","鸾鳳忽覆巢，麒麟不来過。","龟山蔽魯国，有斧且無柯。","归来归去来，宵濟越洪波。"]', '诗', 'shi', '', NULL, '紀南陵題五松山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e1be9c9-fa2f-44c2-a6bc-3edcece745fe', '夜泊牛渚懷古', '夜泊牛渚懷古', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["牛渚西江夜，青天無片雲。","登舟望秋月，空憶謝將軍。","余亦能高詠，斯人不可聞。","明朝挂帆席，楓葉落紛紛。"]', '["牛渚西江夜，青天無片云。","登舟望秋月，空憶謝將軍。","余亦能高詠，斯人不可闻。","明朝挂帆席，楓葉落紛紛。"]', '诗', 'shi', '', NULL, '夜泊牛渚懷古 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342005b5-87b2-41cb-814d-7010ac43e9db', '姑孰十詠 姑孰溪', '姑孰十詠 姑孰溪', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["愛此溪水閑，乘流興無極。","漾楫怕鷗驚，垂竿待魚食。","波飜曉霞影，岸疊春山色。","何處浣紗人，紅顏未相識。"]', '["愛此溪水闲，乘流兴無極。","漾楫怕鷗驚，垂竿待鱼食。","波飜晓霞影，岸叠春山色。","何处浣紗人，紅顏未相識。"]', '诗', 'shi', '', NULL, '姑孰十詠 姑孰溪 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e80219-d018-4966-a7d7-4a324f34c4a2', '姑孰十詠 丹陽湖', '姑孰十詠 丹陽湖', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["湖與元氣連，風波浩難止。","天外賈客歸，雲間片帆起。","龜遊蓮葉上，鳥宿蘆花裏。","少女櫂歸舟，歌聲逐流水。"]', '["湖與元氣連，风波浩难止。","天外賈客归，云间片帆起。","龟游蓮葉上，鸟宿蘆花裏。","少女櫂归舟，歌声逐流水。"]', '诗', 'shi', '', NULL, '姑孰十詠 丹陽湖 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d37e079e-33e7-480a-bd39-7bd72e58420b', '姑孰十詠 謝公宅', '姑孰十詠 謝公宅', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青山日將暝，寂寞謝公宅。","竹裏無人聲，池中虛月白。","荒庭衰草徧，廢井蒼苔積。","惟有清風閑，時時起泉石。"]', '["青山日將暝，寂寞謝公宅。","竹裏無人声，池中虛月白。","荒庭衰草徧，廢井蒼苔積。","惟有清风闲，时时起泉石。"]', '诗', 'shi', '', NULL, '姑孰十詠 謝公宅 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f637920-0d93-44a1-8b24-596ec27fc951', '姑孰十詠 陵歊臺', '姑孰十詠 陵歊台', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["曠望登古臺，臺高極人目。","疊嶂列遠空，雜花間平陸。","閑雲入窗牖，野翠生松竹。","欲覽碑上文，苔侵豈堪讀。"]', '["曠望登古台，台高極人目。","叠嶂列远空，杂花间平陸。","闲云入窗牖，野翠生松竹。","欲覽碑上文，苔侵豈堪读。"]', '诗', 'shi', '', NULL, '姑孰十詠 陵歊臺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6769dfab-6139-4b48-bc93-11bf56b21e08', '姑孰十詠 桓公井', '姑孰十詠 桓公井', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桓公名已古，廢井曾未竭。","石甃冷蒼苔，寒泉湛孤月。","秋來桐暫落，春至桃還發。","路遠人罕窺，誰能見清徹。"]', '["桓公名已古，廢井曾未竭。","石甃冷蒼苔，寒泉湛孤月。","秋来桐暫落，春至桃還發。","路远人罕窺，誰能见清徹。"]', '诗', 'shi', '', NULL, '姑孰十詠 桓公井 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a14ea0-64c6-4493-a8de-5c8fa91adcc0', '姑孰十詠 慈姥竹', '姑孰十詠 慈姥竹', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["野竹攢石生，含煙暎江島。","翠色落波深，虛聲帶寒早。","龍吟曾未聽，鳳曲吹應好。","不學蒲柳凋，貞心嘗自保。"]', '["野竹攢石生，含煙暎江島。","翠色落波深，虛声带寒早。","龙吟曾未听，鳳曲吹應好。","不学蒲柳凋，貞心嘗自保。"]', '诗', 'shi', '', NULL, '姑孰十詠 慈姥竹 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8045fafa-3f64-49dd-a6ed-e27a52d8064e', '姑孰十詠 望夫山', '姑孰十詠 望夫山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["顒望臨碧空，怨情感離別。","江草不知愁，巖花但爭發。","雲山萬重隔，音信千里絕。","春去秋復來，相思幾時歇。"]', '["顒望臨碧空，怨情感離別。","江草不知愁，巖花但爭發。","云山万重隔，音信千里絕。","春去秋复来，相思幾时歇。"]', '诗', 'shi', '', NULL, '姑孰十詠 望夫山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1ba6051-6dc7-42ba-a6d6-9580a426e2fa', '姑孰十詠 牛渚磯', '姑孰十詠 牛渚磯', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["絕壁臨巨川，連峰勢相向。","亂石流洑間，迴波自成浪。","但驚羣木秀，莫測精靈狀。","更聽猨夜啼，憂心醉江上。"]', '["絕壁臨巨川，連峰勢相向。","亂石流洑间，迴波自成浪。","但驚羣木秀，莫測精靈狀。","更听猨夜啼，憂心醉江上。"]', '诗', 'shi', '', NULL, '姑孰十詠 牛渚磯 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18c6d150-033a-4d33-a83f-3513323da7d2', '姑孰十詠 靈墟山', '姑孰十詠 靈墟山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["丁令辭世人，拂衣向仙路。","伏鍊九丹成，方隨五雲去。","松蘿蔽幽洞，桃杏深隱處。","不知曾化鶴，遼海歸幾度。"]', '["丁令辞世人，拂衣向仙路。","伏鍊九丹成，方隨五云去。","松蘿蔽幽洞，桃杏深隐处。","不知曾化鹤，遼海归幾度。"]', '诗', 'shi', '', NULL, '姑孰十詠 靈墟山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86e9088a-6186-4466-9416-c6d97bec7077', '姑孰十詠 天門山', '姑孰十詠 天门山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["逈出江山上，雙峰自相對。","岸暎松色寒，石分浪花碎。","參差遠天際，縹緲晴霞外。","落日舟去遙，迴首沈青靄。"]', '["逈出江山上，雙峰自相对。","岸暎松色寒，石分浪花碎。","參差远天際，縹緲晴霞外。","落日舟去遙，迴首沈青靄。"]', '诗', 'shi', '', NULL, '姑孰十詠 天門山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feaace98-d325-4210-bb70-62e3502da7d9', '與元丹丘方城寺談玄作', '與元丹丘方城寺談玄作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["茫茫大夢中，惟我獨先覺。","騰轉風火來，假合作容貌。","滅除昏疑盡，領略入精要。","澄慮觀此身，因得通寂照。","朗悟前後際，始知金仙妙。","幸逢禪居人，酌玉坐相召。","彼我俱若喪，雲山豈殊調。","清風生虛空，明月見談笑。","怡然青蓮宮，永願姿遊眺。"]', '["茫茫大梦中，惟我独先覺。","腾轉风火来，假合作容貌。","滅除昏疑尽，領略入精要。","澄慮观此身，因得通寂照。","朗悟前後際，始知金仙妙。","幸逢禪居人，酌玉坐相召。","彼我俱若喪，云山豈殊調。","清风生虛空，明月见談笑。","怡然青蓮宮，永願姿游眺。"]', '诗', 'shi', '', NULL, '與元丹丘方城寺談玄作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be4fa628-ef1d-41ca-831a-7594974e9429', '尋高鳳石門山中元丹丘', '尋高鳳石门山中元丹丘', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["尋幽無前期，乘興不覺遠。","蒼厓渺難涉，白日忽欲晚。","未窮三四山，已歷千萬轉。","寂寂聞猨愁，行行見雲收。","高松來好月，空谷宜清秋。","溪深古雪在，石斷寒泉流。","峰巒秀中天，登眺不可盡。","丹丘遙相呼，顧我忽而哂。","遂造窮谷間，始知靜者閑。","留歡達永夜，清曉方言還。"]', '["尋幽無前期，乘兴不覺远。","蒼厓渺难涉，白日忽欲晚。","未窮三四山，已歷千万轉。","寂寂闻猨愁，行行见云收。","高松来好月，空谷宜清秋。","溪深古雪在，石斷寒泉流。","峰巒秀中天，登眺不可尽。","丹丘遙相呼，顧我忽而哂。","遂造窮谷间，始知静者闲。","留歡達永夜，清晓方言還。"]', '诗', 'shi', '', NULL, '尋高鳳石門山中元丹丘 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf7d263-5546-40da-9695-34721dac1493', '安州般若水閣納涼喜遇薛員外乂', '安州般若水閣納涼喜遇薛員外乂', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["翛然金園賞，遠近含晴光。","樓臺成海氣，草木皆天香。","忽逢青雲士，共解丹霞裳。","水退池上熱，風生松下涼。","吞討破萬象，搴窺臨衆芳。","而我遺有漏，與君用無方。","心垢都已滅，永言題禪房。"]', '["翛然金园賞，远近含晴光。","楼台成海氣，草木皆天香。","忽逢青云士，共解丹霞裳。","水退池上熱，风生松下涼。","吞討破万象，搴窺臨衆芳。","而我遺有漏，與君用無方。","心垢都已滅，永言題禪房。"]', '诗', 'shi', '', NULL, '安州般若水閣納涼喜遇薛員外乂 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3935a437-6df6-4006-a5b1-cf35375d7a8b', '魯中都東樓醉起作', '魯中都东楼醉起作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昨日東樓醉，還應倒接䍦。","阿誰扶上馬，不省下樓時。"]', '["昨日东楼醉，還應倒接䍦。","阿誰扶上马，不省下楼时。"]', '诗', 'shi', '', NULL, '魯中都東樓醉起作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0eef61e-6dca-4dbc-beff-3228bce783ce', '對酒醉題屈突明府廳', '对酒醉題屈突明府廳', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["陶令八十日，長歌歸去來。","故人建昌宰，借問幾時迴。","風落吳江雪，紛紛入酒杯。","山翁今已醉，舞袖爲君開。"]', '["陶令八十日，长歌归去来。","故人建昌宰，借问幾时迴。","风落吳江雪，紛紛入酒杯。","山翁今已醉，舞袖爲君开。"]', '诗', 'shi', '', NULL, '對酒醉題屈突明府廳 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e70b6e-ff59-4a3b-8e81-249ab0cda0c3', '月下獨酌四首 一', '月下独酌四首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["花間一壺酒，獨酌無相親。","舉杯邀明月，對影成三人。","月既不解飲，影徒隨我身。","暫伴月將影，行樂須及春。","我歌月裴回，我舞影零亂。","醒時同交歡，醉後各分散。","永結無情遊，相期邈雲漢。"]', '["花间一壺酒，独酌無相親。","舉杯邀明月，对影成三人。","月既不解饮，影徒隨我身。","暫伴月將影，行乐須及春。","我歌月裴回，我舞影零亂。","醒时同交歡，醉後各分散。","永結無情游，相期邈云漢。"]', '诗', 'shi', '', NULL, '月下獨酌四首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d835f44-d5ee-4d4a-ad46-26891f2b9e6f', '月下獨酌四首 二', '月下独酌四首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天若不愛酒，酒星不在天。","地若不愛酒，地應無酒泉。","天地既愛酒，愛酒不愧天。","已聞清比聖，復道濁如賢。","賢聖既已飲，何必求神仙。","三杯通大道，一斗合自然。","但得酒中趣，勿爲醒者傳。"]', '["天若不愛酒，酒星不在天。","地若不愛酒，地應無酒泉。","天地既愛酒，愛酒不愧天。","已闻清比聖，复道濁如賢。","賢聖既已饮，何必求神仙。","三杯通大道，一斗合自然。","但得酒中趣，勿爲醒者傳。"]', '诗', 'shi', '', NULL, '月下獨酌四首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a643857d-d6fc-4f41-a4a7-febaa209562e', '月下獨酌四首 三', '月下独酌四首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三月咸陽城，千花晝如錦。","誰能春獨愁，對此徑須飲。","窮通與修短，造化夙所稟。","一樽齊死生，萬事固難審。","醉後失天地，兀然就孤枕。","不知有吾身，此樂最爲甚。"]', '["三月咸陽城，千花晝如錦。","誰能春独愁，对此徑須饮。","窮通與修短，造化夙所稟。","一樽齊死生，万事固难審。","醉後失天地，兀然就孤枕。","不知有吾身，此乐最爲甚。"]', '诗', 'shi', '', NULL, '月下獨酌四首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97dad3b0-37a6-4c79-b59c-4500b97d63eb', '月下獨酌四首 四', '月下独酌四首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["窮愁千萬端，美酒三百杯。","愁多酒雖少，酒傾愁不來。","所以知酒聖，酒酣心自開。","辭粟臥首陽，屢空飢顏回。","當代不樂飲，虛名安用哉。","蟹螯即金液，糟丘是蓬萊。","且須飲美酒，乘月醉高臺。"]', '["窮愁千万端，美酒三百杯。","愁多酒雖少，酒傾愁不来。","所以知酒聖，酒酣心自开。","辞粟臥首陽，屢空飢顏回。","當代不乐饮，虛名安用哉。","蟹螯即金液，糟丘是蓬萊。","且須饮美酒，乘月醉高台。"]', '诗', 'shi', '', NULL, '月下獨酌四首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc0512e6-2249-45ff-a710-43cacb6673be', '春歸終南山松龕舊隱', '春归終南山松龕旧隐', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我來南山陽，事事不異昔。","却尋溪中水，還望巖下石。","薔薇緣東窗，女蘿遶北壁。","別來能幾日，草木長數尺。","且復命酒樽，獨酌陶永夕。"]', '["我来南山陽，事事不異昔。","却尋溪中水，還望巖下石。","薔薇緣东窗，女蘿遶北壁。","別来能幾日，草木长數尺。","且复命酒樽，独酌陶永夕。"]', '诗', 'shi', '', NULL, '春歸終南山松龕舊隱 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc1da0a-da1f-44f4-94d9-1ad66bed37c4', '冬夜醉宿龍門覺起言志', '冬夜醉宿龙门覺起言志', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["醉來脫寶劒，旅憩高堂眠。","中夜忽驚覺，起立明燈前。","開軒聊直望，曉雪河冰壯。","哀哀歌苦寒，鬱鬱獨惆悵。","傅說版築臣，李斯鷹犬人。","歘起匡社稷，寧復長艱辛。","而我胡爲者，歎息龍門下。","富貴未可期，殷憂向誰寫。","去去淚滿襟，舉聲梁甫吟。","青雲當自致，何必求知音。"]', '["醉来脫寶劒，旅憩高堂眠。","中夜忽驚覺，起立明灯前。","开軒聊直望，晓雪河冰壯。","哀哀歌苦寒，鬱鬱独惆悵。","傅说版築臣，李斯鷹犬人。","歘起匡社稷，寧复长艱辛。","而我胡爲者，歎息龙门下。","富貴未可期，殷憂向誰寫。","去去泪满襟，舉声梁甫吟。","青云當自致，何必求知音。"]', '诗', 'shi', '', NULL, '冬夜醉宿龍門覺起言志 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a6f2822-0128-4791-b2f3-9d0d1bc33a60', '尋山僧不遇作', '尋山僧不遇作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["石徑入丹壑，松門閉青苔。","閑階有鳥跡，禪室無人開。","窺窗見白拂，挂壁生塵埃。","使我空歎息，欲去仍裴回。","香雲徧山起，花雨從天來。","已有空樂好，況聞青猨哀。","了然絕世事，此地方悠哉。"]', '["石徑入丹壑，松门閉青苔。","闲階有鸟跡，禪室無人开。","窺窗见白拂，挂壁生塵埃。","使我空歎息，欲去仍裴回。","香云徧山起，花雨從天来。","已有空乐好，況闻青猨哀。","了然絕世事，此地方悠哉。"]', '诗', 'shi', '', NULL, '尋山僧不遇作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4add7af1-aa2b-44fb-b28c-4680d40e4c07', '過汪氏別業二首 一', '過汪氏別業二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遊山誰可遊，子明與浮丘。","疊嶺礙河漢，連峰橫斗牛。","汪生面北阜，池館清且幽。","我來感意氣，搥炰列珍羞。","掃石待歸月，開池漲寒流。","酒酣益爽氣，爲樂不知秋。"]', '["游山誰可游，子明與浮丘。","叠嶺礙河漢，連峰橫斗牛。","汪生面北阜，池館清且幽。","我来感意氣，搥炰列珍羞。","掃石待归月，开池漲寒流。","酒酣益爽氣，爲乐不知秋。"]', '诗', 'shi', '', NULL, '過汪氏別業二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('044f9513-2781-44e0-a6bc-8a8f89662875', '過汪氏別業二首 二', '過汪氏別業二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["疇昔未識君，知君好賢才。","隨山起館宇，鑿石營池臺。","星火五月中，景風從南來。","數枝石榴發，一丈荷花開。","恨不當此時，相過醉金罍。","我行值木落，月苦清猨哀。","永夜達五更，吳歈送瓊杯。","酒酣欲起舞，四座歌相催。","日出遠海明，軒車且裴回。","更遊龍潭去，枕石拂莓苔。"]', '["疇昔未識君，知君好賢才。","隨山起館宇，鑿石營池台。","星火五月中，景风從南来。","數枝石榴發，一丈荷花开。","恨不當此时，相過醉金罍。","我行值木落，月苦清猨哀。","永夜達五更，吳歈送瓊杯。","酒酣欲起舞，四座歌相催。","日出远海明，軒车且裴回。","更游龙潭去，枕石拂莓苔。"]', '诗', 'shi', '', NULL, '過汪氏別業二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5cd198a-3ef2-4de5-919a-092a74d067fd', '待酒不至', '待酒不至', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉壺繫青絲，沽酒來何遲。","山花向我笑，正好銜杯時。","晚酌東窗下，流鶯復在茲。","春風與醉客，今日乃相宜。"]', '["玉壺繫青絲，沽酒来何遲。","山花向我笑，正好銜杯时。","晚酌东窗下，流鶯复在茲。","春风與醉客，今日乃相宜。"]', '诗', 'shi', '', NULL, '待酒不至 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('063c9e1b-9794-46ce-acff-5c1030ab7e77', '獨酌', '独酌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["春草如有意，羅生玉堂陰。","東風吹愁來，白髮坐相侵。","獨酌勸孤影，閑歌面芳林。","長松爾何知，蕭瑟爲誰吟。","手舞石上月，膝橫花間琴。","過此一壺外，悠悠非我心。"]', '["春草如有意，羅生玉堂陰。","东风吹愁来，白髮坐相侵。","独酌勸孤影，闲歌面芳林。","长松爾何知，蕭瑟爲誰吟。","手舞石上月，膝橫花间琴。","過此一壺外，悠悠非我心。"]', '诗', 'shi', '', NULL, '獨酌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c74a0fa-9059-4951-af44-9b8a3369ba53', '友人會宿', '友人會宿', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["滌蕩千古愁，留連百壺飲。","良宵宜清談，皓月未能寢。","醉來臥空山，天地即衾枕。"]', '["滌蕩千古愁，留連百壺饮。","良宵宜清談，皓月未能寢。","醉来臥空山，天地即衾枕。"]', '诗', 'shi', '', NULL, '友人會宿 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849c7103-6c9d-40c6-8210-60e602915209', '春日獨酌二首 一', '春日独酌二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["東風扇淑氣，水木榮春暉。","白日照綠草，落花散且飛。","孤雲還空山，衆鳥各已歸。","彼物皆有託，吾生獨無依。","對此石上月，長醉歌芳菲。"]', '["东风扇淑氣，水木榮春暉。","白日照綠草，落花散且飞。","孤云還空山，衆鸟各已归。","彼物皆有託，吾生独無依。","对此石上月，长醉歌芳菲。"]', '诗', 'shi', '', NULL, '春日獨酌二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f398c63-d380-43c4-8881-38e0a0e8c760', '春日獨酌二首 二', '春日独酌二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我有紫霞想，緬懷滄洲間。","思對一壺酒，澹然萬事閑。","橫琴倚高松，把酒望遠山。","長空去鳥沒，落日孤雲還。","但恐光景晚，宿昔成秋顏。"]', '["我有紫霞想，緬懷滄洲间。","思对一壺酒，澹然万事闲。","橫琴倚高松，把酒望远山。","长空去鸟沒，落日孤云還。","但恐光景晚，宿昔成秋顏。"]', '诗', 'shi', '', NULL, '春日獨酌二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8590a5b-dffc-499f-b09c-b670c0ddd417', '金陵江上遇蓬池隱者', '金陵江上遇蓬池隐者', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["心愛名山遊，身隨名山遠。","羅浮麻姑臺，此去或未返。","遇君蓬池隱，就我石上飯。","空言不成歡，強笑惜日晚。","綠水向雁門，黃雲蔽龍山。","歎息兩客鳥，裴回吳越間。","共語一執手，留連夜將久。","解我紫綺裘，且換金陵酒。","酒來笑復歌，興酣樂事多。","水影弄月色，清光奈愁何。","明晨挂帆席，離恨滿滄波。"]', '["心愛名山游，身隨名山远。","羅浮麻姑台，此去或未返。","遇君蓬池隐，就我石上飯。","空言不成歡，強笑惜日晚。","綠水向雁门，黄云蔽龙山。","歎息兩客鸟，裴回吳越间。","共語一執手，留連夜將久。","解我紫綺裘，且換金陵酒。","酒来笑复歌，兴酣乐事多。","水影弄月色，清光奈愁何。","明晨挂帆席，離恨满滄波。"]', '诗', 'shi', '', NULL, '金陵江上遇蓬池隱者 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe631cf2-b06a-45d1-8386-8cb7d1a45fdd', '月夜聽盧子順彈琴', '月夜听盧子順彈琴', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["閑坐夜明月，幽人彈素琴。","忽聞悲風調，宛若寒松吟。","白雪亂纖手，綠水清虛心。","鍾期久已沒，世上無知音。"]', '["闲坐夜明月，幽人彈素琴。","忽闻悲风調，宛若寒松吟。","白雪亂纖手，綠水清虛心。","鍾期久已沒，世上無知音。"]', '诗', 'shi', '', NULL, '月夜聽盧子順彈琴 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c735c91-2bc5-4cfb-a245-f732723ea3cb', '清溪半夜聞笛', '清溪半夜闻笛', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["羗笛梅花引，吳溪隴水情。","寒山秋浦月，腸斷玉關聲。"]', '["羗笛梅花引，吳溪隴水情。","寒山秋浦月，腸斷玉关声。"]', '诗', 'shi', '', NULL, '清溪半夜聞笛 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7765f83-8373-46f3-9705-8625158a0219', '日夕山中忽然有懷', '日夕山中忽然有懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["久臥青山雲，遂爲青山客。","山深雲更好，賞弄終日夕。","月銜樓間峰，泉潄階下石。","素心自此得，真趣非外惜。","鼯啼桂方秋，風滅籟歸寂。","緬思洪厓術，欲往滄海隔。","雲車來何遲，撫几空歎息。"]', '["久臥青山云，遂爲青山客。","山深云更好，賞弄終日夕。","月銜楼间峰，泉潄階下石。","素心自此得，真趣非外惜。","鼯啼桂方秋，风滅籟归寂。","緬思洪厓術，欲往滄海隔。","云车来何遲，撫几空歎息。"]', '诗', 'shi', '', NULL, '日夕山中忽然有懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e393f3-d0e4-41aa-95e0-2cdb17395c21', '夏日山中', '夏日山中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嬾搖白羽扇，躶體青林中。","脫巾挂石壁，露頂洒松風。"]', '["嬾搖白羽扇，躶體青林中。","脫巾挂石壁，露頂洒松风。"]', '诗', 'shi', '', NULL, '夏日山中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6a4a34d-2a6a-4b04-948f-bbc835e65771', '山中與幽人對酌', '山中與幽人对酌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["兩人對酌山花開，一杯一杯復一杯。","我醉欲眠卿且去，明朝有意抱琴來。"]', '["兩人对酌山花开，一杯一杯复一杯。","我醉欲眠卿且去，明朝有意抱琴来。"]', '诗', 'shi', '', NULL, '山中與幽人對酌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4da2f5-1603-4b17-a022-d088cfb2f8c6', '春日醉起言志', '春日醉起言志', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["處世若大夢，胡爲勞其生。","所以終日醉，頹然臥前楹。","覺來盼庭前，一鳥花間鳴。","借問此何時，春風語流鶯。","感之欲歎息，對酒還自傾。","浩歌待明月，曲盡已忘情。"]', '["处世若大梦，胡爲勞其生。","所以終日醉，頹然臥前楹。","覺来盼庭前，一鸟花间鳴。","借问此何时，春风語流鶯。","感之欲歎息，对酒還自傾。","浩歌待明月，曲尽已忘情。"]', '诗', 'shi', '', NULL, '春日醉起言志 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d81ca96f-dd8d-45d2-9807-a4a8866ce8ad', '廬山東林寺夜懷', '廬山东林寺夜懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我尋青蓮宇，獨往謝城闕。","霜清東林鐘，水白虎溪月。","天香生虛空，天樂鳴不歇。","宴坐寂不動，大千入毫髮。","湛然冥真心，曠劫斷出沒。"]', '["我尋青蓮宇，独往謝城闕。","霜清东林鐘，水白虎溪月。","天香生虛空，天乐鳴不歇。","宴坐寂不动，大千入毫髮。","湛然冥真心，曠劫斷出沒。"]', '诗', 'shi', '', NULL, '廬山東林寺夜懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69261f5d-52cd-4de8-96ee-3b7d8c8dfa48', '尋雍尊師隱居', '尋雍尊師隐居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["羣峭碧摩天，逍遙不記年。","撥雲尋古道，倚石聽流泉。","花暖青牛臥，松高白鶴眠。","語來江色暮，獨自下寒烟。"]', '["羣峭碧摩天，逍遙不記年。","撥云尋古道，倚石听流泉。","花暖青牛臥，松高白鹤眠。","語来江色暮，独自下寒烟。"]', '诗', 'shi', '', NULL, '尋雍尊師隱居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d5cf185-31e4-4d49-9504-cbc1e9c12723', '與史郎中欽聽黃鶴樓上吹笛', '與史郎中欽听黄鹤楼上吹笛', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一爲遷客去長沙，西望長安不見家。","黃鶴樓中吹玉笛，江城五月落梅花。"]', '["一爲遷客去长沙，西望长安不见家。","黄鹤楼中吹玉笛，江城五月落梅花。"]', '诗', 'shi', '', NULL, '與史郎中欽聽黃鶴樓上吹笛 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e265f41f-3601-48eb-98a0-f1dddb07b9f9', '對酒', '对酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["勸君莫拒杯，春風笑人來。","桃李如舊識，傾花向我開。","流鶯啼碧樹，明月窺金罍。","昨日朱顏子，今日白髮催。","棘生石虎殿，鹿走姑蘇臺。","自古帝王宅，城闕閉黃埃。"]', '["勸君莫拒杯，春风笑人来。","桃李如旧識，傾花向我开。","流鶯啼碧樹，明月窺金罍。","昨日朱顏子，今日白髮催。","棘生石虎殿，鹿走姑蘇台。","自古帝王宅，城闕閉黄埃。"]', '诗', 'shi', '', NULL, '對酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b463c627-1cfa-478a-a454-a4416ada0591', '醉題王漢陽廳', '醉題王漢陽廳', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我似鷓鴣鳥，南遷嬾北飛。","時尋漢陽令，取醉月中歸。"]', '["我似鷓鴣鸟，南遷嬾北飞。","时尋漢陽令，取醉月中归。"]', '诗', 'shi', '', NULL, '醉題王漢陽廳 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df40c153-838f-47d8-a895-99c81fe62845', '嘲王歷陽不肯飲酒', '嘲王歷陽不肯饮酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["地白風色寒，雪花大如手。","笑殺陶淵明，不飲杯中酒。","浪撫一張琴，虛栽五株柳。","空負頭上巾，吾於爾何有。"]', '["地白风色寒，雪花大如手。","笑殺陶淵明，不饮杯中酒。","浪撫一張琴，虛栽五株柳。","空負头上巾，吾於爾何有。"]', '诗', 'shi', '', NULL, '嘲王歷陽不肯飲酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2005d82-8986-400f-9f8f-650d6f734a61', '獨坐敬亭山', '独坐敬亭山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["衆鳥高飛盡，孤雲獨去閑。","相看兩不厭，只有敬亭山。"]', '["衆鸟高飞尽，孤云独去闲。","相看兩不厭，只有敬亭山。"]', '诗', 'shi', '', NULL, '獨坐敬亭山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0216beca-aac2-410f-baa4-1007ed7ebafe', '自遣', '自遣', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["對酒不覺暝，落花盈我衣。","醉起步溪月，鳥還人亦稀。"]', '["对酒不覺暝，落花盈我衣。","醉起步溪月，鸟還人亦稀。"]', '诗', 'shi', '', NULL, '自遣 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bdf02de-ac34-4528-a267-ab6b0becb32a', '訪戴天山道士不遇', '訪戴天山道士不遇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["犬吠水聲中，桃花帶雨濃。","樹深時見鹿，溪午不聞鐘。","野竹分青靄，飛泉挂碧峰。","無人知所去，愁倚兩三松。"]', '["犬吠水声中，桃花带雨濃。","樹深时见鹿，溪午不闻鐘。","野竹分青靄，飞泉挂碧峰。","無人知所去，愁倚兩三松。"]', '诗', 'shi', '', NULL, '訪戴天山道士不遇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a909399-c6d6-4a5b-9d87-dd56052c6d1e', '秋日與張少府楚城韋公藏書高齋作', '秋日與張少府楚城韋公藏书高斋作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日下空庭暮，城荒古跡餘。","地形連海盡，天影落江虛。","舊賞人雖隔，新知樂未疎。","彩雲思作賦，丹壁間藏書。","楂擁隨流葉，萍開出水魚。","夕來秋興滿，回首意何如。"]', '["日下空庭暮，城荒古跡餘。","地形連海尽，天影落江虛。","旧賞人雖隔，新知乐未疎。","彩云思作賦，丹壁间藏书。","楂擁隨流葉，萍开出水鱼。","夕来秋兴满，回首意何如。"]', '诗', 'shi', '', NULL, '秋日與張少府楚城韋公藏書高齋作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30402058-21b4-4dae-be09-03b26433360c', '秋夜獨坐懷故山', '秋夜独坐懷故山', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["小隱慕安石，遠遊學屈平。","天書訪江海，雲臥起咸京。","入侍瑤池宴，出陪玉輦行。","誇胡新賦作，諫獵短書成。","但奉紫霄顧，非邀青史名。","莊周空說劒，墨翟耻論兵。","拙薄遂疎絕，歸閑事耦耕。","顧無蒼生望，空愛紫芝榮。","寥落暝霞色，微茫舊壑情。","秋山綠蘿月，今夕爲誰明。"]', '["小隐慕安石，远游学屈平。","天书訪江海，云臥起咸京。","入侍瑤池宴，出陪玉輦行。","誇胡新賦作，諫獵短书成。","但奉紫霄顧，非邀青史名。","莊周空说劒，墨翟耻論兵。","拙薄遂疎絕，归闲事耦耕。","顧無蒼生望，空愛紫芝榮。","寥落暝霞色，微茫旧壑情。","秋山綠蘿月，今夕爲誰明。"]', '诗', 'shi', '', NULL, '秋夜獨坐懷故山 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87762e0a-6022-4d29-a8f6-f4d1a404a10c', '憶崔郎中宗之遊南陽遺吾孔子琴撫之潸然感舊', '憶崔郎中宗之游南陽遺吾孔子琴撫之潸然感旧', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔在南陽城，唯餐獨山蕨。","憶與崔宗之，白水弄素月。","時過菊潭上，縱酒無休歇。","泛此黃金花，頹然清歌發。","一朝摧玉樹，生死殊飄忽。","留我孔子琴，琴存人已歿。","誰傳廣陵散，但哭邙山骨。","泉戶何時明，長掃狐兔窟。"]', '["昔在南陽城，唯餐独山蕨。","憶與崔宗之，白水弄素月。","时過菊潭上，縱酒無休歇。","泛此黄金花，頹然清歌發。","一朝摧玉樹，生死殊飄忽。","留我孔子琴，琴存人已歿。","誰傳廣陵散，但哭邙山骨。","泉戶何时明，长掃狐兔窟。"]', '诗', 'shi', '', NULL, '憶崔郎中宗之遊南陽遺吾孔子琴撫之潸然感舊 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0f4e0d-6ad0-4915-ab11-2a4a5901d1ed', '憶東山二首 一', '憶东山二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["不向東山久，薔薇幾度花。","白雲還自散，明月落誰家。"]', '["不向东山久，薔薇幾度花。","白云還自散，明月落誰家。"]', '诗', 'shi', '', NULL, '憶東山二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81275210-59eb-4102-b949-e9de1de6de97', '憶東山二首 二', '憶东山二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我今攜謝妓，長嘯絕人羣。","欲報東山客，開關掃白雲。"]', '["我今携謝妓，长嘯絕人羣。","欲報东山客，开关掃白云。"]', '诗', 'shi', '', NULL, '憶東山二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3699d9ca-9851-4a75-9caf-61b28f14f8f6', '望月有懷', '望月有懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清泉暎疎松，不知幾千古。","寒月搖清波，流光入窗戶。","對此空長吟，思君意何深。","無因見安道，興盡愁人心。"]', '["清泉暎疎松，不知幾千古。","寒月搖清波，流光入窗戶。","对此空长吟，思君意何深。","無因见安道，兴尽愁人心。"]', '诗', 'shi', '', NULL, '望月有懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a4fb2d0-a124-43b0-bb86-cf8347143eaa', '對酒憶賀監二首 一', '对酒憶賀監二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["四明有狂客，風流賀季真。","長安一相見，呼我謫仙人。","昔好杯中物，翻爲松下塵。","金龜換酒處，却憶淚沾巾。"]', '["四明有狂客，风流賀季真。","长安一相见，呼我謫仙人。","昔好杯中物，翻爲松下塵。","金龟換酒处，却憶泪沾巾。"]', '诗', 'shi', '', NULL, '對酒憶賀監二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a2f723d-6216-4c10-b2e0-215598dfdc75', '對酒憶賀監二首 二', '对酒憶賀監二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["狂客歸四明，山陰道士迎。","敕賜鏡湖水，爲君臺沼榮。","人亡餘故宅，空有荷花生。","念此杳如夢，淒然傷我情。"]', '["狂客归四明，山陰道士迎。","敕賜镜湖水，爲君台沼榮。","人亡餘故宅，空有荷花生。","念此杳如梦，淒然傷我情。"]', '诗', 'shi', '', NULL, '對酒憶賀監二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df4e423-90f2-48b6-b050-5aae6a097a3d', '重憶一首', '重憶一首', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["欲向江東去，定將誰舉杯。","稽山無賀老，却櫂酒船回。"]', '["欲向江东去，定將誰舉杯。","稽山無賀老，却櫂酒船回。"]', '诗', 'shi', '', NULL, '重憶一首 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ff52da-f3e6-4b96-9aa2-2f173e2113fd', '春滯沅湘有懷山中', '春滯沅湘有懷山中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["沅湘春色還，風暖烟草綠。","古之傷心人，於此腸斷續。","予非懷沙客，但美採菱曲。","所願歸東山，寸心於此足。"]', '["沅湘春色還，风暖烟草綠。","古之傷心人，於此腸斷續。","予非懷沙客，但美採菱曲。","所願归东山，寸心於此足。"]', '诗', 'shi', '', NULL, '春滯沅湘有懷山中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e582e6-4e11-4710-91cf-82e2c6aa5fda', '落日憶山中', '落日憶山中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雨後烟景綠，晴天散餘霞。","東風隨春歸，發我枝上花。","花落時欲暮，見此令人嗟。","願遊名山去，學道飛丹砂。"]', '["雨後烟景綠，晴天散餘霞。","东风隨春归，發我枝上花。","花落时欲暮，见此令人嗟。","願游名山去，学道飞丹砂。"]', '诗', 'shi', '', NULL, '落日憶山中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80498ffd-7631-427a-ba29-b8bbf1d578dd', '憶秋浦桃花舊遊時竄夜郎', '憶秋浦桃花旧游时竄夜郎', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桃花春水生，白石今出沒。","搖蕩女蘿枝，半搖青天月。","不知舊行徑，初拳幾枝蕨。","三載夜郎還，於茲鍊金骨。"]', '["桃花春水生，白石今出沒。","搖蕩女蘿枝，半搖青天月。","不知旧行徑，初拳幾枝蕨。","三載夜郎還，於茲鍊金骨。"]', '诗', 'shi', '', NULL, '憶秋浦桃花舊遊時竄夜郎 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e520730-d319-4bb4-8253-36e8d5fcc6c1', '越中秋懷', '越中秋懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["越水遶碧山，周迴數千里。","乃是天鏡中，分明畫相似。","愛此從冥搜，永懷臨湍遊。","一爲滄波客，十見紅蕖秋。","觀濤壯天險，望海令人愁。","路遐迫西照，歲晚悲東流。","何必探禹穴，逝將歸蓬丘。","不然五湖上，亦可乘扁舟。"]', '["越水遶碧山，周迴數千里。","乃是天镜中，分明畫相似。","愛此從冥搜，永懷臨湍游。","一爲滄波客，十见紅蕖秋。","观濤壯天險，望海令人愁。","路遐迫西照，歲晚悲东流。","何必探禹穴，逝將归蓬丘。","不然五湖上，亦可乘扁舟。"]', '诗', 'shi', '', NULL, '越中秋懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb782de-e796-4888-9fe2-58b20ba83c4a', '效古二首 一', '效古二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝入天苑中，謁帝蓬萊宮。","青山映輦道，碧樹搖蒼空。","謬題金閨籍，得與銀臺通。","待詔奉明主，抽毫頌清風。","歸時落日晚，躞蹀浮雲驄。","人馬本無意，飛馳自豪雄。","入門紫鴛鴦，金井雙梧桐。","清歌弦古曲，美酒沽新豐。","快意且爲樂，列筵坐羣公。","光景不可留，生世如轉蓬。","早達勝晚遇，羞比垂釣翁。"]', '["朝入天苑中，謁帝蓬萊宮。","青山映輦道，碧樹搖蒼空。","謬題金閨籍，得與銀台通。","待詔奉明主，抽毫頌清风。","归时落日晚，躞蹀浮云驄。","人马本無意，飞驰自豪雄。","入门紫鴛鴦，金井雙梧桐。","清歌弦古曲，美酒沽新豐。","快意且爲乐，列筵坐羣公。","光景不可留，生世如轉蓬。","早達勝晚遇，羞比垂釣翁。"]', '诗', 'shi', '', NULL, '效古二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('543d61de-90af-48e8-9daf-80ee24e7bfa2', '效古二首 二', '效古二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["自古有秀色，西施與東鄰。","蛾眉不可妬，況乃效其矉。","所以尹婕妤，羞見邢夫人。","低頭不出氣，塞默少精神。","寄語無鹽子，如君何足珍。"]', '["自古有秀色，西施與东鄰。","蛾眉不可妬，況乃效其矉。","所以尹婕妤，羞见邢夫人。","低头不出氣，塞默少精神。","寄語無鹽子，如君何足珍。"]', '诗', 'shi', '', NULL, '效古二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6f963af-2b31-4a18-9e01-a7b37e6e6f13', '擬古十二首 一', '擬古十二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青天何歷歷，明星如白石。","黃姑與織女，相去不盈尺。","銀河無鵲橋，非時將安適。","閨人理紈素，遊子悲行役。","瓶冰知冬寒，霜露欺遠客。","客似秋葉飛，飄颻不言歸。","別後羅帶長，愁寬去時衣。","乘月託宵夢，因之寄金徽。"]', '["青天何歷歷，明星如白石。","黄姑與织女，相去不盈尺。","銀河無鵲橋，非时將安適。","閨人理紈素，游子悲行役。","瓶冰知冬寒，霜露欺远客。","客似秋葉飞，飄颻不言归。","別後羅带长，愁寬去时衣。","乘月託宵梦，因之寄金徽。"]', '诗', 'shi', '', NULL, '擬古十二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35bc02da-b239-4e22-8232-12fe88e62375', '擬古十二首 二', '擬古十二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["高樓入青天，下有白玉堂。","明月看欲墮，當窗懸清光。","遙夜一美人，羅衣霑秋霜。","含情弄柔瑟，彈作陌上桑。","弦聲何激烈，風捲遶飛梁。","行人皆躑躅，栖鳥起迴翔。","但寫妾意苦，莫辭此曲傷。","願逢同心者，飛作紫鴛鴦。"]', '["高楼入青天，下有白玉堂。","明月看欲墮，當窗懸清光。","遙夜一美人，羅衣霑秋霜。","含情弄柔瑟，彈作陌上桑。","弦声何激烈，风捲遶飞梁。","行人皆躑躅，栖鸟起迴翔。","但寫妾意苦，莫辞此曲傷。","願逢同心者，飞作紫鴛鴦。"]', '诗', 'shi', '', NULL, '擬古十二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4f40444-de50-40a2-8786-64cc1949cbe2', '擬古十二首 三', '擬古十二首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長繩難繫日，自古共悲辛。","黃金高北斗，不惜買陽春。","石火無留光，還如世中人。","即事已如夢，後來我誰身。","提壺莫辭貧，取酒會四鄰。","仙人殊恍惚，未若醉中真。"]', '["长繩难繫日，自古共悲辛。","黄金高北斗，不惜買陽春。","石火無留光，還如世中人。","即事已如梦，後来我誰身。","提壺莫辞貧，取酒會四鄰。","仙人殊恍惚，未若醉中真。"]', '诗', 'shi', '', NULL, '擬古十二首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbc70889-352b-4356-aaec-0873cf945705', '擬古十二首 四', '擬古十二首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清都綠玉樹，灼爍瑤臺春。","攀花弄秀色，遠贈天仙人。","香風送紫蘂，直到扶桑津。","取掇世上豔，所貴心之珍。","相思傳一笑，聊欲示情親。"]', '["清都綠玉樹，灼爍瑤台春。","攀花弄秀色，远贈天仙人。","香风送紫蘂，直到扶桑津。","取掇世上豔，所貴心之珍。","相思傳一笑，聊欲示情親。"]', '诗', 'shi', '', NULL, '擬古十二首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e25cdf4-a9de-469b-a196-39cfa9a1719a', '擬古十二首 五', '擬古十二首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["今日風日好，明日恐不如。","春風笑於人，何乃愁自居。","吹簫舞彩鳳，酌醴鱠神魚。","千金買一醉，取樂不求餘。","達士遺天地，東門有二疏。","愚夫同瓦石，有才知卷舒。","無事作悲苦，塊然涸轍魚。"]', '["今日风日好，明日恐不如。","春风笑於人，何乃愁自居。","吹簫舞彩鳳，酌醴鱠神鱼。","千金買一醉，取乐不求餘。","達士遺天地，东门有二疏。","愚夫同瓦石，有才知卷舒。","無事作悲苦，塊然涸轍鱼。"]', '诗', 'shi', '', NULL, '擬古十二首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('395f8c38-26db-4220-9fb7-33b755faa04e', '擬古十二首 六', '擬古十二首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["運速天地閉，胡風結飛霜。","百草死冬月，六龍頹西荒。","太白出東方，彗星揚精光。","鴛鴦非越鳥，何爲眷南翔。","惟昔鷹將犬，今爲侯與王。","得水成蛟龍，爭池奪鳳凰。","北斗不酌酒，南箕空簸揚。"]', '["運速天地閉，胡风結飞霜。","百草死冬月，六龙頹西荒。","太白出东方，彗星揚精光。","鴛鴦非越鸟，何爲眷南翔。","惟昔鷹將犬，今爲侯與王。","得水成蛟龙，爭池奪鳳凰。","北斗不酌酒，南箕空簸揚。"]', '诗', 'shi', '', NULL, '擬古十二首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a74c0025-6e9a-4b31-8606-fee3784e0e34', '擬古十二首 七', '擬古十二首 七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["世路今太行，迴車竟何託。","萬族皆凋枯，遂無少可樂。","曠野多白骨，幽魂共銷鑠。","榮貴當及時，春華宜照灼。","人非崑山玉，安得長璀錯。","身沒期不朽，榮名在麟閣。"]', '["世路今太行，迴车竟何託。","万族皆凋枯，遂無少可乐。","曠野多白骨，幽魂共銷鑠。","榮貴當及时，春华宜照灼。","人非崑山玉，安得长璀錯。","身沒期不朽，榮名在麟閣。"]', '诗', 'shi', '', NULL, '擬古十二首 七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35aedc22-3117-4065-b6da-d988d8e03fa8', '擬古十二首 八', '擬古十二首 八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月色不可掃，客愁不可道。","玉露生秋衣，流螢飛百草。","日月終銷毀，天地同枯槁。","蟪蛄啼青松，安見此樹老。","金丹寧誤俗，昧者難精討。","爾非千歲翁，多恨去世早。","飲酒入玉壺，藏身以爲寶。"]', '["月色不可掃，客愁不可道。","玉露生秋衣，流螢飞百草。","日月終銷毀，天地同枯槁。","蟪蛄啼青松，安见此樹老。","金丹寧誤俗，昧者难精討。","爾非千歲翁，多恨去世早。","饮酒入玉壺，藏身以爲寶。"]', '诗', 'shi', '', NULL, '擬古十二首 八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9205b1b-6ac3-4b28-8843-3432bd6c7afe', '擬古十二首 九', '擬古十二首 九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["生者爲過客，死者爲歸人。","天地一逆旅，同悲萬古塵。","月兔空搗藥，扶桑已成薪。","白骨寂無言，青松豈知春。","前後更嘆息，浮榮安足珍。"]', '["生者爲過客，死者爲归人。","天地一逆旅，同悲万古塵。","月兔空捣藥，扶桑已成薪。","白骨寂無言，青松豈知春。","前後更嘆息，浮榮安足珍。"]', '诗', 'shi', '', NULL, '擬古十二首 九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527d85ce-3391-4ada-91ca-55578dac99e6', '擬古十二首 十', '擬古十二首 十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["仙人騎彩鳳，昨下閬風岑。","海水三清淺，桃源一見尋。","遺我綠玉桮，兼之紫瓊琴。","杯以傾美酒，琴以閑素心。","二物非世有，何論珠與金。","琴彈松裏風，桮勸天上月。","風月長相知，世人何倏忽。"]', '["仙人騎彩鳳，昨下閬风岑。","海水三清淺，桃源一见尋。","遺我綠玉桮，兼之紫瓊琴。","杯以傾美酒，琴以闲素心。","二物非世有，何論珠與金。","琴彈松裏风，桮勸天上月。","风月长相知，世人何倏忽。"]', '诗', 'shi', '', NULL, '擬古十二首 十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b8a6d32-ff98-425f-b75f-d8255b3e79ac', '擬古十二首 十一', '擬古十二首 十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["涉江弄秋水，愛此荷花鮮。","攀荷弄其珠，蕩漾不成圓。","佳人綵雲裏，欲贈隔遠天。","相思無由見，悵望涼風前。"]', '["涉江弄秋水，愛此荷花鲜。","攀荷弄其珠，蕩漾不成圓。","佳人綵云裏，欲贈隔远天。","相思無由见，悵望涼风前。"]', '诗', 'shi', '', NULL, '擬古十二首 十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db29d61-2168-4b47-9e7e-a9e812d9df1d', '擬古十二首 十二', '擬古十二首 十二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["去去復去去，辭君還憶君。","漢水既殊流，楚山亦此分。","人生難稱意，豈得長爲羣。","越燕喜海日，燕鴻思朔雲。","別久容華晚，琅玕不能飯。","日落知天昏，夢長覺道遠。","望夫登高山，化石竟不返。"]', '["去去复去去，辞君還憶君。","漢水既殊流，楚山亦此分。","人生难稱意，豈得长爲羣。","越燕喜海日，燕鴻思朔云。","別久容华晚，琅玕不能飯。","日落知天昏，梦长覺道远。","望夫登高山，化石竟不返。"]', '诗', 'shi', '', NULL, '擬古十二首 十二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f47b763f-9870-4c3b-8b19-00cee343bf46', '感興六首 一', '感兴六首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["瑤姬天帝女，精彩化朝雲。","宛轉入宵夢，無心向楚君。","錦衾抱秋月，綺席空蘭芬。","茫昧竟誰測，虛傳宋玉文。"]', '["瑤姬天帝女，精彩化朝云。","宛轉入宵梦，無心向楚君。","錦衾抱秋月，綺席空蘭芬。","茫昧竟誰測，虛傳宋玉文。"]', '诗', 'shi', '', NULL, '感興六首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21c858a3-6eba-43a7-b110-47e716220227', '感興六首 二', '感兴六首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["洛浦有宓妃，飄颻雪爭飛。","輕雲拂素月，了可見清輝。","解珮欲西去，含情詎相違。","香塵動羅襪，綠水不霑衣。","陳王徒作賦，神女豈同歸。","好色傷大雅，多爲世所譏。"]', '["洛浦有宓妃，飄颻雪爭飞。","轻云拂素月，了可见清輝。","解珮欲西去，含情詎相違。","香塵动羅襪，綠水不霑衣。","陳王徒作賦，神女豈同归。","好色傷大雅，多爲世所譏。"]', '诗', 'shi', '', NULL, '感興六首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3131783-37d0-4609-880c-8175f542c02b', '感興六首 三', '感兴六首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["裂素持作書，將寄萬里懷。","眷眷待遠信，竟歲無人來。","征鴻務隨陽，又不爲我棲。","委之在深篋，蠹魚壞其題。","何如投水中，流落他人開。","不惜他人開，但恐生是非。"]', '["裂素持作书，將寄万里懷。","眷眷待远信，竟歲無人来。","征鴻務隨陽，又不爲我棲。","委之在深篋，蠹鱼壞其題。","何如投水中，流落他人开。","不惜他人开，但恐生是非。"]', '诗', 'shi', '', NULL, '感興六首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd431a0a-64d3-4b2e-85a7-ea8dcddde134', '感興六首 四', '感兴六首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["十五遊神仙，仙遊未曾歇。","吹笙坐松風，汎瑟窺海月。","西山玉童子，使我鍊金骨。","欲逐黃鶴飛，相呼向蓬闕。"]', '["十五游神仙，仙游未曾歇。","吹笙坐松风，汎瑟窺海月。","西山玉童子，使我鍊金骨。","欲逐黄鹤飞，相呼向蓬闕。"]', '诗', 'shi', '', NULL, '感興六首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c72e22e-815a-48c8-8cd8-4cf9dc32541b', '感興六首 五', '感兴六首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西國有美女，結樓青雲端。","蛾眉豔曉月，一笑傾城歡。","高節不可奪，炯心如凝丹。","常恐彩色晚，不爲人所觀。","安得配君子，共乘雙飛鸞。"]', '["西国有美女，結楼青云端。","蛾眉豔晓月，一笑傾城歡。","高節不可奪，炯心如凝丹。","常恐彩色晚，不爲人所观。","安得配君子，共乘雙飞鸾。"]', '诗', 'shi', '', NULL, '感興六首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaad4233-739e-4f93-9745-479d93307ec1', '感興六首 六', '感兴六首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嘉穀隱豐草，草深苗且稀。","農夫既不異，孤穗將安歸。","常恐委疇隴，忽與秋蓬飛。","烏得薦宗廟，爲君生光輝。"]', '["嘉穀隐豐草，草深苗且稀。","農夫既不異，孤穗將安归。","常恐委疇隴，忽與秋蓬飞。","烏得薦宗廟，爲君生光輝。"]', '诗', 'shi', '', NULL, '感興六首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f76a03-469c-4784-a5f4-258204d5004c', '寓言三首 一', '寓言三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["周公負斧扆，成王何夔夔。","武王昔不豫，剪爪投河湄。","賢聖遇讒慝，不免人君疑。","天風拔大木，禾黍咸傷萎。","管蔡扇蒼蠅，公賦鴟鴞詩。","金縢若不啓，忠信誰明之。"]', '["周公負斧扆，成王何夔夔。","武王昔不豫，剪爪投河湄。","賢聖遇讒慝，不免人君疑。","天风拔大木，禾黍咸傷萎。","管蔡扇蒼蠅，公賦鴟鴞诗。","金縢若不啓，忠信誰明之。"]', '诗', 'shi', '', NULL, '寓言三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41dcfe15-cf84-449d-93a5-4b676e67e4f2', '寓言三首 二', '寓言三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["搖裔雙彩鳳，婉孌三青禽。","往還瑤臺裏，鳴舞玉山岑。","以歡秦娥意，復得王母心。","區區精衛鳥，銜木空哀吟。"]', '["搖裔雙彩鳳，婉孌三青禽。","往還瑤台裏，鳴舞玉山岑。","以歡秦娥意，复得王母心。","區區精衛鸟，銜木空哀吟。"]', '诗', 'shi', '', NULL, '寓言三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed446759-2c64-4669-88a8-6d94032dc517', '寓言三首 三', '寓言三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長安春色歸，先入青門道。","綠楊不自持，從風欲傾倒。","海燕還秦宮，雙飛入簾櫳。","相思不相見，託夢遼城東。"]', '["长安春色归，先入青门道。","綠楊不自持，從风欲傾倒。","海燕還秦宮，雙飞入簾櫳。","相思不相见，託梦遼城东。"]', '诗', 'shi', '', NULL, '寓言三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17433d29-99c9-471e-9fca-431ac6eb3a51', '秋夕旅懷', '秋夕旅懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["涼風度秋海，吹我鄉思飛。","連山去無際，流水何時歸。","目極浮雲色，心斷明月暉。","芳草歇柔豔，白露催寒衣。","夢長銀漢落，覺罷天星稀。","含悲想舊國，泣下誰能揮。"]', '["涼风度秋海，吹我乡思飞。","連山去無際，流水何时归。","目極浮云色，心斷明月暉。","芳草歇柔豔，白露催寒衣。","梦长銀漢落，覺罷天星稀。","含悲想旧国，泣下誰能揮。"]', '诗', 'shi', '', NULL, '秋夕旅懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79bf081b-3ce2-4d11-af56-82934b5828d7', '感遇四首 一', '感遇四首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾愛王子晉，得道伊洛濱。","金骨既不毀，玉顏長自春。","可憐浮丘公，猗靡與情親。","舉首白日間，分明謝時人。","二仙去已遠，夢想空殷勤。"]', '["吾愛王子晉，得道伊洛濱。","金骨既不毀，玉顏长自春。","可怜浮丘公，猗靡與情親。","舉首白日间，分明謝时人。","二仙去已远，梦想空殷勤。"]', '诗', 'shi', '', NULL, '感遇四首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa629fb-81b1-436f-83dd-13e359bb7ba2', '感遇四首 二', '感遇四首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["可歎東籬菊，莖疎葉且微。","雖言異蘭蕙，亦自有芳菲。","未泛盈樽酒，徒霑清露輝。","當榮君不採，飄落欲何依。"]', '["可歎东籬菊，莖疎葉且微。","雖言異蘭蕙，亦自有芳菲。","未泛盈樽酒，徒霑清露輝。","當榮君不採，飄落欲何依。"]', '诗', 'shi', '', NULL, '感遇四首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2200e99e-cc15-42b2-9161-efcc9950063c', '感遇四首 三', '感遇四首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔余聞姮娥，竊藥駐雲髮。","不自嬌玉顏，方希鍊金骨。","飛去身莫返，含笑坐明月。","紫宮誇蛾眉，隨手會凋歇。"]', '["昔余闻姮娥，竊藥駐云髮。","不自嬌玉顏，方希鍊金骨。","飞去身莫返，含笑坐明月。","紫宮誇蛾眉，隨手會凋歇。"]', '诗', 'shi', '', NULL, '感遇四首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df05d26-7a31-46ac-a746-1610d0eeed41', '感遇四首 四', '感遇四首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["宋玉事楚王，立身本高潔。","巫山賦綵雲，郢路歌白雪。","舉國莫能和，巴人皆卷舌。","一感登徒言，恩情遂中絕。"]', '["宋玉事楚王，立身本高潔。","巫山賦綵云，郢路歌白雪。","舉国莫能和，巴人皆卷舌。","一感登徒言，恩情遂中絕。"]', '诗', 'shi', '', NULL, '感遇四首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('638f0fa8-cbb1-4652-9f75-a62cd7d31fd0', '翰林讀書言懷呈集賢諸學士', '翰林读书言懷呈集賢諸学士', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["晨趨紫禁中，夕待金門詔。","觀書散遺帙，探古窮至妙。","片言苟會心，掩卷忽而笑。","青蠅易相點，白雪難同調。","本是疎散人，屢貽褊促誚。","雲天屬清朗，林壑憶遊眺。","或時清風來，閑倚欄下嘯。","嚴光桐廬溪，謝客臨海嶠。","功成謝人間，從此一投釣。"]', '["晨趨紫禁中，夕待金门詔。","观书散遺帙，探古窮至妙。","片言苟會心，掩卷忽而笑。","青蠅易相点，白雪难同調。","本是疎散人，屢貽褊促誚。","云天屬清朗，林壑憶游眺。","或时清风来，闲倚欄下嘯。","嚴光桐廬溪，謝客臨海嶠。","功成謝人间，從此一投釣。"]', '诗', 'shi', '', NULL, '翰林讀書言懷呈集賢諸學士 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d156eb9-550b-4052-8cfd-cdeeb9c44c73', '尋陽紫極宮感秋作', '尋陽紫極宮感秋作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["何處聞秋聲，翛翛北窗竹。","迴薄萬古心，攬之不盈掬。","靜坐觀衆妙，浩然媚幽獨。","白雲南山來，就我檐下宿。","嬾從唐生決，羞訪季主卜。","四十九年非，一往不可復。","野情轉蕭灑，世道有飜覆。","陶令歸去來，田家酒應熟。"]', '["何处闻秋声，翛翛北窗竹。","迴薄万古心，攬之不盈掬。","静坐观衆妙，浩然媚幽独。","白云南山来，就我檐下宿。","嬾從唐生決，羞訪季主卜。","四十九年非，一往不可复。","野情轉蕭灑，世道有飜覆。","陶令归去来，田家酒應熟。"]', '诗', 'shi', '', NULL, '尋陽紫極宮感秋作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ffee7a6-2071-4926-97a8-f95d59a071ff', '江上秋懷', '江上秋懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["餐霞臥舊壑，散髮謝遠遊。","山蟬號枯桑，始復知天秋。","朔雁別海裔，越燕辭江樓。","颯颯風卷沙，茫茫霧縈洲。","黃雲結暮色，白水揚寒流。","惻愴心自悲，潺湲淚難收。","蘅蘭方蕭瑟，長嘆令人愁。"]', '["餐霞臥旧壑，散髮謝远游。","山蟬號枯桑，始复知天秋。","朔雁別海裔，越燕辞江楼。","颯颯风卷沙，茫茫霧縈洲。","黄云結暮色，白水揚寒流。","惻愴心自悲，潺湲泪难收。","蘅蘭方蕭瑟，长嘆令人愁。"]', '诗', 'shi', '', NULL, '江上秋懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eed4e2b-2f4d-421c-b637-e5589cfcd327', '秋夕書懷', '秋夕书懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["北風吹海鴈，南渡落寒聲。","感此瀟湘客，淒其流浪情。","海懷結滄洲，霞想遊赤城。","始探蓬壺事，旋覺天地輕。","澹然吟高秋，閑臥瞻太清。","蘿月掩空幕，松霜結前楹。","滅見息羣動，獵微窮至精。","桃花有源水，可以保吾生。"]', '["北风吹海鴈，南渡落寒声。","感此瀟湘客，淒其流浪情。","海懷結滄洲，霞想游赤城。","始探蓬壺事，旋覺天地轻。","澹然吟高秋，闲臥瞻太清。","蘿月掩空幕，松霜結前楹。","滅见息羣动，獵微窮至精。","桃花有源水，可以保吾生。"]', '诗', 'shi', '', NULL, '秋夕書懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5beaf48e-c727-4fba-8a4c-33629beb03e6', '避地司空原言懷', '避地司空原言懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["南風昔不競，豪聖思經綸。","劉琨與祖逖，起舞雞鳴晨。","雖有匡濟心，終爲樂禍人。","我則異於是，潛光皖水濱。","卜築司空原，北將天柱鄰。","雪霽萬里月，雲開九江春。","俟乎泰階平，然後託微身。","傾家事金鼎，年貌可長新。","所願得此道，終然保清真。","弄景奔日馭，攀星戲河津。","一隨王喬去，長年玉天賓。"]', '["南风昔不競，豪聖思經綸。","劉琨與祖逖，起舞雞鳴晨。","雖有匡濟心，終爲乐禍人。","我則異於是，潛光皖水濱。","卜築司空原，北將天柱鄰。","雪霽万里月，云开九江春。","俟乎泰階平，然後託微身。","傾家事金鼎，年貌可长新。","所願得此道，終然保清真。","弄景奔日馭，攀星戲河津。","一隨王喬去，长年玉天賓。"]', '诗', 'shi', '', NULL, '避地司空原言懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f73734e0-155a-449c-b02c-aef8d40f548a', '上崔相百憂章', '上崔相百憂章', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["共公赫怒，天維中摧。","鯤鯨噴蕩，揚濤起雷。","魚龍陷人，成此禍胎。","火焚崑山，玉石相磓。","仰希霖雨，灑寶炎煨。","箭發石開，戈揮日迴。","鄒衍慟哭，燕霜颯來。","微誠不感，猶縶夏臺。","蒼鷹搏攫，丹棘崔嵬。","豪聖凋枯，王風傷哀。","斯文未喪，東嶽豈頹。","穆逃楚難，鄒脫吳災。","見機苦遲，二公所咍。","驥不驟進，麟何來哉。","星離一門，草擲二孩。","萬憤結習，憂從中催。","金瑟玉壺，盡爲愁媒。","舉酒太息，泣血盈桮。","台星再朗，天綱重恢。","屈法申恩，棄瑕取材。","冶長非罪，尼父無猜。","覆盆儻舉，應照寒灰。"]', '["共公赫怒，天維中摧。","鯤鯨噴蕩，揚濤起雷。","鱼龙陷人，成此禍胎。","火焚崑山，玉石相磓。","仰希霖雨，灑寶炎煨。","箭發石开，戈揮日迴。","鄒衍慟哭，燕霜颯来。","微誠不感，猶縶夏台。","蒼鷹搏攫，丹棘崔嵬。","豪聖凋枯，王风傷哀。","斯文未喪，东嶽豈頹。","穆逃楚难，鄒脫吳災。","见機苦遲，二公所咍。","驥不驟進，麟何来哉。","星離一门，草擲二孩。","万憤結習，憂從中催。","金瑟玉壺，尽爲愁媒。","舉酒太息，泣血盈桮。","台星再朗，天綱重恢。","屈法申恩，棄瑕取材。","冶长非罪，尼父無猜。","覆盆儻舉，應照寒灰。"]', '诗', 'shi', '', NULL, '上崔相百憂章 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8936accd-7c40-42ed-aa10-8eeb2ff76c58', '萬憤詞投魏郎中', '万憤词投魏郎中', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海水渤潏，人罹鯨鯢。","蓊胡沙而四塞，始滔天於燕齊。","何六龍之浩蕩，遷白日於秦西。","九土星分，嗷嗷棲棲。","南冠君子，呼天而啼。","戀高堂而掩泣，淚血地而成泥。","獄戶春而不草，獨幽怨而沈迷。","兄九江兮弟三峽，悲羽化之難齊。","穆陵關北愁愛子，豫章天南隔老妻。","一門骨肉散百草，遇難不復相提攜。","樹榛拔桂，囚鸞寵雞。","舜昔授禹，伯成耕犂。","德自此衰，吾將安棲。","好我者恤我，不好我者何忍臨危而相擠。","子胥鴟夷，彭越醢醯。","自古豪烈，胡爲此繄。","蒼蒼之天，高乎視低。","如其聽卑，脫我牢狴。","儻辨美玉，君收白珪。"]', '["海水渤潏，人罹鯨鯢。","蓊胡沙而四塞，始滔天於燕齊。","何六龙之浩蕩，遷白日於秦西。","九土星分，嗷嗷棲棲。","南冠君子，呼天而啼。","戀高堂而掩泣，泪血地而成泥。","獄戶春而不草，独幽怨而沈迷。","兄九江兮弟三峽，悲羽化之难齊。","穆陵关北愁愛子，豫章天南隔老妻。","一门骨肉散百草，遇难不复相提携。","樹榛拔桂，囚鸾寵雞。","舜昔授禹，伯成耕犂。","德自此衰，吾將安棲。","好我者恤我，不好我者何忍臨危而相擠。","子胥鴟夷，彭越醢醯。","自古豪烈，胡爲此繄。","蒼蒼之天，高乎視低。","如其听卑，脫我牢狴。","儻辨美玉，君收白珪。"]', '诗', 'shi', '', NULL, '萬憤詞投魏郎中 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f40d38b4-85f4-42cc-978d-da08bdca85fe', '荆州賊平臨洞庭言懷作', '荆州賊平臨洞庭言懷作', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["修蛇橫洞庭，吞象臨江島。","積骨成巴陵，遺言聞楚老。","水窮三苗國，地窄三湘道。","歲[晏]天崢嶸，時危人枯槁。","思歸阻喪亂，去國傷懷抱。","郢路方丘墟，章華亦傾倒。","風悲猨嘯苦，木落鴻飛早。","日隱西赤沙，月明東城草。","關河望已絕，氛霧行當掃。","長呌天可聞，吾將問蒼昊。"]', '["修蛇橫洞庭，吞象臨江島。","積骨成巴陵，遺言闻楚老。","水窮三苗国，地窄三湘道。","歲[晏]天崢嶸，时危人枯槁。","思归阻喪亂，去国傷懷抱。","郢路方丘墟，章华亦傾倒。","风悲猨嘯苦，木落鴻飞早。","日隐西赤沙，月明东城草。","关河望已絕，氛霧行當掃。","长呌天可闻，吾將问蒼昊。"]', '诗', 'shi', '', NULL, '荆州賊平臨洞庭言懷作 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('021b5e5d-ccb6-4e86-aff0-a6796bceeca1', '覽鏡書懷', '覽镜书懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["得道無古今，失道還衰老。","自笑鏡中人，白髮如霜草。","捫心空嘆息，問影何枯槁。","桃李竟何言，終成南山皓。"]', '["得道無古今，失道還衰老。","自笑镜中人，白髮如霜草。","捫心空嘆息，问影何枯槁。","桃李竟何言，終成南山皓。"]', '诗', 'shi', '', NULL, '覽鏡書懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d75235b-91c9-4e30-9500-df1989c5a0e7', '田園言懷', '田园言懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["賈誼三年謫，班超萬里侯。","何如牽白犢，飲水對清流。"]', '["賈誼三年謫，班超万里侯。","何如牽白犢，饮水对清流。"]', '诗', 'shi', '', NULL, '田園言懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ca7bc9-ed9d-4165-b8fb-e014d55696eb', '江南春懷', '江南春懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青春幾何時，黃鳥鳴不歇。","天涯失鄉路，江外老華髮。","心飛秦塞雲，影滯楚關月。","身世殊爛漫，田園久蕪沒。","歲[晏]何所從，長歌謝金闕。"]', '["青春幾何时，黄鸟鳴不歇。","天涯失乡路，江外老华髮。","心飞秦塞云，影滯楚关月。","身世殊爛漫，田园久蕪沒。","歲[晏]何所從，长歌謝金闕。"]', '诗', 'shi', '', NULL, '江南春懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71999aa1-55dd-4449-81b0-41f04686bf2e', '聽蜀僧濬彈琴', '听蜀僧濬彈琴', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蜀僧抱綠綺，西下峨眉峰。","爲我一揮手，如聽萬壑松。","客心洗流水，餘響入霜鐘。","不覺碧山暮，秋雲暗幾重。"]', '["蜀僧抱綠綺，西下峨眉峰。","爲我一揮手，如听万壑松。","客心洗流水，餘响入霜鐘。","不覺碧山暮，秋云暗幾重。"]', '诗', 'shi', '', NULL, '聽蜀僧濬彈琴 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe41dff-920c-48f6-9950-ee6dda12333e', '魯東門觀刈蒲', '魯东门观刈蒲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯國寒事早，初霜刈渚蒲。","揮鐮若轉月，拂水生連珠。","此草最可珍，何必貴龍鬚。","織作玉牀席，欣承清夜娛。","羅衣能再拂，不畏素塵蕪。"]', '["魯国寒事早，初霜刈渚蒲。","揮鐮若轉月，拂水生連珠。","此草最可珍，何必貴龙鬚。","织作玉牀席，欣承清夜娛。","羅衣能再拂，不畏素塵蕪。"]', '诗', 'shi', '', NULL, '魯東門觀刈蒲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45c9a460-8040-4c0c-aad2-336533d9de3d', '詠鄰女東窗海石榴', '詠鄰女东窗海石榴', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯女東窗下，海榴世所稀。","珊瑚映綠水，未足比光輝。","清香隨風發，落日好鳥歸。","願爲東南枝，低舉拂羅衣。","無由共攀折，引領望金扉。"]', '["魯女东窗下，海榴世所稀。","珊瑚映綠水，未足比光輝。","清香隨风發，落日好鸟归。","願爲东南枝，低舉拂羅衣。","無由共攀折，引領望金扉。"]', '诗', 'shi', '', NULL, '詠鄰女東窗海石榴 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('583eb6c2-5b43-493c-a49a-ee1d2e3542ac', '南軒松', '南軒松', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["南軒有孤松，柯葉自綿冪。","清風無閑時，瀟灑終日夕。","陰生古苔綠，色染秋烟碧。","何當凌雲霄，直上數千尺。"]', '["南軒有孤松，柯葉自綿冪。","清风無闲时，瀟灑終日夕。","陰生古苔綠，色染秋烟碧。","何當凌云霄，直上數千尺。"]', '诗', 'shi', '', NULL, '南軒松 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f35c9d-a609-430a-ac00-50a1d775c272', '詠山樽二首 一', '詠山樽二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蟠木不彫飾，且將斤斧疎。","樽成山岳勢，材是棟梁餘。","外與金罍並，中涵玉醴虛。","慙君垂拂拭，遂忝玳筵居。"]', '["蟠木不彫飾，且將斤斧疎。","樽成山岳勢，材是棟梁餘。","外與金罍並，中涵玉醴虛。","慙君垂拂拭，遂忝玳筵居。"]', '诗', 'shi', '', NULL, '詠山樽二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ae28d7-25cb-46e2-bbfb-c69947664602', '詠山樽二首 二', '詠山樽二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["擁腫寒山木，嵌空成酒樽。","愧無江海量，偃蹇在君門。"]', '["擁腫寒山木，嵌空成酒樽。","愧無江海量，偃蹇在君门。"]', '诗', 'shi', '', NULL, '詠山樽二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aab6852-8e9c-489f-879d-23cadee8b26e', '初出金門尋王侍御不遇詠壁上鸚鵡', '初出金门尋王侍御不遇詠壁上鸚鵡', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["落羽辭金殿，孤鳴咤繡衣。","能言終見棄，還向隴西飛。"]', '["落羽辞金殿，孤鳴咤繡衣。","能言終见棄，還向隴西飞。"]', '诗', 'shi', '', NULL, '初出金門尋王侍御不遇詠壁上鸚鵡 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6bf8732-b70d-4290-892e-2b5e19d1909f', '紫藤樹', '紫藤樹', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紫藤挂雲木，花蔓宜陽春。","密葉隱歌鳥，香風留美人。"]', '["紫藤挂云木，花蔓宜陽春。","密葉隐歌鸟，香风留美人。"]', '诗', 'shi', '', NULL, '紫藤樹 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33782dec-ab43-4b04-a83a-deb1c8eb2c94', '觀放白鷹二首 一', '观放白鷹二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["八月邊風高，胡鷹白錦毛。","孤飛一片雪，百里見秋毫。"]', '["八月邊风高，胡鷹白錦毛。","孤飞一片雪，百里见秋毫。"]', '诗', 'shi', '', NULL, '觀放白鷹二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08cd7925-03d4-4983-8cfc-e3780f20f55f', '觀放白鷹二首 二', '观放白鷹二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["寒冬十二月，蒼鷹八九毛。","寄言燕雀莫相啅，自有雲霄萬里高。"]', '["寒冬十二月，蒼鷹八九毛。","寄言燕雀莫相啅，自有云霄万里高。"]', '诗', 'shi', '', NULL, '觀放白鷹二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f90a353d-12fb-4949-aa2d-70e5246d132e', '觀博平王志安少府山水粉圖', '观博平王志安少府山水粉圖', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["粉壁爲空天，丹青狀江海。","遊雲不知歸，日見白鷗在。","博平真人王志安，沈吟至此願挂冠。","松溪石磴帶秋色，愁客思歸坐曉寒。"]', '["粉壁爲空天，丹青狀江海。","游云不知归，日见白鷗在。","博平真人王志安，沈吟至此願挂冠。","松溪石磴带秋色，愁客思归坐晓寒。"]', '诗', 'shi', '', NULL, '觀博平王志安少府山水粉圖 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867666e6-4d65-4122-b487-8103ab1e9035', '題雍丘崔明府丹竈', '題雍丘崔明府丹竈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["美人爲政本忘機，服藥求仙事不違。","葉縣已泥丹竈畢，瀛洲當伴赤松歸。","先師有訣神將助，大聖無心火自飛。","九轉但能生羽翼，雙鳧忽去定何依。"]', '["美人爲政本忘機，服藥求仙事不違。","葉縣已泥丹竈畢，瀛洲當伴赤松归。","先師有訣神將助，大聖無心火自飞。","九轉但能生羽翼，雙鳧忽去定何依。"]', '诗', 'shi', '', NULL, '題雍丘崔明府丹竈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff97e4cd-746e-455f-8419-d57e058c03ad', '觀元丹丘坐巫山屏風', '观元丹丘坐巫山屏风', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昔遊三峽見巫山，見畫巫山宛相似。","疑是天邊十二峰，飛入君家彩屏裏。","寒松蕭瑟如有聲，陽臺微茫如有情。","錦衾瑤席何寂寂，楚王神女徒盈盈。","高咫尺，如千里，翠屏丹崖燦如綺。","蒼蒼遠樹圍荆門，歷歷行舟泛巴水。","水石潺湲萬壑分，烟光草色俱氛氳。","溪花笑日何年發，江客聽猨幾歲聞。","使人對此心緬邈，疑入嵩丘夢綵雲。"]', '["昔游三峽见巫山，见畫巫山宛相似。","疑是天邊十二峰，飞入君家彩屏裏。","寒松蕭瑟如有声，陽台微茫如有情。","錦衾瑤席何寂寂，楚王神女徒盈盈。","高咫尺，如千里，翠屏丹崖燦如綺。","蒼蒼远樹圍荆门，歷歷行舟泛巴水。","水石潺湲万壑分，烟光草色俱氛氳。","溪花笑日何年發，江客听猨幾歲闻。","使人对此心緬邈，疑入嵩丘梦綵云。"]', '诗', 'shi', '', NULL, '觀元丹丘坐巫山屏風 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('710f07bb-942c-4408-aec1-6927f7b96126', '求崔山人百丈崖瀑布圖', '求崔山人百丈崖瀑布圖', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["百丈素崖裂，四山丹壁開。","龍潭中噴射，晝夜生風雷。","但見瀑泉落，如潨雲漢來。","聞君寫真圖，島嶼備縈迴。","石黛刷幽草，曾青澤古苔。","幽緘儻相傳，何必向天台。"]', '["百丈素崖裂，四山丹壁开。","龙潭中噴射，晝夜生风雷。","但见瀑泉落，如潨云漢来。","闻君寫真圖，島嶼備縈迴。","石黛刷幽草，曾青澤古苔。","幽緘儻相傳，何必向天台。"]', '诗', 'shi', '', NULL, '求崔山人百丈崖瀑布圖 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('072f32eb-bb78-4d53-acd9-fcbbccbc62ac', '見野草中有曰白頭翁者', '见野草中有曰白头翁者', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["醉入田家去，行歌荒野中。","如何青草裏，亦有白頭翁。","折取對明鏡，宛將衰鬢同。","微芳似相誚，留恨向東風。"]', '["醉入田家去，行歌荒野中。","如何青草裏，亦有白头翁。","折取对明镜，宛將衰鬢同。","微芳似相誚，留恨向东风。"]', '诗', 'shi', '', NULL, '見野草中有曰白頭翁者 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf2b6733-cda9-4704-ae90-a012fc05dade', '流夜郎題葵葉', '流夜郎題葵葉', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["慙君能衛足，嘆我遠移根。","白日如分照，還歸守故園。"]', '["慙君能衛足，嘆我远移根。","白日如分照，還归守故园。"]', '诗', 'shi', '', NULL, '流夜郎題葵葉 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccc5b149-cdce-4b5f-a4d4-4e0f31f200ea', '塋禪師房觀山海圖', '塋禪師房观山海圖', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["真僧閉精宇，滅跡含達觀。","列嶂圖雲山，攢峰入霄漢。","丹崖森在目，清晝疑卷幔。","蓬壺來軒窗，瀛海入几案。","煙濤爭噴薄，島嶼相凌亂。","征帆飄空中，瀑水灑天半。","崢嶸若可陟，想像徒盈嘆。","杳與真心冥，遂諧靜者翫。","如登赤城裏，揭步滄洲畔。","即事能娛人，從茲得消散。"]', '["真僧閉精宇，滅跡含達观。","列嶂圖云山，攢峰入霄漢。","丹崖森在目，清晝疑卷幔。","蓬壺来軒窗，瀛海入几案。","煙濤爭噴薄，島嶼相凌亂。","征帆飄空中，瀑水灑天半。","崢嶸若可陟，想像徒盈嘆。","杳與真心冥，遂諧静者翫。","如登赤城裏，揭步滄洲畔。","即事能娛人，從茲得消散。"]', '诗', 'shi', '', NULL, '塋禪師房觀山海圖 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8055ae5-be41-44f0-9148-fa5f27dd5d1d', '白鷺鶿', '白鷺鶿', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白鷺下秋水，孤飛如墜霜。","心閑且未去，獨立沙洲傍。"]', '["白鷺下秋水，孤飞如墜霜。","心闲且未去，独立沙洲傍。"]', '诗', 'shi', '', NULL, '白鷺鶿 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ff70288-0c55-419f-9e44-34fe40cce41e', '詠槿', '詠槿', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["園花笑芳年，池草豔春色。","猶不如槿花，嬋娟玉階側。","芬榮何夭促，零落在瞬息。","豈若瓊樹枝，終歲長翕赩。"]', '["园花笑芳年，池草豔春色。","猶不如槿花，嬋娟玉階側。","芬榮何夭促，零落在瞬息。","豈若瓊樹枝，終歲长翕赩。"]', '诗', 'shi', '', NULL, '詠槿 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('963bf805-633e-4fab-9029-1c379c9e71e9', '詠桂', '詠桂', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["世人種桃李，皆在金張門。","攀折爭捷徑，及此春風暄。","一朝天霜下，榮耀難久存。","安知南山桂，綠葉垂芳根。","清陰亦可託，何惜樹君園。"]', '["世人種桃李，皆在金張门。","攀折爭捷徑，及此春风暄。","一朝天霜下，榮耀难久存。","安知南山桂，綠葉垂芳根。","清陰亦可託，何惜樹君园。"]', '诗', 'shi', '', NULL, '詠桂 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('764f45de-ea78-4680-8930-b8dee0fba520', '白胡桃', '白胡桃', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紅羅袖裏分明見，白玉盤中看却無。","疑是老僧休念誦，腕前推下水晶珠。"]', '["紅羅袖裏分明见，白玉盤中看却無。","疑是老僧休念誦，腕前推下水晶珠。"]', '诗', 'shi', '', NULL, '白胡桃 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35af2a9a-f7c6-4372-8403-e7e6952703ed', '巫山枕障', '巫山枕障', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["巫山枕障畫高丘，白帝城邊樹色秋。","朝雲夜入無行處，巴水橫天更不流。"]', '["巫山枕障畫高丘，白帝城邊樹色秋。","朝云夜入無行处，巴水橫天更不流。"]', '诗', 'shi', '', NULL, '巫山枕障 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f5bf4b-22c5-46ec-90ed-93bb8ce8d1cf', '南奔書懷', '南奔书懷', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遙夜何漫漫，空歌白石爛。","甯戚未匡齊，陳平終佐漢。","攙搶掃河洛，直割鴻溝半。","歷數方未遷，雲雷屢多難。","天人秉旄鉞，虎竹光藩翰。","侍筆黃金臺，傳觴青玉案。","不因秋風起，自有思歸歎。","主將動讒疑，王師忽離叛。","自來白沙上，鼓譟丹陽岸。","賓御如浮雲，從風各消散。","舟中指可掬，城上骸爭爨。","草草出近關，行行昧前算。","南奔劇星火，北寇無涯畔。","顧乏七寶鞭，留連道傍翫。","太白夜食昴，長虹日中貫。","秦趙興天兵，茫茫九州亂。","感遇明主恩，頗高祖逖言。","過江誓流水，志在清中原。","拔劍擊前柱，悲歌難重論。"]', '["遙夜何漫漫，空歌白石爛。","甯戚未匡齊，陳平終佐漢。","攙搶掃河洛，直割鴻溝半。","歷數方未遷，云雷屢多难。","天人秉旄鉞，虎竹光藩翰。","侍笔黄金台，傳觴青玉案。","不因秋风起，自有思归歎。","主將动讒疑，王師忽離叛。","自来白沙上，鼓譟丹陽岸。","賓御如浮云，從风各消散。","舟中指可掬，城上骸爭爨。","草草出近关，行行昧前算。","南奔劇星火，北寇無涯畔。","顧乏七寶鞭，留連道傍翫。","太白夜食昴，长虹日中貫。","秦趙兴天兵，茫茫九州亂。","感遇明主恩，頗高祖逖言。","過江誓流水，志在清中原。","拔劍擊前柱，悲歌难重論。"]', '诗', 'shi', '', NULL, '南奔書懷 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1087aac3-dd31-4943-8fd4-d65979838af0', '題隨州紫陽先生壁', '題隨州紫陽先生壁', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["神農好長生，風俗久已成。","復聞紫陽客，早署丹臺名。","喘息餐妙氣，步虛吟真聲。","道與古仙合，心將元化幷。","樓疑出蓬海，鶴似飛玉京。","松雪窗外曉，池水階下明。","忽耽笙歌樂，頗失軒冕情。","終願惠金液，提攜凌太清。"]', '["神農好长生，风俗久已成。","复闻紫陽客，早署丹台名。","喘息餐妙氣，步虛吟真声。","道與古仙合，心將元化幷。","楼疑出蓬海，鹤似飞玉京。","松雪窗外晓，池水階下明。","忽耽笙歌乐，頗失軒冕情。","終願惠金液，提携凌太清。"]', '诗', 'shi', '', NULL, '題隨州紫陽先生壁 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('038c9285-f36b-41dc-85a6-c82fc531d5af', '題元丹丘山居', '題元丹丘山居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["故人棲東山，自愛丘壑美。","青春臥空林，白日猶不起。","松風清襟袖，石潭洗心耳。","羨君無紛喧，高枕碧霞裏。"]', '["故人棲东山，自愛丘壑美。","青春臥空林，白日猶不起。","松风清襟袖，石潭洗心耳。","羨君無紛喧，高枕碧霞裏。"]', '诗', 'shi', '', NULL, '題元丹丘山居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74334c08-0ddd-40f0-b34b-1689da32b1cf', '題元丹丘潁陽山居', '題元丹丘潁陽山居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["仙遊渡潁水，訪隱同元君。","忽遺蒼生望，獨與洪崖羣。","卜地初晦跡，興言且成文。","却顧北山斷，前瞻南嶺分。","遙通汝海月，不隔嵩丘雲。","之子合逸趣，而我欽清芬。","舉跡倚松石，談笑迷朝曛。","益願狎青鳥，拂衣棲江濆。"]', '["仙游渡潁水，訪隐同元君。","忽遺蒼生望，独與洪崖羣。","卜地初晦跡，兴言且成文。","却顧北山斷，前瞻南嶺分。","遙通汝海月，不隔嵩丘云。","之子合逸趣，而我欽清芬。","舉跡倚松石，談笑迷朝曛。","益願狎青鸟，拂衣棲江濆。"]', '诗', 'shi', '', NULL, '題元丹丘潁陽山居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad860d8f-eff5-4789-8897-879dea7b8d11', '題瓜州新河餞族叔舍人賁', '題瓜州新河餞族叔舍人賁', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["齊公鑿新河，萬古流不絕。","豐功利生人，天地同朽滅。","兩橋對雙閣，芳樹有行列。","愛此如甘棠，誰云敢攀折。","吳關倚此固，天險自茲設。","海水落斗門，湖平見沙汭。","我行送季父，弭櫂徒流悅。","楊花滿江來，疑是龍山雪。","惜此林下興，愴爲山陽別。","瞻望清路塵，歸來空寂滅。"]', '["齊公鑿新河，万古流不絕。","豐功利生人，天地同朽滅。","兩橋对雙閣，芳樹有行列。","愛此如甘棠，誰云敢攀折。","吳关倚此固，天險自茲設。","海水落斗门，湖平见沙汭。","我行送季父，弭櫂徒流悅。","楊花满江来，疑是龙山雪。","惜此林下兴，愴爲山陽別。","瞻望清路塵，归来空寂滅。"]', '诗', 'shi', '', NULL, '題瓜州新河餞族叔舍人賁 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aca73ac-71ff-414b-922c-c5d58c4fc17f', '洗脚亭', '洗脚亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白道向姑熟，洪亭臨道傍。","前有昔時井，下有五丈牀。","樵女洗素足，行人歇金裝。","西望白鷺洲，蘆花似朝霜。","送君此時去，回首淚成行。"]', '["白道向姑熟，洪亭臨道傍。","前有昔时井，下有五丈牀。","樵女洗素足，行人歇金裝。","西望白鷺洲，蘆花似朝霜。","送君此时去，回首泪成行。"]', '诗', 'shi', '', NULL, '洗脚亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b4ab666-f675-4484-a3de-6f2d6f6d6cff', '勞勞亭', '勞勞亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天下傷心處，勞勞送客亭。","春風知別苦，不遣柳條青。"]', '["天下傷心处，勞勞送客亭。","春风知別苦，不遣柳條青。"]', '诗', 'shi', '', NULL, '勞勞亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f29fbd12-b739-4b55-8ed3-51f42e2281e7', '題金陵王處士水亭', '題金陵王处士水亭', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["王子耽玄言，賢豪多在門。","好鵝尋道士，愛竹嘯名園。","樹色老荒苑，池光蕩華軒。","此堂見明月，更憶陸平原。","埽拭青玉簟，爲余置金尊。","醉罷欲歸去，花枝宿鳥喧。","何時復來此，再得洗囂煩。"]', '["王子耽玄言，賢豪多在门。","好鵝尋道士，愛竹嘯名园。","樹色老荒苑，池光蕩华軒。","此堂见明月，更憶陸平原。","埽拭青玉簟，爲余置金尊。","醉罷欲归去，花枝宿鸟喧。","何时复来此，再得洗囂煩。"]', '诗', 'shi', '', NULL, '題金陵王處士水亭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25b546c-88d0-4a92-9eb7-42f5f99d6160', '題嵩山逸人元丹丘山居', '題嵩山逸人元丹丘山居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["家本紫雲山，道風未淪落。","沈懷丹丘志，沖賞歸寂寞。","朅來遊閩荒，捫涉窮禹鑿。","夤緣泛潮海，偃蹇陟廬霍。","憑雷躡天窗，弄影憩霞閣。","且欣登眺美，頗愜隱淪諾。","三山曠幽期，四岳聊所託。","故人契嵩穎，高義炳丹雘。","滅跡遺紛囂，終言本峰壑。","自矜林湍好，不羨朝市樂。","偶與真意幷，頓覺世情薄。","爾能折芳桂，吾亦採蘭若。","拙妻好乘鸞，嬌女愛飛鶴。","提攜訪神仙，從此鍊金藥。"]', '["家本紫云山，道风未淪落。","沈懷丹丘志，沖賞归寂寞。","朅来游閩荒，捫涉窮禹鑿。","夤緣泛潮海，偃蹇陟廬霍。","憑雷躡天窗，弄影憩霞閣。","且欣登眺美，頗愜隐淪諾。","三山曠幽期，四岳聊所託。","故人契嵩穎，高義炳丹雘。","滅跡遺紛囂，終言本峰壑。","自矜林湍好，不羨朝市乐。","偶與真意幷，頓覺世情薄。","爾能折芳桂，吾亦採蘭若。","拙妻好乘鸾，嬌女愛飞鹤。","提携訪神仙，從此鍊金藥。"]', '诗', 'shi', '', NULL, '題嵩山逸人元丹丘山居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d8603cf-3b29-4816-86c4-00e46a3601c1', '題江夏修靜寺', '題江夏修静寺', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我家北海宅，作寺南江濱。","空庭無玉樹，高殿坐幽人。","書帶留青草，琴堂冪素塵。","平生種桃李，寂滅不成春。"]', '["我家北海宅，作寺南江濱。","空庭無玉樹，高殿坐幽人。","书带留青草，琴堂冪素塵。","平生種桃李，寂滅不成春。"]', '诗', 'shi', '', NULL, '題江夏修靜寺 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd948956-3b61-4faf-9a30-70ae35154f8e', '題宛溪館', '題宛溪館', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吾憐宛溪好，百尺照心明。","何謝新安水，千尋見底清。","白沙留月色，綠竹助秋聲。","却笑嚴湍上，于今獨擅名。"]', '["吾怜宛溪好，百尺照心明。","何謝新安水，千尋见底清。","白沙留月色，綠竹助秋声。","却笑嚴湍上，于今独擅名。"]', '诗', 'shi', '', NULL, '題宛溪館 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9aeda4e-b29a-48a7-b9c9-6ed24f940cca', '題東谿公幽居', '題东谿公幽居', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["杜陵賢人清且廉，東溪卜築歲將淹。","宅近青山同謝朓，門垂碧柳似陶潛。","好鳥迎春歌後院，飛花送酒舞前簷。","客到但知留一醉，盤中秪有水晶鹽。"]', '["杜陵賢人清且廉，东溪卜築歲將淹。","宅近青山同謝朓，门垂碧柳似陶潛。","好鸟迎春歌後院，飞花送酒舞前簷。","客到但知留一醉，盤中秪有水晶鹽。"]', '诗', 'shi', '', NULL, '題東谿公幽居 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87cd9170-3349-46b0-925a-86cf2a31ad71', '嘲魯儒', '嘲魯儒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯叟談五經，白髮死章句。","問以經濟策，茫如墜煙霧。","足著遠遊履，首戴方山巾。","緩步從直道，未行先起塵。","秦家丞相府，不重褒衣人。","君非叔孫通，與我本殊倫。","時事且未達，歸耕汶水濱。"]', '["魯叟談五經，白髮死章句。","问以經濟策，茫如墜煙霧。","足著远游履，首戴方山巾。","緩步從直道，未行先起塵。","秦家丞相府，不重褒衣人。","君非叔孫通，與我本殊倫。","时事且未達，归耕汶水濱。"]', '诗', 'shi', '', NULL, '嘲魯儒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd0ce687-7545-4e77-addc-0badaf6fb9ec', '懼讒', '懼讒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["二桃殺三士，詎假劒如霜。","衆女妬蛾眉，雙花競春芳。","魏姝信鄭褏，掩袂對懷王。","一惑巧言子，朱顏成死傷。","行將泣團扇，戚戚愁人腸。"]', '["二桃殺三士，詎假劒如霜。","衆女妬蛾眉，雙花競春芳。","魏姝信鄭褏，掩袂对懷王。","一惑巧言子，朱顏成死傷。","行將泣團扇，戚戚愁人腸。"]', '诗', 'shi', '', NULL, '懼讒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a511cd4d-868d-4b5e-b5e5-cd1529235db2', '觀獵', '观獵', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["太守耀清威，乘閑弄晚暉。","江沙橫獵騎，山火遶行圍。","箭逐雲鴻落，鷹隨月兔飛。","不知白日暮，歡賞夜方歸。"]', '["太守耀清威，乘闲弄晚暉。","江沙橫獵騎，山火遶行圍。","箭逐云鴻落，鷹隨月兔飞。","不知白日暮，歡賞夜方归。"]', '诗', 'shi', '', NULL, '觀獵 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19caae1a-96be-4c91-8374-126bbca1df8d', '觀胡人吹笛', '观胡人吹笛', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡人吹玉笛，一半是秦聲。","十月吳山曉，梅花落敬亭。","愁聞出塞曲，淚滿逐臣纓。","却望長安道，空懷戀主情。"]', '["胡人吹玉笛，一半是秦声。","十月吳山晓，梅花落敬亭。","愁闻出塞曲，泪满逐臣纓。","却望长安道，空懷戀主情。"]', '诗', 'shi', '', NULL, '觀胡人吹笛 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e98fc4a-b0cd-4259-be02-efd617286a5d', '軍行', '軍行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["騮馬新跨白玉鞍，戰罷沙場月色寒。","城頭鐵鼓聲猶震，匣裏金刀血未乾。"]', '["騮马新跨白玉鞍，戰罷沙場月色寒。","城头鐵鼓声猶震，匣裏金刀血未乾。"]', '诗', 'shi', '', NULL, '軍行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32fdc25f-0345-4675-a120-5ba61540eae0', '從軍行', '從軍行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["百戰沙場碎鐵衣，城南已合數重圍。","突營射殺呼延將，獨領殘兵千騎歸。"]', '["百戰沙場碎鐵衣，城南已合數重圍。","突營射殺呼延將，独領殘兵千騎归。"]', '诗', 'shi', '', NULL, '從軍行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d89382-9b46-4e84-89d2-2b11942f0ed9', '平虜將軍妻', '平虜將軍妻', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["平虜將軍婦，入門二十年。","君心自有悅，妾寵豈能專。","出解牀前帳，行吟道上篇。","古人不唾井，莫忘昔纏綿。"]', '["平虜將軍婦，入门二十年。","君心自有悅，妾寵豈能專。","出解牀前帳，行吟道上篇。","古人不唾井，莫忘昔纏綿。"]', '诗', 'shi', '', NULL, '平虜將軍妻 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4838bc46-446b-44cb-8296-29eed12cf343', '春夜洛城聞笛', '春夜洛城闻笛', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["誰家玉笛暗飛聲，散入春風滿洛城。","此夜曲中聞折柳，何人不起故園情。"]', '["誰家玉笛暗飞声，散入春风满洛城。","此夜曲中闻折柳，何人不起故园情。"]', '诗', 'shi', '', NULL, '春夜洛城聞笛 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61347ec6-8ecb-4d4f-b4bc-a38bafdd2bb4', '嵩山採菖蒲者', '嵩山採菖蒲者', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["神仙多古貌，雙耳下垂肩。","嵩嶽逢漢武，疑是九疑仙。","我來採菖蒲，服食可延年。","言終忽不見，滅影入雲烟。","喻帝竟莫悟，終歸茂陵田。"]', '["神仙多古貌，雙耳下垂肩。","嵩嶽逢漢武，疑是九疑仙。","我来採菖蒲，服食可延年。","言終忽不见，滅影入云烟。","喻帝竟莫悟，終归茂陵田。"]', '诗', 'shi', '', NULL, '嵩山採菖蒲者 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96890538-3448-4e3a-8923-333c8198cbdd', '金陵聽韓侍御吹笛', '金陵听韓侍御吹笛', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["韓公吹玉笛，倜儻流英音。","風吹繞鍾山，萬壑皆龍吟。","王子停鳳管，師襄掩瑤琴。","餘韻度江去，天涯安可尋。"]', '["韓公吹玉笛，倜儻流英音。","风吹繞鍾山，万壑皆龙吟。","王子停鳳管，師襄掩瑤琴。","餘韻度江去，天涯安可尋。"]', '诗', 'shi', '', NULL, '金陵聽韓侍御吹笛 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8404ac71-5739-4644-b9ff-b5f7ae31806b', '流夜郎聞酺不預', '流夜郎闻酺不預', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["北闕聖人歌太康，南冠君子竄遐荒。","漢酺聞奏鈞天樂，願得風吹到夜郎。"]', '["北闕聖人歌太康，南冠君子竄遐荒。","漢酺闻奏鈞天乐，願得风吹到夜郎。"]', '诗', 'shi', '', NULL, '流夜郎聞酺不預 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deffd343-83b3-4a8f-9c8e-296b88f888d2', '放後遇恩不霑', '放後遇恩不霑', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天作雲與雷，霈然德澤開。","東風日本至，白雉越裳來。","獨棄長沙國，三年未許回。","何時入宣室，更問洛陽才。"]', '["天作云與雷，霈然德澤开。","东风日本至，白雉越裳来。","独棄长沙国，三年未許回。","何时入宣室，更问洛陽才。"]', '诗', 'shi', '', NULL, '放後遇恩不霑 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df7e8d1d-50ab-40be-8e0c-f2b082fe6e7c', '宣城見杜鵑花', '宣城见杜鵑花', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蜀國曾聞子規鳥，宣城還見杜鵑花。","一呌一迴腸一斷，三春三月憶三巴。"]', '["蜀国曾闻子規鸟，宣城還见杜鵑花。","一呌一迴腸一斷，三春三月憶三巴。"]', '诗', 'shi', '', NULL, '宣城見杜鵑花 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f4daad-aab2-4c61-ad45-a261e6b0735d', '白田馬上聞鶯', '白田马上闻鶯', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃鸝啄紫椹，五月鳴桑枝。","我行不記日，誤作陽春時。","蠶老客未歸，白田已繰絲。","驅馬又前去，捫心空自悲。"]', '["黄鸝啄紫椹，五月鳴桑枝。","我行不記日，誤作陽春时。","蠶老客未归，白田已繰絲。","驱马又前去，捫心空自悲。"]', '诗', 'shi', '', NULL, '白田馬上聞鶯 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05ab8907-1e1b-4f9b-932f-5ca1444adc1f', '三五七言', '三五七言', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秋風清，秋月明。","落葉聚還散，寒鴉棲復驚。","相思相見知何日，此時此夜難爲情。"]', '["秋风清，秋月明。","落葉聚還散，寒鴉棲复驚。","相思相见知何日，此时此夜难爲情。"]', '诗', 'shi', '', NULL, '三五七言 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54435974-70d8-48c1-bbc6-21344c4d6b20', '雜詩', '杂诗', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白日與明月，晝夜尚不閑。","況爾悠悠人，安得久世間。","傳聞海水上，乃有蓬萊山。","玉樹生綠葉，靈仙每登攀。","一食駐玄髮，再食留紅顏。","吾欲從此去，去之無時還。"]', '["白日與明月，晝夜尚不闲。","況爾悠悠人，安得久世间。","傳闻海水上，乃有蓬萊山。","玉樹生綠葉，靈仙每登攀。","一食駐玄髮，再食留紅顏。","吾欲從此去，去之無时還。"]', '诗', 'shi', '', NULL, '雜詩 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dd9396f-141b-4899-a1f1-1d3bcd890d3c', '寄遠十一首 一', '寄远十一首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三鳥別王母，銜書來見過。","腸斷若剪弦，其如愁思何。","遙知玉窗裏，纖手弄雲和。","奏曲有深意，青松交女蘿。","寫水山井中，同泉豈殊波。","秦心與楚恨，皎皎爲誰多。"]', '["三鸟別王母，銜书来见過。","腸斷若剪弦，其如愁思何。","遙知玉窗裏，纖手弄云和。","奏曲有深意，青松交女蘿。","寫水山井中，同泉豈殊波。","秦心與楚恨，皎皎爲誰多。"]', '诗', 'shi', '', NULL, '寄遠十一首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('660a2210-b61c-4742-8bc9-a71fa887b61e', '寄遠十一首 二', '寄远十一首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["青樓何所在，乃在碧雲中。","寶鏡挂秋水，羅衣輕春風。","新妝坐落日，悵望金屏空。","念此送短書，願因雙飛鴻。"]', '["青楼何所在，乃在碧云中。","寶镜挂秋水，羅衣轻春风。","新妝坐落日，悵望金屏空。","念此送短书，願因雙飞鴻。"]', '诗', 'shi', '', NULL, '寄遠十一首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe47df60-2cf0-410a-b638-e976c5c1b368', '寄遠十一首 三', '寄远十一首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["本作一行書，殷勤道相憶。","一行復一行，滿紙情何極。","瑤臺有黃鶴，爲報青樓人。","朱顏凋落盡，白髮一何新。","自知未應還，離居經三春。","桃李今若爲，當窗發光彩。","莫使香風飄，留與紅芳待。"]', '["本作一行书，殷勤道相憶。","一行复一行，满紙情何極。","瑤台有黄鹤，爲報青楼人。","朱顏凋落尽，白髮一何新。","自知未應還，離居經三春。","桃李今若爲，當窗發光彩。","莫使香风飄，留與紅芳待。"]', '诗', 'shi', '', NULL, '寄遠十一首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20dc3129-f969-4f7a-8eb2-d323ea564470', '寄遠十一首 四', '寄远十一首 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉[筯]落春鏡，坐愁湖陽水。","聞與陰麗華，風煙接鄰里。","青春已復過，白日忽相催。","但恐荷花晚，令人意已摧。","相思不惜夢，日夜向陽臺。"]', '["玉[筯]落春镜，坐愁湖陽水。","闻與陰丽华，风煙接鄰里。","青春已复過，白日忽相催。","但恐荷花晚，令人意已摧。","相思不惜梦，日夜向陽台。"]', '诗', 'shi', '', NULL, '寄遠十一首 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da621f92-7f9f-46c5-a83f-6f80153a8fea', '寄遠十一首 五', '寄远十一首 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遠憶巫山陽，花明淥江暖。","躊躇未得往，淚向南雲滿。","春風復無情，吹我夢魂斷。","不見眼中人，天長音信短。"]', '["远憶巫山陽，花明淥江暖。","躊躇未得往，泪向南云满。","春风复無情，吹我梦魂斷。","不见眼中人，天长音信短。"]', '诗', 'shi', '', NULL, '寄遠十一首 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0c3d026-26c4-4597-939a-b3e18d91cc05', '寄遠十一首 六', '寄远十一首 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["陽臺隔楚水，春草生黃河。","相思無日夜，浩蕩若流波。","流波向海去，欲見終無因。","遙將一點淚，遠寄如花人。"]', '["陽台隔楚水，春草生黄河。","相思無日夜，浩蕩若流波。","流波向海去，欲见終無因。","遙將一点泪，远寄如花人。"]', '诗', 'shi', '', NULL, '寄遠十一首 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90cfd7af-86b5-4c1d-9aa2-7a1bbed6ade5', '寄遠十一首 七', '寄远十一首 七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["妾在舂陵東，君居漢江島。","一日望花光，往來成白道。","一爲雲雨別，此地生秋草。","秋草秋蛾飛，相思愁落暉。","何由一相見，滅燭解羅衣。"]', '["妾在舂陵东，君居漢江島。","一日望花光，往来成白道。","一爲云雨別，此地生秋草。","秋草秋蛾飞，相思愁落暉。","何由一相见，滅燭解羅衣。"]', '诗', 'shi', '', NULL, '寄遠十一首 七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d612da26-bd76-45f8-b159-77c1c8d734af', '寄遠十一首 八', '寄远十一首 八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["憶昨東園桃李紅碧枝，與君此時初別離。","金瓶落井無消息，令人行歎復坐思。","坐思行歎成楚越，春風玉顏畏銷歇。","碧窗紛紛下落花，青樓寂寂空明月。","兩不見，但相思，空留錦字表心素，至今緘愁不忍窺。"]', '["憶昨东园桃李紅碧枝，與君此时初別離。","金瓶落井無消息，令人行歎复坐思。","坐思行歎成楚越，春风玉顏畏銷歇。","碧窗紛紛下落花，青楼寂寂空明月。","兩不见，但相思，空留錦字表心素，至今緘愁不忍窺。"]', '诗', 'shi', '', NULL, '寄遠十一首 八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0904fc8b-9caa-4976-aa52-40ea67073a4a', '寄遠十一首 九', '寄远十一首 九', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長短春草綠，緣階如有情。","卷施心獨苦，抽却死還生。","覩物知妾意，希君種後庭。","閑時當採掇，念此莫相輕。"]', '["长短春草綠，緣階如有情。","卷施心独苦，抽却死還生。","覩物知妾意，希君種後庭。","闲时當採掇，念此莫相轻。"]', '诗', 'shi', '', NULL, '寄遠十一首 九 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ffd46bb-4dcf-451d-9b4d-9a41578572ba', '寄遠十一首 十', '寄远十一首 十', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["魯縞如玉霜，筆題月氏書。","寄書白鸚鵡，西海慰離居。","行數雖不多，字字有委曲。","天末如見之，開緘淚相續。","淚盡恨轉深，千里同此心。","相思千萬里，一書值千金。"]', '["魯縞如玉霜，笔題月氏书。","寄书白鸚鵡，西海慰離居。","行數雖不多，字字有委曲。","天末如见之，开緘泪相續。","泪尽恨轉深，千里同此心。","相思千万里，一书值千金。"]', '诗', 'shi', '', NULL, '寄遠十一首 十 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2f7e2e-8dde-49a9-ab92-91653000dc37', '寄遠十一首 十一', '寄远十一首 十一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["愛君芙蓉嬋娟之豔色，色可餐兮難再得。","憐君冰玉清逈之明心，情不極兮意已深。","朝共琅玕之綺食，夜同鴛鴦之錦衾。","恩情婉孌忽爲別，使人莫錯亂愁心。","亂愁心，涕如雪，寒燈厭夢魂欲絕。","覺來相思生白髮，盈盈漢水若可越。","可惜凌波步羅韤，美人美人兮歸去來，莫作朝雲暮雨兮飛陽臺。"]', '["愛君芙蓉嬋娟之豔色，色可餐兮难再得。","怜君冰玉清逈之明心，情不極兮意已深。","朝共琅玕之綺食，夜同鴛鴦之錦衾。","恩情婉孌忽爲別，使人莫錯亂愁心。","亂愁心，涕如雪，寒灯厭梦魂欲絕。","覺来相思生白髮，盈盈漢水若可越。","可惜凌波步羅韤，美人美人兮归去来，莫作朝云暮雨兮飞陽台。"]', '诗', 'shi', '', NULL, '寄遠十一首 十一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5950085-e09e-4d68-b199-e81bb0d25633', '長信宮', '长信宮', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月皎昭陽殿，霜清長信宮。","天行乘玉輦，飛燕與君同。","別有歡娛處，承恩樂未窮。","誰憐團扇妾，獨坐怨秋風。"]', '["月皎昭陽殿，霜清长信宮。","天行乘玉輦，飞燕與君同。","別有歡娛处，承恩乐未窮。","誰怜團扇妾，独坐怨秋风。"]', '诗', 'shi', '', NULL, '長信宮 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f89038d8-0672-4589-8c23-2d75940047cd', '長門怨二首 一', '长门怨二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天迴北斗挂西樓，金屋無人螢火流。","月光欲到長門殿，別作深宮一段愁。"]', '["天迴北斗挂西楼，金屋無人螢火流。","月光欲到长门殿，別作深宮一段愁。"]', '诗', 'shi', '', NULL, '長門怨二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad2c3b5-e54b-4e2a-9261-e258ef34a686', '長門怨二首 二', '长门怨二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桂殿長愁不記春，黃金四屋起秋塵。","夜懸明鏡青天上，獨照長門宮裏人。"]', '["桂殿长愁不記春，黄金四屋起秋塵。","夜懸明镜青天上，独照长门宮裏人。"]', '诗', 'shi', '', NULL, '長門怨二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c83b82eb-93fa-4a3d-af84-616a6992b0f3', '春怨', '春怨', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白馬金羈遼海東，羅帷繡被臥春風。","落月低軒窺燭盡，飛花入戶笑牀空。"]', '["白马金羈遼海东，羅帷繡被臥春风。","落月低軒窺燭尽，飞花入戶笑牀空。"]', '诗', 'shi', '', NULL, '春怨 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9840849f-4221-4fd0-8e95-c0bb33d3a956', '代贈遠', '代贈远', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["妾本洛陽人，狂夫幽燕客。","渴飲易水波，由來多感激。","胡馬西北馳，香騣搖綠絲。","鳴鞭從此去，逐虜蕩邊陲。","昔去有好言，不言久離別。","燕支多美女，走馬輕風雪。","見此不記人，恩情雲雨絕。","啼流玉筯盡，坐恨金閨切。","織錦作短書，腸隨回文結。","相思欲有寄，恐君不見察。","焚之揚其灰，手跡自此滅。"]', '["妾本洛陽人，狂夫幽燕客。","渴饮易水波，由来多感激。","胡马西北驰，香騣搖綠絲。","鳴鞭從此去，逐虜蕩邊陲。","昔去有好言，不言久離別。","燕支多美女，走马轻风雪。","见此不記人，恩情云雨絕。","啼流玉筯尽，坐恨金閨切。","织錦作短书，腸隨回文結。","相思欲有寄，恐君不见察。","焚之揚其灰，手跡自此滅。"]', '诗', 'shi', '', NULL, '代贈遠 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4753cb69-c4e4-454f-b86d-828d244405c5', '陌上贈美人', '陌上贈美人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["駿馬驕行踏落花，垂鞭直拂五雲車。","美人一笑褰珠箔，遙指紅樓是妾家。"]', '["駿马驕行踏落花，垂鞭直拂五云车。","美人一笑褰珠箔，遙指紅楼是妾家。"]', '诗', 'shi', '', NULL, '陌上贈美人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03e17c9d-eaa8-41bd-8532-03b03f509941', '閨情', '閨情', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["流水去絕國，浮雲辭故關。","水或戀前浦，雲猶歸舊山。","恨君流沙去，棄妾漁陽間。","玉筯夜垂流，雙雙落朱顏。","黃鳥坐相悲，綠楊誰更攀。","織錦心草草，挑燈淚斑斑。","窺鏡不自識，況乃狂夫還。"]', '["流水去絕国，浮云辞故关。","水或戀前浦，云猶归旧山。","恨君流沙去，棄妾漁陽间。","玉筯夜垂流，雙雙落朱顏。","黄鸟坐相悲，綠楊誰更攀。","织錦心草草，挑灯泪斑斑。","窺镜不自識，況乃狂夫還。"]', '诗', 'shi', '', NULL, '閨情 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc78ce7-25e1-4171-91fd-879df8e705bc', '代別情人', '代別情人', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["清水本不動，桃花發岸傍。","桃花弄水色，波蕩搖春光。","我悅子容豔，子傾我文章。","風吹綠琴去，曲度紫鴛鴦。","昔作一水魚，今成兩枝鳥。","哀哀長雞鳴，夜夜達五曉。","起折相思樹，歸贈知寸心。","覆水不可收，行雲難重尋。","天涯有度鳥，莫絕瑤華音。"]', '["清水本不动，桃花發岸傍。","桃花弄水色，波蕩搖春光。","我悅子容豔，子傾我文章。","风吹綠琴去，曲度紫鴛鴦。","昔作一水鱼，今成兩枝鸟。","哀哀长雞鳴，夜夜達五晓。","起折相思樹，归贈知寸心。","覆水不可收，行云难重尋。","天涯有度鸟，莫絕瑤华音。"]', '诗', 'shi', '', NULL, '代別情人 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd315fe-e269-45bc-ae28-ed1a7b9ede04', '代秋情', '代秋情', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["幾日相別離，門前生穭葵。","寒蟬聒梧桐，日夕長鳴悲。","白露濕螢火，清霜凌兔絲。","空掩紫羅袂，長啼無盡時。"]', '["幾日相別離，门前生穭葵。","寒蟬聒梧桐，日夕长鳴悲。","白露濕螢火，清霜凌兔絲。","空掩紫羅袂，长啼無尽时。"]', '诗', 'shi', '', NULL, '代秋情 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e564d728-17e6-40e0-8e90-4607f683345f', '對酒', '对酒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["蒲萄酒，金叵羅，吳姬十五細馬馱。","青黛畫眉紅錦靴，道字不正嬌唱歌。","玳瑁筵中懷裏醉，芙蓉帳底奈君何。"]', '["蒲萄酒，金叵羅，吳姬十五細马馱。","青黛畫眉紅錦靴，道字不正嬌唱歌。","玳瑁筵中懷裏醉，芙蓉帳底奈君何。"]', '诗', 'shi', '', NULL, '對酒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a532137-253d-4ba7-bb5b-4f7b929171ac', '怨情', '怨情', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["新人如花雖可寵，故人似玉由來重。","花性飄揚不自持，玉心皎潔終不移。","故人昔新今尚故，還見新人有故時。","請看陳后黃金屋，寂寂珠簾生網絲。"]', '["新人如花雖可寵，故人似玉由来重。","花性飄揚不自持，玉心皎潔終不移。","故人昔新今尚故，還见新人有故时。","請看陳后黄金屋，寂寂珠簾生網絲。"]', '诗', 'shi', '', NULL, '怨情 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('784b5a89-8c57-4d96-91e6-c5adad655e99', '湖邊採蓮婦', '湖邊採蓮婦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["小姑織白紵，未解將人語。","大嫂採芙蓉，溪湖千萬重。","長兄行不在，莫使外人逢。","願學秋胡婦，貞心比古松。"]', '["小姑织白紵，未解將人語。","大嫂採芙蓉，溪湖千万重。","长兄行不在，莫使外人逢。","願学秋胡婦，貞心比古松。"]', '诗', 'shi', '', NULL, '湖邊採蓮婦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e72306-f41c-4621-a925-83bab7f9d76e', '怨情', '怨情', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["美人捲珠簾，深坐顰蛾眉。","但見淚痕濕，不知心恨誰。"]', '["美人捲珠簾，深坐顰蛾眉。","但见泪痕濕，不知心恨誰。"]', '诗', 'shi', '', NULL, '怨情 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c5e9539-ad36-48ff-87ac-3b5568434b55', '代寄情楚詞體', '代寄情楚词體', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君不來兮，徒蓄怨積思而孤吟。","雲陽一去已遠，隔巫山綠水之沈沈。","留餘香兮染繡被，夜欲寢兮愁人心。","朝馳余馬於青樓，怳若空而夷猶。","浮雲深兮不得語，却惆悵而懷憂。","使青鳥兮銜書，恨獨宿兮傷離居。","何無情而雨絕，夢雖往而交疎。","橫流涕而長嗟，折芳洲之瑤華。","送飛鳥以極目，怨夕陽之西斜。","願爲連根同死之秋草，不作飛空之落花。"]', '["君不来兮，徒蓄怨積思而孤吟。","云陽一去已远，隔巫山綠水之沈沈。","留餘香兮染繡被，夜欲寢兮愁人心。","朝驰余马於青楼，怳若空而夷猶。","浮云深兮不得語，却惆悵而懷憂。","使青鸟兮銜书，恨独宿兮傷離居。","何無情而雨絕，梦雖往而交疎。","橫流涕而长嗟，折芳洲之瑤华。","送飞鸟以極目，怨夕陽之西斜。","願爲連根同死之秋草，不作飞空之落花。"]', '诗', 'shi', '', NULL, '代寄情楚詞體 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e13e252b-786b-46fd-bf7e-495708f63b57', '學古思邊', '学古思邊', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["銜悲上隴首，腸斷不見君。","流水若有情，幽哀從此分。","蒼茫愁邊色，惆悵落日曛。","山外接遠天，天際復有雲。","白雁從中來，飛鳴苦難聞。","足繫一書札，寄言難離羣。","離羣心斷絕，十見花成雪。","胡地無春暉，征人行不歸。","相思杳如夢，珠淚濕羅衣。"]', '["銜悲上隴首，腸斷不见君。","流水若有情，幽哀從此分。","蒼茫愁邊色，惆悵落日曛。","山外接远天，天際复有云。","白雁從中来，飞鳴苦难闻。","足繫一书札，寄言难離羣。","離羣心斷絕，十见花成雪。","胡地無春暉，征人行不归。","相思杳如梦，珠泪濕羅衣。"]', '诗', 'shi', '', NULL, '學古思邊 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da2cf966-4604-454f-9297-b7acd57a677a', '思邊', '思邊', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["去年何時君別妾，南園綠草飛蝴蝶。","今歲何時妾憶君，西山白雪暗晴雲。","玉關去此三千里，欲寄音書那可聞。"]', '["去年何时君別妾，南园綠草飞蝴蝶。","今歲何时妾憶君，西山白雪暗晴云。","玉关去此三千里，欲寄音书那可闻。"]', '诗', 'shi', '', NULL, '思邊 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4e1236-ae4e-40dd-9790-2183767e57ee', '口號吳王美人半醉', '口號吳王美人半醉', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["風動荷花水殿香，姑蘇臺上宴吳王。","西施醉舞嬌無力，笑倚東窗白玉牀。"]', '["风动荷花水殿香，姑蘇台上宴吳王。","西施醉舞嬌無力，笑倚东窗白玉牀。"]', '诗', 'shi', '', NULL, '口號吳王美人半醉 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ae4b43-a036-4895-bfd8-7a1f741ced8e', '代美人愁鏡二首 一', '代美人愁镜二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["明明金鵲鏡，了了玉臺前。","拂拭交冰月，光輝何清圓。","紅顏老昨日，白髮多去年。","鉛粉坐相誤，照來空淒然。"]', '["明明金鵲镜，了了玉台前。","拂拭交冰月，光輝何清圓。","紅顏老昨日，白髮多去年。","鉛粉坐相誤，照来空淒然。"]', '诗', 'shi', '', NULL, '代美人愁鏡二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('441198ac-3221-4f13-b2d2-6c5f5c755333', '代美人愁鏡二首 二', '代美人愁镜二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["美人贈此盤龍之寶鏡，燭我金縷之羅衣。","時將紅袖拂明月，爲惜普照之餘暉。","影中金鵲飛不滅，臺下青鸞思獨絕。","藳砧一別若箭弦，去有日，來無年。","狂風吹却妾心斷，玉筯幷墮菱花前。"]', '["美人贈此盤龙之寶镜，燭我金縷之羅衣。","时將紅袖拂明月，爲惜普照之餘暉。","影中金鵲飞不滅，台下青鸾思独絕。","藳砧一別若箭弦，去有日，来無年。","狂风吹却妾心斷，玉筯幷墮菱花前。"]', '诗', 'shi', '', NULL, '代美人愁鏡二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f12f256-2436-48a6-bbe2-58e47c9b7cb4', '贈段七娘', '贈段七娘', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["羅韤凌波生網塵，那能得計訪情親。","千杯綠酒何辭醉，一面紅妝惱殺人。"]', '["羅韤凌波生網塵，那能得計訪情親。","千杯綠酒何辞醉，一面紅妝惱殺人。"]', '诗', 'shi', '', NULL, '贈段七娘 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d7454d0-5261-48f8-b97b-b68bdc4b03a1', '別內赴徵三首 一', '別內赴徵三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["王命三徵去未還，明朝離別出吳關。","白玉高樓看不見，相思須上望夫山。"]', '["王命三徵去未還，明朝離別出吳关。","白玉高楼看不见，相思須上望夫山。"]', '诗', 'shi', '', NULL, '別內赴徵三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca2f34d-ed6a-40ee-8f75-b74e4e5ccf39', '別內赴徵三首 二', '別內赴徵三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["出門妻子強牽衣，問我西行幾日歸。","歸時儻佩黃金印，莫學蘇秦不下機。"]', '["出门妻子強牽衣，问我西行幾日归。","归时儻佩黄金印，莫学蘇秦不下機。"]', '诗', 'shi', '', NULL, '別內赴徵三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c89e422-d326-433c-b9e8-d7d8be805866', '別內赴徵三首 三', '別內赴徵三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["翡翠爲樓金作梯，誰人獨宿倚門啼。","夜坐寒燈連曉月，行行淚盡楚關西。"]', '["翡翠爲楼金作梯，誰人独宿倚门啼。","夜坐寒灯連晓月，行行泪尽楚关西。"]', '诗', 'shi', '', NULL, '別內赴徵三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8900ac3-78df-4ace-a19c-4d69aacc74e6', '秋浦寄內', '秋浦寄內', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["我今尋陽去，辭家千里餘。","結荷倦水宿，却寄大雷書。","雖不同辛苦，愴離各自居。","我自入秋浦，三年北信疎。","紅顏愁落盡，白髮不能除。","有客自梁苑，手攜五色魚。","開魚得錦字，歸問我何如。","江山雖道阻，意合不爲殊。"]', '["我今尋陽去，辞家千里餘。","結荷倦水宿，却寄大雷书。","雖不同辛苦，愴離各自居。","我自入秋浦，三年北信疎。","紅顏愁落尽，白髮不能除。","有客自梁苑，手携五色鱼。","开鱼得錦字，归问我何如。","江山雖道阻，意合不爲殊。"]', '诗', 'shi', '', NULL, '秋浦寄內 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a78794b-8968-4fd0-9780-d10e7066ff9e', '自代內贈', '自代內贈', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["寶刀截流水，無有斷絕時。","妾意逐君行，纏綿亦如之。","別來門前草，秋巷春轉碧。","埽盡更還生，萋萋滿行跡。","鳴鳳始相得，雄驚雌各飛。","遊雲落何山，一往不見歸。","估客發大樓，知君在秋浦。","梁苑空錦衾，陽臺夢行雨。","妾家三作相，失勢去西秦。","猶有舊歌管，淒清聞四鄰。","曲度入紫雲，啼無眼中人。","妾似井底桃，開花向誰笑。","君如天上月，不肯一迴照。","窺鏡不自識，別多憔悴深。","安得秦吉了，爲人道寸心。"]', '["寶刀截流水，無有斷絕时。","妾意逐君行，纏綿亦如之。","別来门前草，秋巷春轉碧。","埽尽更還生，萋萋满行跡。","鳴鳳始相得，雄驚雌各飞。","游云落何山，一往不见归。","估客發大楼，知君在秋浦。","梁苑空錦衾，陽台梦行雨。","妾家三作相，失勢去西秦。","猶有旧歌管，淒清闻四鄰。","曲度入紫云，啼無眼中人。","妾似井底桃，开花向誰笑。","君如天上月，不肯一迴照。","窺镜不自識，別多憔悴深。","安得秦吉了，爲人道寸心。"]', '诗', 'shi', '', NULL, '自代內贈 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2511ca31-bf64-4c30-b4ee-7d4cfa5476d9', '秋浦感主人歸燕寄內', '秋浦感主人归燕寄內', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["霜凋楚關木，始知殺氣嚴。","寥寥金天廓，婉婉綠紅潛。","胡燕別主人，雙雙語前簷。","三飛四迴顧，欲去復相瞻。","豈不戀華屋，終然謝珠簾。","我不及此鳥，遠行歲已淹。","寄書道中歎，淚下不能緘。"]', '["霜凋楚关木，始知殺氣嚴。","寥寥金天廓，婉婉綠紅潛。","胡燕別主人，雙雙語前簷。","三飞四迴顧，欲去复相瞻。","豈不戀华屋，終然謝珠簾。","我不及此鸟，远行歲已淹。","寄书道中歎，泪下不能緘。"]', '诗', 'shi', '', NULL, '秋浦感主人歸燕寄內 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb13388b-3d3a-4104-8687-5948a47849a1', '送內尋廬山女道士李騰空二首 一', '送內尋廬山女道士李腾空二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君尋騰空子，應到碧山家。","水舂雲母確，風埽石楠花。","若愛幽居好，相邀弄紫霞。"]', '["君尋腾空子，應到碧山家。","水舂云母確，风埽石楠花。","若愛幽居好，相邀弄紫霞。"]', '诗', 'shi', '', NULL, '送內尋廬山女道士李騰空二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e581a851-f222-4cce-8a41-f194e30cf044', '送內尋廬山女道士李騰空二首 二', '送內尋廬山女道士李腾空二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["多君相門女，學道愛神仙。","素手掬青靄，羅衣曳紫煙。","一往屏風疊，乘鸞着玉鞭。"]', '["多君相门女，学道愛神仙。","素手掬青靄，羅衣曳紫煙。","一往屏风叠，乘鸾着玉鞭。"]', '诗', 'shi', '', NULL, '送內尋廬山女道士李騰空二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60ec5bb3-629e-402c-8481-89828f960481', '贈內', '贈內', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["三百六十日，日日醉如泥。","雖爲李白婦，何異太常妻。"]', '["三百六十日，日日醉如泥。","雖爲李白婦，何異太常妻。"]', '诗', 'shi', '', NULL, '贈內 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('730675ae-6683-4433-9313-b292eab2ac63', '在潯陽非所寄內', '在潯陽非所寄內', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["聞難知慟哭，行啼入府中。","多君同蔡琰，流淚請曹公。","知登吳章嶺，昔與死無分。","崎嶇行石道，外折入青雲。","相見若悲歌，哀聲那可聞。"]', '["闻难知慟哭，行啼入府中。","多君同蔡琰，流泪請曹公。","知登吳章嶺，昔與死無分。","崎嶇行石道，外折入青云。","相见若悲歌，哀声那可闻。"]', '诗', 'shi', '', NULL, '在潯陽非所寄內 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac279462-e1b7-426c-85ff-7ef1cb56a2b2', '南流夜郎寄內', '南流夜郎寄內', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["夜郎天外怨離居，明月樓中音信疎。","北雁春歸看欲盡，南來不得豫章書。"]', '["夜郎天外怨離居，明月楼中音信疎。","北雁春归看欲尽，南来不得豫章书。"]', '诗', 'shi', '', NULL, '南流夜郎寄內 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f84a2b0-3d36-4a6a-8df1-89c5d0936493', '越女詞五首 一', '越女词五首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長干吳兒女，眉目豔新月。","屐上足如霜，不着鴉頭襪。"]', '["长干吳兒女，眉目豔新月。","屐上足如霜，不着鴉头襪。"]', '诗', 'shi', '', NULL, '越女詞五首 一 李白 shi');
